-- ============================================================
-- Ereb3g (7/7) — DB kontentinin AR tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6170 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ربما يكون طفلكِ قد اتخذ وضعية الولادة اعتبارًا من هذا الأسبوع. فعادةً ما يبدأ الأطفال باتخاذ الوضعية المناسبة للولادة بعد دخول الأسبوع 32. وعلى الرغم من أن هذا هو التوقيت المتوسط، فقد يحدث ذلك قبل 4 أسابيع أو حتى في أثناء الولادة. وفي وضعية الولادة، يكون رأس طفلكِ إلى الأسفل، ومقعدته أسفل حجابكِ الحاجز، وساقاه مثنيتين باتجاه بطنه، ويداه متقاطعتين فوق صدره. وتُسمى وضعية الولادة الطبيعية هذه بالمجيء الرأسي أو وضعية الرأس إلى الأسفل. >:P ولكي تتم الولادة من الناحية الفسيولوجية، يجب أن يستقر الرأس بطريقة محددة داخل عظام الحوض. وفي وضعية الولادة، يكون الجزء الذي يتقدم أولًا هو النتوء الموجود في مؤخرة رأس طفلكِ. وبذلك يدخل رأسه إلى الحوض العظمي بأصغر قطر ممكن.'), baby_message_ar = COALESCE(baby_message_ar, 'أحصل على مناعتكِ! 🛡️ ماما، تنتقل إليّ عبر المشيمة "أجسام مضادة" منكِ، وهي الجنود الذين يحاربون الجراثيم. وهذا هو لقاحي الأول. عندما أولد، ستكون مناعتي الذاتية ضعيفة، لكن الحماية التي تمنحينني إياها ستقيني من الأمراض خلال الأشهر الأولى. أنتِ ملاكي الحارس!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'قد يظل عسر الهضم والإمساك يسببان لكِ مشكلة. فبسبب هرمون البروجسترون وضغط الرحم على الأمعاء، يعمل الجهاز الهضمي ببطء. ومن المهم شرب الكثير من الماء وتناول الأطعمة الغنية بالألياف.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تناولي وجبات صغيرة ومتكررة لتخفيف حرقة المعدة. كما أن الاستلقاء على جانبكِ الأيسر عند النوم يسهّل تنفسكِ ويحسّن تدفق الدم إلى طفلكِ. وإذا لم تكوني قد بدأتِ بعد، فابدئي بالتخطيط لما ستضعينه في حقيبة المستشفى. ولا تنسي أن تستريحي وألا ترهقي نفسكِ كثيرًا!') WHERE id = '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يتراوح طول طفلكِ في هذه المرحلة بين 40-48 سم. وتحدث الزيادة في الطول أساسًا نتيجة استطالة العظام. واستطالة العظام عملية تبدأ لدى طفلكِ في الرحم مع نهاية المرحلة الجنينية، وتستمر منذ الولادة حتى نهاية مرحلة المراهقة. وقد تتسارع هذه الاستطالة أو تتباطأ من فترة إلى أخرى. وتختلف فترات النمو بين الذكور والإناث. فحتى عمر سنتين، يمر الأطفال الذكور بمرحلة نمو في الطول أسرع من الإناث. أما الإناث، فابتداءً من عمر سنتين وخلال مرحلة الطفولة وحتى المراهقة، يُكملن مرحلة الاستطالة هذه في وقت أبكر من الذكور. ويكون هذا الاختلاف أكثر وضوحًا بين عمر 11-13 عامًا، إذ يُلاحظ عادةً أن الإناث أطول من الذكور. ويختفي هذا الفارق في المتوسط عند عمر 15-16 عامًا، ومع انتهاء مرحلة المراهقة يصبح الذكور أطول من الإناث. وتُعد العوامل الوراثية أهم العوامل المؤثرة في زيادة الطول. وفي هذه المرحلة، يكون الطول الذي سيبلغه طفلكِ عند سن البلوغ محددًا تقريبًا.'), baby_message_ar = COALESCE(baby_message_ar, 'تزداد عظامي صلابة، لكن... 🦴 تزداد عظام جسمي صلابة، إلا أن عظام جمجمتي لم تلتحم بعد وما زالت لينة. لماذا؟ لأن رأسي يحتاج عند الولادة إلى الانضغاط قليلًا وتغيير شكله حتى يمر عبر قناة الولادة الضيقة. هذه هي خطة الطبيعة المذهلة. وبعد الولادة، سيعود شكل رأسي إلى طبيعته.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'إذا ظهر في المشيمة، التي تنقل الغذاء والأكسجين إلى طفلكِ طوال فترة الحمل، مظهر لامع وأبيض أثناء فحص الموجات فوق الصوتية، فهذا يشير إلى بدء تكلسها.;;;
قد تحدث شيخوخة المشيمة في أي مرحلة من الحمل، لكن احتمال ظهورها يكون أكبر خلال الثلث الأخير. وتُعد العادات الضارة مثل شرب الكحول والتدخين من العوامل التي تسرّع شيخوخة المشيمة. وشيخوخة المشيمة في الأشهر الأخيرة من الحمل حالة غير خطرة، لكنها تتطلب متابعة منتظمة. كذلك، إذا كنتِ تعانين من ارتفاع ضغط الدم، فمن المفيد أن تبقي تحت المراقبة تحسبًا لاحتمال تأثر طفلكِ بهذا التكلس.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تساعد الأطعمة الغنية بالبروبيوتيك، مثل الزبادي الطبيعي والكفير، على تنظيم الجهاز الهضمي. ولتخفيف الإمساك، قد يفيد تناول ملعقة من زيت الزيتون صباحًا أو تناول البرقوق المجفف.') WHERE id = 'ffcf32a2-fefd-4897-8f4a-507b427193a8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتكوّن معظم الهيكل العظمي لطفلكِ في هذه المرحلة من نسيج غضروفي. ومع تقدّم طفلكِ في العمر منذ ولادته، يحلّ النسيج العظمي تدريجيًا محل النسيج الغضروفي الذي يشكّل الجزء الأكبر من الهيكل العظمي. ويستمر ترسّب أملاح الكالسيوم التي تمنح العظام صلابتها في النسيج العظمي حتى نهاية مرحلة المراهقة. وبعد اكتمال التعظّم، يبقى النسيج الغضروفي عند أطراف الأضلاع والأسطح المفصلية وفي القصبة الهوائية والحنجرة وصيوان الأذن وطرف الأنف. كما يساعد العظام على اكتساب المرونة ويسهّل حركة الهيكل العظمي.'), baby_message_ar = COALESCE(baby_message_ar, 'لا يزال رأسي لينًا! 🧠 على الرغم من أن عظام جسمي صلبة، فإن عظام جمجمتي متحركة بما يكفي لتتراكب بعضها فوق بعض. لماذا؟ لأن رأسي سيحتاج إلى أن يصغر قليلًا كي يمر عبر ذلك الممر الضيق عند الولادة. لقد منحتني الطبيعة "خوذة مرنة".'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الشمام'), body_changes_ar = COALESCE(body_changes_ar, 'ربما تكون شكواكِ من الأرق قد وصلت إلى أعلى مستوياتها تقريبًا. فكل من الغثيان وارتجاع حمض المعدة وحرقتها والحاجة المستمرة إلى دخول الحمام وعدم القدرة على الشعور بالراحة بسبب نمو البطن يمكن أن يؤثر بمفرده في جودة نومكِ. ولمساعدتكِ على مقاومة الأرق، خذي حمّامًا سريعًا قبل النوم ليلًا واشربي كوبًا واحدًا من الحليب الدافئ، وتجنّبي الأطعمة الثقيلة والدهنية التي يصعب هضمها، ولا سيما في المساء، وابتعدي عن المشروبات المحتوية على الكافيين مثل الشاي والقهوة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ارفعي ساقيكِ إلى أعلى مرارًا خلال اليوم. وارتدي حذاءً مريحًا أكبر بمقاس واحد أو نعالًا مريحًا. وابتعدي عن الأطعمة المالحة.') WHERE id = '75724f71-0d67-40e0-ac05-b52a8a77f3b7';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يُعد الجهاز البولي لدى طفلكِ أحد أكثر الأجهزة نشاطًا خلال المرحلة الجنينية. وفي هذه المرحلة، تقع الغدة الكظرية على سطح كليته، ويفصل بينهما نسيج دهني. كما يتصل بالكلية عدد كبير من الأوعية الدموية والأوعية اللمفاوية والأعصاب والمسالك البولية عبر المنطقة المقعّرة على جانبيها. وتتكوّن مثانة طفلكِ، وهي بنية تشبه الكيس، بالكامل من العضلات الملساء. وتوجد عند مواضع دخول البول إلى المثانة صمامات تمنع ارتجاعه. وعندما تمتلئ المثانة، ترسل النهايات العصبية الموجودة في جدرانها المتمددة إشارات إلى الدماغ، ما يؤدي إلى انقباض المثانة. وبذلك يشعر طفلكِ بالحاجة إلى التبوّل، ثم يطرح البول عبر الإحليل. وإذا كان طفلكِ ذكرًا، فإن الإحليل يكون مرتبطًا بالجهاز التناسلي الذكري.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتابع الضوء! 🔦 عيناي مفتوحتان وأنظر من حولي. تستجيب حدقتاي للضوء؛ فتضيقان عند التعرض له وتتسعان في الظلام. إن جهازي البصري يعمل. وعندما أولد، سأتمكن من رؤية وجهكِ من مسافة تقارب 20-30 سم (وهي مسافة الرضاعة الطبيعية!).'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الشمام'), body_changes_ar = COALESCE(body_changes_ar, 'قد تكون الاضطرابات الناشئة عن المعدة والأمعاء خلال الحمل أشد بكثير من المعتاد. ولهذا تُعد آلام الغازات مشكلة شائعة جدًا أثناء الحمل. ويرجع احتباس الغازات خلال الحمل بالكامل إلى هرمونات الحمل، ولا سيما هرمون البروجستيرون، الذي يسبب ارتخاء العضلات الملساء في الجهاز الهضمي.;;;
يُعد شاي البابونج مفيدًا جدًا لمشكلات الغازات. ويجب تجنّب الأطعمة الحارة والغنية بالتوابل التي تزيد هذه الأعراض. وإضافةً إلى ذلك، يساعد تجنّب تناول السوائل أثناء الطعام على تقليل الانتفاخ والوقاية من آلام الغازات.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف ضيق التنفس، احرصي على إبقاء ظهركِ مستقيمًا عند الجلوس. ولتقليل تورّم ساقيكِ، اشربي الكثير من الماء واستريحي مع رفع ساقيكِ خلال اليوم. الأرق طبيعي في هذه الفترة، لذا ستمنحكِ قيلولات قصيرة لمدة 15-20 دقيقة خلال اليوم بعض الطاقة. خصّصي لنفسكِ بعض الوقت هذا المساء وأريحي جسمكِ بحمّام دافئ.') WHERE id = '0d05bbb2-bf77-46f6-81b3-38696a1de3f5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اكتمل تكوّن الطبقة المخاطية المؤلفة من خلايا ظهارية على السطح الخارجي لأمعاء طفلكِ. وبفضلها لا تتضرر أمعاؤه نتيجة احتكاكها بالأعضاء الأخرى. وتوجد بعض الأنسجة اللمفاوية في الأمعاء الغليظة. وتساعد الأجسام المضادة التي تنتجها هذه الأنسجة على منع التكاثر المفرط للبكتيريا النافعة التي تعيش في الأمعاء، كما تُبطل مفعول الكائنات الدقيقة الضارة التي تدخل الجسم عن طريق الطعام. وبهذه الطريقة، تُمنع العدوى التي قد تنشأ عنها. وتُنتج البكتيريا الموجودة في الأمعاء فيتامينات لا يستطيع جسم طفلكِ تصنيعها، وأهمها فيتامين K وفيتامينات مجموعة B. كما يضمن امتصاص الماء في الأمعاء الغليظة عدم طرح الماء الذي يحتاج إليه الجسم مع البراز وإعادته إلى الدم. وبعد أن تمتص الأمعاء الدقيقة والغليظة جزيئات الكربوهيدرات والدهون والبروتينات والفيتامينات والمعادن والماء الموجودة في الطعام، تُخزّن الفضلات المتبقية في الأمعاء الغليظة حتى تُطرح عبر فتحة الشرج. ولهذا تؤدي الأمعاء الغليظة أيضًا دور مستودع للفضلات.'), baby_message_ar = COALESCE(baby_message_ar, 'المكان ضيق جدًا! 🏠 ماما، أريد أن أستدير، لكن الجدران تضغط عليّ. أصبحت حركاتي الآن أشبه بـ"الانزلاق" و"الدفع". وعندما أدفع بمرفقي نحو أحد جانبي بطنكِ، ترينه على شكل نتوء. ربّتي عليّ، وسأتراجع.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الشمام'), body_changes_ar = COALESCE(body_changes_ar, 'مع اقترابكِ من نهاية الحمل، ربما أصبحت انقباضاتكِ الكاذبة أكثر شدة. وقد تكون انقباضات الرحم الكاذبة مؤلمة جدًا من حين إلى آخر خلال الأسابيع الأخيرة. وغالبًا ما تختلط هذه الانقباضات، المعروفة باسم انقباضات براكستون هيكس، بانقباضات المخاض الحقيقية. وقد تزداد شدتها، خصوصًا عند الإرهاق أو الوقوف طويلًا أو التعرّض لضربة في منطقة البطن. وإضافةً إلى ذلك، تبدأ هذه الانقباضات في وقت أبكر وتستمر مدة أطول لدى النساء اللاتي سبق لهن الولادة أكثر من مرة. أما النساء اللاتي يخضن حملهن الأول، فتبدأ الانقباضات لديهن في وقت متأخر وتكون الفروق بين مددها أكبر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي شرب الكثير من الماء لتقليل تورّم ساقيكِ، وارفعِي قدميكِ عند الجلوس. واستخدمي فرشاة أسنان ناعمة إذا كانت لثتكِ حساسة. وإذا لم تكوني قد فعلتِ ذلك بعد، فيمكنكِ البدء بغسل وكيّ الملابس الأولى التي سيحتاج إليها طفلكِ. سيساعدكِ هذا النشاط المهدّئ على الاستعداد، كما سيقوّي الرابطة بينكِ وبين طفلكِ.') WHERE id = 'd5a88302-fe21-4399-b36c-3480a294c860';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يؤدي الحبل السري، الذي يعمل كحلقة وصل لتلبية جميع احتياجات طفلكِ، إلى بعض المشكلات في هذه المرحلة من الحمل. ومن بينها التفاف الحبل السري ووجود حبل سري ذي وعاءين دمويين. وقد يشكّل التفاف هذا الحبل، الذي يصل بين المشيمة وسرة طفلكِ، حول عنقه خطرًا.;;;
وكما قد يلتف الحبل السري حول عنق طفلكِ، فقد تتكوّن فيه أيضًا عقدة. تتشكّل بعض العقد أثناء الولادة، بينما تنشأ أخرى خلال الحمل نتيجة حركات طفلكِ. إذا كانت العقدة رخوة، فلا تشكّل خطرًا على طفلكِ. أما إذا كانت محكمة، فقد تؤثر في تدفق الدم من المشيمة إلى طفلكِ وتؤدي إلى نقص الأكسجين. وأكثر علامات التفاف الحبل السري شيوعًا هي ملاحظة انخفاض حركات طفلكِ خلال الأسابيع الأخيرة. وإذا حدثت العقدة أثناء الولادة، فقد تظهر اضطرابات في نبض القلب على جهاز اختبار عدم الإجهاد (NST). ويكون التفاف الحبل السري الرخو أكثر شيوعًا لدى الحوامل اللواتي لديهن كمية كبيرة من السائل الأمنيوسي، لأنه يتيح للطفل حركة أكثر حرية. وفي نحو 1 من كل 2000 ولادة، تتكوّن في الحبل السري عقدة محكمة بما يكفي لتشكّل خطرًا على الطفل.'), baby_message_ar = COALESCE(baby_message_ar, 'مائي يتناقص وأنا أكبر! 💧 كان حوضي واسعًا جدًا في السابق، لكنني الآن أشغل مساحة كبيرة لدرجة أن كمية السائل الأمنيوسي تبدو أقل نسبيًا. أصبحتِ الآن تشعرين بحركاتي بصورة أوضح وأقوى. وقد يتغير شكل بطنكِ عندما أدفع مرفقي باتجاهكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'مع اقترابكِ من نهاية الحمل خلال هذه الأسابيع، ينبغي أن تبدئي التفكير في الطريقة التي ترغبين في أن تتم بها ولادتكِ. تُعد الولادة في الماء من أكثر أنواع الولادة التي خضعت للبحث في السنوات الأخيرة. تُجرى هذه الولادة داخل الماء في حوض أو مغطس مُعدّ خصيصًا لذلك، وتهدف إلى الاستفادة من تأثير الماء المهدئ للتعامل مع تقلصات المخاض براحة أكبر. يساعد الوجود في ماء دافئ أثناء الولادة على استرخاء الجسم وزيادة إفراز هرمون الأوكسيتوسين. ويجعل الأوكسيتوسين المُفرز التقلصات أكثر انتظامًا ويقصّر مدة الولادة. ومن فوائد هذه الطريقة أيضًا أن الماء الدافئ يساعد على إرخاء العضلات والأنسجة، ما يقلل الشعور بالألم والتوتر. ومع ارتخاء عضلات البطن ومنطقة الأربية خصوصًا، يصبح تحمّل التقلصات أسهل بكثير. وهكذا يمكنكِ إتمام ولادتكِ بمشاعر أكثر هدوءًا وإيجابية.;;;
كذلك، عندما يولد طفلكِ، الذي تطوّر طوال فترة الحمل داخل السائل الأمنيوسي، في ماء دافئ، يكون انتقاله إلى العالم الخارجي أكثر لطفًا، ما يحد من تأثره بصدمة الولادة إلى أدنى درجة.;;;
إذا كنتِ ترغبين في الولادة في الماء، فتحققي مما إذا كانت إمكانات المستشفى وظروفه مناسبة لذلك.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي وضع الزيوت المرطبة على بطنكِ، وتجنّبي الحك. إذا تغير لون الإفرازات أو رائحتها، كأن تصبح خضراء أو كريهة الرائحة، فاستشيري الطبيبة أو الطبيب. وقد يمنحكِ استخدام الفوط اليومية مزيدًا من الراحة.') WHERE id = '1071fbaa-eb8a-400f-b713-0a3f36f51bd7';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بفضل انفصال جفنيه، بدأ طفلكِ يفتح عينيه كثيرًا عندما يكون مستيقظًا. وبمساعدة القزحية، أصبحت حدقتاه تضيقان عند التعرض للضوء وتتسعان في الظلام.;;;
الحدقة هي الفتحة الواقعة في مركز القزحية، أي الجزء الملوّن من العين. وتسمح هذه البنية بوصول الضوء إلى الشبكية. ويبدو هذا الجزء أسود اللون لأن أشعة الضوء التي تمر عبره تمتصها الأنسجة داخل العين ولا تنعكس خارجةً من الحدقة. أما القزحية الملوّنة المحيطة بالحدقة، فهي بنية قابلة للانقباض وتتكوّن أساسًا من عضلات ملساء. يدخل الضوء إلى العين عبر الحدقة، وتتحكم القزحية في حجمها لتنظيم كمية الضوء الداخلة. وتحدث حركات اتساع الحدقة وتضيّقها بفضل عضلتين ملساوين موجودتين في القزحية. فعندما يكون الضوء ساطعًا، تنقبض العضلة العاصرة للحدقة فتُضيّقها، وبذلك تحمي العين من الآثار الضارة للضوء الشديد. وفي الظلام، تنقبض العضلة الموسّعة للحدقة فتسحب القزحية نحو الأطراف. وهذا يؤدي إلى اتساع الحدقة ودخول كمية أكبر من الضوء إلى العين، ما يتيح الرؤية في الظلام.'), baby_message_ar = COALESCE(baby_message_ar, 'لم تعد بشرتي شفافة! 👶 أصبحت بشرتي أكثر سماكة ووردية، ولم تعد أعضائي الداخلية ظاهرة. والطبقة الدهنية تجعلني أكثر امتلاءً. لقد أصبحت أشبه بمولود جديد حقيقي. إذا رأيتِني في التصوير بالموجات فوق الصوتية ثلاثي الأبعاد، فسترغبين في قرص وجنتيّ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كنتِ في حملكِ الثاني وكانت ولادتكِ الأولى قيصرية، فقد تكون الولادة الطبيعية بعد القيصرية (SQSD) خيارًا متاحًا لكِ. ويشير اختصار SQSD إلى الولادة الطبيعية بعد عملية قيصرية، أي الولادة عن طريق المهبل بعد أن كانت الولادة السابقة بعملية قيصرية. في الماضي، لم يكن يُنصح عادةً للنساء اللواتي خضعن لولادة قيصرية بأن يلدن طبيعيًا في الحمل التالي.;;;
لكن أظهرت الأبحاث الحديثة أن احتمال نجاح المرأة التي سبق أن ولدت قيصريًا في ولادتها الثانية طبيعيًا يزيد على 75%.;;;
إذا مرّ عام واحد على الأقل منذ ولادتكِ القيصرية، ولم يسبق أن تعرضتِ لتمزق الرحم أو أجريتِ أي جراحة أخرى في الرحم، ولم تكن هناك خلال حملكِ مشكلات تمنع الولادة الطبيعية، فيمكنكِ التفكير في الولادة الطبيعية بعد القيصرية (SQSD) بالتشاور مع طبيبتكِ أو طبيبكِ. وإضافة إلى ذلك، تتمتع الولادة الطبيعية بمزايا أكثر مقارنة بالولادة القيصرية؛ إذ تقصر فترة التعافي بعد الولادة، وينخفض خطر العدوى، ويكون فقدان الدم في أدنى مستوياته.'), daily_tip_ar = COALESCE(daily_tip_ar, 'خصّصي وقتًا لنفسكِ. فهذه هي الأسابيع الأخيرة قبل الولادة التي قد تتمكنين فيها من الاستمتاع بوقتكِ على انفراد. اقرئي كتابًا، وشاهدي فيلمًا، والتقي بصديقاتكِ وأصدقائكِ، وقدّري قيمة هذه الأيام الهادئة.') WHERE id = '79fb5c0f-3cea-4126-92e7-e885b95bc603';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تنتقل الجينات التي تحدد طول طفلكِ ووزنه عبر الكروموسومات الموجودة في الخلايا التناسلية لديكِ ولدى الأب. ويرتبط نحو 80% من العوامل التي تحدد زيادة الطول تحديدًا بالشفرة الجينية، وقد يتراوح عدد الجينات المعنية بين 600-700 جين. وباختصار، إذا كان والدا الطفل قصيري القامة ونحيلي البنية وراثيًا، فمن غير المرجح أن يصبح طويل القامة أو ميالًا إلى زيادة الوزن دون تأثير عوامل أخرى. كما تُعد العادات الغذائية عاملًا يؤثر مباشرةً في زيادة الوزن واستطالة العظام وزيادة سماكتها، وتؤدي عملية نمو العظام هذه إلى زيادة الطول. وإلى جانب العوامل الوراثية، تتأثر نسبة الطول إلى الوزن أيضًا بأمراض مختلفة، واضطرابات جينية تعوق النمو، ونقص العناصر الغذائية والعادات الغذائية غير السليمة، ونظام النوم، والنشاط البدني. كما يؤثر المناخ في زيادة الطول والوزن. فالأشخاص الذين يعيشون في المناطق ذات المناخ الاستوائي يميلون إلى أن يكونوا أقصر قامة وأكبر بنية، في حين يميل سكان شمال أوروبا، مثل الدول الإسكندنافية، إلى أن يكونوا أطول قامة وأنحف بنية.'), baby_message_ar = COALESCE(baby_message_ar, 'أكتسب مناعتكِ! 🛡️ ماما، هل تعرفين ماذا أفعل الآن؟ أجمع من دمكِ «جنود المناعة» الخاصة بي، أي الأجسام المضادة. فأنتِ تنقلين إليّ المناعة التي اكتسبتِها ضد الأمراض طوال حياتكِ. وعندما أولد، ستكونين أنتِ درعي الأول الذي يحميني من الجراثيم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'تزداد حاجتكِ إلى فيتامين D خلال الحمل بنحو 5 أضعاف بسبب نمو عظام طفلكِ. وتكون كمية الكالسيوم التي تنتقل من جسمكِ إلى طفلكِ مرتفعة جدًا، خصوصًا خلال الثلث الثاني من الحمل، حين يتسارع نمو عظامه. لذلك يزيد جسمكِ امتصاص هذا الفيتامين في الأمعاء لتلبية الاحتياج المتزايد إليه. وفي الوقت نفسه، قد يزداد انتقال الكالسيوم من عظامكِ إلى الدم، ما قد يجعل عظامكِ أكثر هشاشة خلال الحمل.;;;
تفقد النساء نحو 5% من كتلتهن العظمية على امتداد الحمل. وقد يؤدي انخفاض مستوى فيتامين D في جسمكِ إلى زيادة خطر الإصابة بسكري الحمل، وتسمم الحمل المعروف باسم ما قبل تسمم الحمل، والعدوى. لذلك تُعد مكملات فيتامين D مهمة جدًا وفق إرشادات طبيبتكِ أو طبيبكِ. وإلى جانب المكملات، قد يفيدكِ التعرض لأشعة الشمس لمدة 15-20 دقيقة يوميًا مع مراعاة الحماية المناسبة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي شرب الكثير من الماء. فهذا ضروري لتنظيم درجة حرارة جسمكِ وتجنب الجفاف، إذ قد يؤدي الجفاف إلى حدوث تقلصات مبكرة.') WHERE id = 'adc2549c-64e5-4fcb-ab22-00fd00f59fac';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بحلول نهاية الأسبوع 33، تكونين قد أتممتِ 7 أشهر و28 يومًا من الحمل. ابتداءً من هذا الأسبوع، يبدأ طفلكِ باكتساب ما لا يقل عن 30 غرامًا يوميًا. وترجع هذه الزيادة في الوزن إلى إنتاجه السريع للخلايا الدهنية. وبفضل الزيادة الكبيرة في النسيج الدهني تحت الجلد، أصبح طفلكِ يبدو الآن كطفل مكتمل الملامح. وخلال الأسبوعين المقبلين، ستصل نسبة الدهون لديه تقريبًا إلى مستواها عند الولادة، ما يجعل بشرته ناعمة جدًا. وتعمل الخلايا الدهنية التي يخزنها طفلكِ تحت جلده على الحفاظ على دفء جسمه وتوفير احتياطي من الطاقة. وخلال هذه الأسابيع التي تقتربين فيها من نهاية الحمل، يقوى جهاز طفلكِ المناعي أيضًا. ويحدث ذلك بانتقال الأجسام المضادة التي ينتجها جسمكِ إلى طفلكِ عبر المشيمة والحبل السري. وبفضل تطور جهازه المناعي، سيكون طفلكِ عند ولادته أكثر قدرة على التكيف ومستعدًا للعالم الخارجي.'), baby_message_ar = COALESCE(baby_message_ar, '🍈 أنا بحجم ثمرة شمام! هذا الأسبوع يمثل مرحلة مهمة جدًا. إذا وُلدت الآن، فمن المرجح أن أتمكن من التنفس بمفردي لأن رئتيّ أصبحتا متطورتين بما يكفي. أنا الآن ضمن فئة "الخداج المتأخر". لقد انخفضت المخاطر كثيرًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام'), body_changes_ar = COALESCE(body_changes_ar, 'يحتاج طفلكِ، الذي ينمو بسرعة خلال الحمل، إلى كمية كبيرة من الكالسيوم، ولا سيما لتقوية هيكله العظمي وعظامه. وإذا لم تحصلي على ما يكفي من الكالسيوم طوال فترة الحمل، فسيلبي طفلكِ حاجته إليه من جهازكِ العظمي، ما قد يؤدي إلى استنزاف مخزون الكالسيوم في جسمكِ. وعندما لا تحصلين على قدر كافٍ من الكالسيوم من نظامكِ الغذائي اليومي، قد تعانين كثيرًا من مشكلات مثل الألم والتشنجات، خصوصًا في ساعات المساء. كما أن تأثر جهازكِ العظمي بدرجة كبيرة قد يمهد للإصابة بهشاشة العظام وغيرها من مشكلات العظام. لذلك، احرصي على اختيار الأطعمة التي تتناولينها بعناية وتأكدي من تلبية احتياجاتكِ اليومية من الكالسيوم، من أجل نمو طفلكِ والحفاظ على صحة جسمكِ. ومن الأطعمة التي تساعد على تلبية احتياجاتكِ من الكالسيوم: الجبن الأبيض واللبن والحليب والمكسرات النيئة والبقوليات والطحينة الطبيعية ودبس الفاكهة. يحتوي وعاء من اللبن على 250 ملغ، وشريحة من الجبن الأبيض على 100 ملغ، وحفنة من المكسرات النيئة على 50 ملغ، و50 غرامًا من دبس الفاكهة على 200 ملغ، و50 غرامًا من الطحينة على 220 ملغ من الكالسيوم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'كافئي نفسكِ اليوم وخذي قسطًا كافيًا من الراحة احتفالًا بإتمامكِ 34 أسبوعًا من هذه الرحلة بنجاح. استخدمي وسائد تدعم ظهركِ أثناء الجلوس لتخفيف آلام الظهر. وإذا لم تكوني قد فعلتِ ذلك بعد، فضعي حقيبة الولادة بجوار الباب لتكوني مستعدة في أي لحظة. وابتداءً من الغد، سنبدأ الأسبوع 35، أي المنعطف الكبير الأخير نحو الولادة!') WHERE id = '5eeb8067-0b28-436d-9bac-19e1ef1b2e15';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ابتداءً من هذا الأسبوع، أصبحت جميع وظائف جسم طفلكِ تعمل. وقد وصلت أعضاؤه تقريبًا إلى الحجم الذي ستكون عليه عند الولادة. ومن بين هذه الأعضاء الكبد، الذي يعادل حجمه %5 من وزن طفلكِ ويبلغ وزنه في المتوسط 100 غرام. والكبد هو أكبر الأعضاء الداخلية لدى طفلكِ، ويزن لدى البالغين نحو 2 كيلوغرام. يقع الكبد على الجانب الأيمن من المعدة وبالقرب من أجهزة الجسم الأخرى، وله وظائف حيوية لطفلكِ. فعند الحاجة إلى الطاقة، يمكنه تحويل الغليكوجين المخزن إلى سكر. كما تُخزن فيه فيتامينات A وD وE وK وB12 والحديد. وينتج البروتينات، ويمكنه تحويلها إلى هرمونات وأجسام مضادة وفقًا لاحتياجات الجسم. وبفضل العصارة الصفراوية التي ينتجها، يحول الدهون الداخلة إلى الجسم إلى أحماض دهنية وغليسرين، لتصبح جاهزة لاستخدام الخلايا. ويعمل الكبد أيضًا كمرشح للمواد الضارة المتراكمة في الجسم، إذ يعطل جميع المواد المؤذية، وفي مقدمتها الكحول والمواد السامة، ويساعد على طرحها من الجسم عبر البول.'), baby_message_ar = COALESCE(baby_message_ar, 'تزداد طبقة الطلاء الجبني لديّ سماكة! 🧀 إن تلك المادة البيضاء الشبيهة بالجبن التي تغطي جلدي (الطلاء الجبني) بلغت الآن أقصى سماكتها. إنها تحميني. ومع اقتراب الولادة، ستقل هذه الطبقة تدريجيًا وتختلط بالسائل الأمنيوسي. وعندما أبتلع هذا السائل، أحصل على البروتين. أنا لا أهدر شيئًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام'), body_changes_ar = COALESCE(body_changes_ar, 'يزيد جسمكِ حجم الدم بسرعة لتزويد طفلكِ بالأكسجين والعناصر الغذائية. وتؤدي هذه الزيادة إلى توسع الأوعية الدموية، ما يسبب انخفاض ضغط الدم وتراجع قراءاته. وبوجه عام، لا يسبب لكِ انخفاض ضغط الدم مشقة كبيرة. لكن بعض العوامل التي قد تزيده سوءًا، مثل الإرهاق الشديد والعدوى والبقاء بلا حركة مدة طويلة وقلة شرب السوائل وسوء التغذية وفقر الدم والنزيف والحساسية، قد تؤدي إلى الدوار واسوداد الرؤية وتشوشها وسرعة التنفس والغثيان والشعور بقرب الإغماء. إذا كان ضغط دمكِ منخفضًا، فتجنبي النهوض بسرعة من وضعية الجلوس أو الاستلقاء، ولا تقفي مدة طويلة، ولا تبقي جائعة لفترات طويلة، وابتعدي عن الحمامات شديدة السخونة أو الطويلة. واحرصي على شرب ما يكفي من السوائل والحفاظ على نظام غذائي متوازن للحصول على الفيتامينات الضرورية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تقلقي إذا لم تكن مشكلة الرؤية لديكِ شديدة. لكن إذا كنتِ ترين "ذبابًا طائرًا" أمام عينيكِ، فقد يكون ذلك علامة مرتبطة بضغط الدم، فأخبري طبيبكِ فورًا.') WHERE id = 'ee172976-4ef5-4259-a92a-16b538ea9e64';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من اكتمال تكوّن كثير من عظام طفلكِ ومفاصله، فإن عظام جمجمته لا تزال لينة. وهذا مهم جدًا للسماح لعظام الجمجمة بالحركة اللازمة لإتمام عملية الولادة. وفي هذه المرحلة، تُبقي الأنسجة الضامة عظام الجمجمة متماسكة من دون أن تلتحم. ولأن هذه الأنسجة تمنح عظام الجمجمة القدرة على الحركة أيضًا، يمكن لرأس طفلكِ المرور بسهولة عبر قناة الولادة الضيقة جدًا.;;;
وفي المواضع التي لم تلتحم فيها عظام الجمجمة، توجد مناطق لينة تُعرف باسم "اليافوخ". وتمنح هذه المناطق اللينة رأس طفلكِ المرونة اللازمة للتحرك عبر قناة الولادة، بمساعدة الأنسجة الضامة الموجودة تحتها. وتُغلق هذه المناطق بعد ولادة طفلكِ بالتزامن مع نمو الدماغ وتطوره. وأثناء مرور طفلكِ عبر قناة الولادة، عليه القيام ببعض الحركات ليتكيف قطر رأسه مع قطر القناة. كما يغيّر وضعيته للتغلب على المقاومة التي يواجهها أثناء تقدمه فيها. وخلال هذه الحركات، تنكمش الأنسجة الضامة، فتتقارب عظام الجمجمة وقد تتراكب فوق بعضها بعضًا.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أنظر إلى الأسفل! ⬇️ على الأرجح، دخل رأسي الآن بين عظام حوضكِ. قد يسبب لكِ هذا بعض الانزعاج (كأن هناك كرة بين ساقيكِ)، لكنه يعني بالنسبة إليّ أنني أقترب من باب الخروج. أنا عند خط الانطلاق!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي أن يكون السمك جزءًا أساسيًا من نظامكِ الغذائي طوال الحمل، لأنه غني بأحماض أوميغا-3 وأوميغا-6 الدهنية. فتناول السمك مهم جدًا لنمو جسم طفلكِ بالكامل، ولا سيما تطور جهازه العصبي وعينيه. ومع ذلك، عند تناول الأسماك التي تحتوي على كميات مرتفعة من الزئبق، يمتص الجسم هذه المادة السامة بسهولة، ثم تنتقل عبر الدم إلى المشيمة. ويُعد تناول أسماك السلمون والأنشوجة والسردين والسلمون المرقط والماكريل مفيدًا جدًا. أما أسماك أبو سيف والتونة والقرش، فتحتوي على كميات مرتفعة من الزئبق. وعلى الرغم من احتواء التونة على الزئبق، فإنها غذاء مهم لنمو طفلكِ، لذا يمكن تناولها من حين إلى آخر من دون إفراط.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تحركي ببطء. واستعيني بيديكِ عند النهوض من مكان جلوسكِ. كما أن الجلوس على كرة التمارين والقيام بحركات دائرية مفيد جدًا لإرخاء عضلات الحوض.') WHERE id = '75621ce6-a937-4f79-9f2e-175be59eec6b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتكوّن الحبل السري، الذي يؤدي مهمة نقل الغذاء والأكسجين بين مشيمة طفلكِ وجسمه، من شريانين ووريد واحد. ويُسمّى الحبل السري في المصطلحات الطبية بالحبل السريّ، وهو جزء من طفلكِ من الناحيتين الفسيولوجية والجينية؛ إذ يضمن نقل الدم النظيف والدم المحتوي على الفضلات من دون اختلاطهما ببعضهما. يبلغ طول الحبل السري نحو 50 sm وقطره 2 sm. وتعمل الشرايين والأوردة الموجودة في هذا التركيب بصورة معاكسة. ففي الوضع الطبيعي، يُنقل الدم الغني بالأكسجين عبر الشرايين، بينما يُنقل الدم الفقير بالأكسجين والمحتوي على الفضلات عبر الأوردة؛ أما في الحبل السري، فتنقل الشرايين الدم المحتوي على الفضلات، بينما تنقل الأوردة الدم الغني بالأكسجين والمواد الغذائية. ولأنه لا يحتوي على أعصاب، فإن قطعه بعد الولادة لا يسبب لطفلكِ أي شعور بالألم. لكن في بعض الحالات، قد يتكوّن الحبل السري من وعاءين فقط، هما شريان واحد ووريد واحد. وفي هذه الحالات، يُفحص نمو الطفل وقد تكون المتابعة الدقيقة ضرورية.'), baby_message_ar = COALESCE(baby_message_ar, 'عظامي صلبة كالحجر! 🦴 لقد أصبح هيكلي العظمي صلبًا بالكامل. لم تعد ذراعاي وساقاي رخوتين كالمطاط، بل أصبحتا قويتين. عندما أركلكِ، ربما تشعرين الآن بألم أكبر. واصلي تناول الكالسيوم، لأنني ما زلت أستخدم مخزون جسمكِ منه.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'الريلاكسين هرمون ذو طبيعة بروتينية يبدأ مستواه في الارتفاع في جسمكِ مع بداية حملكِ.;;;
الريلاكسين هرمون يشبه الإنسولين إلى حد كبير من الناحية الكيميائية. تفرزه المشيمة والمبيضان، ويؤدي وظائف بالغة الأهمية خلال الحمل.;;;
يساعد هرمون الريلاكسين على إرخاء الأربطة التي تثبّت عظام الحوض وتليينها. إضافة إلى ذلك، يساعد، بدءًا من الثلث الثالث مع اقتراب موعد الولادة، على إرخاء الأربطة المحيطة بالرحم.;;;
ترتفع كميته في الجسم بنحو 10 أضعاف مقارنة بما كانت عليه قبل الحمل. ويرتفع مستوى هذا الهرمون في الدم بدرجة كبيرة حتى في الأيام الأولى لانغراس طفلكِ في الرحم، كما يساعد على تكوين أوعية دموية جديدة، مما يهيئ البيئة الأنسب للبويضة المخصبة.;;;
إضافة إلى ذلك، يؤدي هرمون الريلاكسين إلى ارتخاء أربطة مختلفة في الجسم، مثل أربطة الوركين والكاحلين والركبتين والكتفين. ونتيجة لذلك، قد يزداد الشعور بالحساسية أو الألم في هذه المناطق بصورة متكررة.;;;
وفي الأسابيع الأخيرة من الحمل، يُرخي هرمون الريلاكسين الحوض المتكوّن من اتصال عظام الورك بعظام العانة، مما يسمح لطفلكِ بالمرور بسهولة أثناء الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'هزّي يديكِ كثيرًا لتخفيف الألم فيهما. واحرصي عند النوم ليلًا على عدم ثني معصميكِ، أو استخدمي دعامات خاصة للمعصم.') WHERE id = '17265dbc-d27e-4949-9a83-25783c4be9dd';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل العضلات الملساء التي ستساعد على الحركة في الأمعاء الدقيقة لطفلكِ نموها. وتستمر عملية النمو هذه حتى الأسبوع 37 تقريبًا. الأمعاء الدقيقة هي المكان الذي تتحلل فيه البروتينات والدهون والكربوهيدرات الموجودة في الكيموس، وهو الطعام المهضوم جزئيًا والقادم من المعدة، إلى وحداتها البنائية. وتتم عملية الهضم بفضل العصارة الصفراوية التي تُنتج في الكبد وتُخزّن في المرارة، وكذلك العصارة البنكرياسية التي تُنتج في البنكرياس وتُفرز مباشرة في الأمعاء الدقيقة.;;;
إضافة إلى ذلك، يجري امتصاص العناصر الغذائية التي تحللت إلى وحداتها البنائية عبر الأمعاء الدقيقة أيضًا. والزُغابات الموجودة في الطبقة الداخلية للأمعاء الدقيقة هي التراكيب المسؤولة عن هذا الامتصاص. في هذه المرحلة، يوجد نحو 40 زغابة في كل مليمتر من الأمعاء الدقيقة. وبعد هضم الطعام في الأجزاء الأولى من الأمعاء الدقيقة، تمتصه الزُغابات في الأجزاء الوسطى منها، لينتقل إلى الدم والسائل اللمفاوي. وتحدث عملية دفع الطعام إلى الأمام ليُهضم ويُمتص بفضل العضلات الملساء الموجودة في الطبقة الوسطى من الأمعاء. وتُشكّل هذه العضلات الطولية والحلقية الحركات الدودية للأمعاء الدقيقة. وبفضل الحركات الدودية، تتحرك المواد الغذائية إلى الأسفل.'), baby_message_ar = COALESCE(baby_message_ar, 'وصل السائل الأمنيوسي من حولي إلى أعلى مستوياته! 💧 الآن يحتوي حوضي على أكبر كمية من الماء (نحو 1 litr). ومن الآن فصاعدًا، ستبقى كمية الماء ثابتة أو ستنخفض قليلًا مع اقتراب الولادة، لأنني سأكبر وأشغل المكان كله. ما زلت مرتاحًا الآن، لكن الجدران تضيق من حولي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'ربما ازدادت شكواكِ من حرقة المعدة بدرجة كبيرة مع دخولكِ الثلث الثالث من الحمل. وقد تحدث حرقة المعدة في أي وقت خلال اليوم، لكنها تُلاحظ عمومًا بصورة أكثر تكرارًا بعد تناول الطعام في ساعات المساء. والارتجاع، المعروف بحرقة المعدة، هو الشعور بالحرقة في منطقة الصدر نتيجة التهيّج الذي يحدث عندما ترتد أحماض المعدة إلى المريء. وترجع الشكوى من حرقة المعدة خلال الحمل بصورة أساسية إلى التغيرات الهرمونية والجسدية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عند الشعور بضيق التنفس، تناولي الطعام في حصص صغيرة جدًا. فعندما تمتلئ المعدة، تضغط أكثر على الحجاب الحاجز. ويساعد الجلوس باستقامة على توفير مساحة أكبر قليلًا للرئتين.') WHERE id = '41437aba-e2e0-4e6a-ba9f-969bd7411f70';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'توجد في الأمعاء الغليظة لطفلكِ بكتيريا نافعة تساعد على الهضم، ويكاد عددها يعادل عدد خلايا الجسم.;;;
الأمعاء الغليظة هي الجزء الأخير من الجهاز الهضمي. وهي عضو يؤدي مهمة فصل الماء والفيتامينات عن بقايا الطعام المهضوم والممتص، وتحويل هذه البقايا إلى براز. ومن أهم وظائف الأمعاء الغليظة أيضًا امتصاص الفيتامينات. ويحدث هذا الامتصاص بواسطة البكتيريا التي تعيش في الأمعاء الغليظة. ويوجد في الأمعاء الغليظة أكثر من 700 نوع من البكتيريا، ويتجاوز عددها الملايين.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بحجم حبة أناناس! لقد أصبحت الآن طفلًا كبيرًا. امتلأ خداي وأصبح جسمي مستديرًا. لم يتبقَّ سوى وقت قصير جدًا حتى ألتقي بكِ، ماما. ويزداد وزني كل يوم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد التهابات المسالك البولية من أكثر المشكلات الصحية شيوعًا في الأسابيع الأخيرة من الحمل. ومن أفضل التدابير التي يمكنكِ اتخاذها للوقاية من التهاب المسالك البولية شرب ما لا يقل عن 2,5 litr من الماء يوميًا. ويجب تجنّب المشروبات المعبأة والمُحلّاة بالسكر خصوصًا، إذ تغذي هذه المنتجات البكتيريا المحتملة في المسالك البولية، مما يؤدي إلى تكاثرها بسرعة. إضافة إلى ذلك، احرصي قدر الإمكان على دخول المرحاض كثيرًا من دون حبس البول، وتأكدي من إفراغ المثانة بالكامل، واهتمي بأقصى قدر ممكن بنظافة المنطقة التناسلية بعد استخدام المرحاض.'), daily_tip_ar = COALESCE(daily_tip_ar, 'زيدي من تناول الحليب أو الزبادي أو الجبن لتعويض الكالسيوم الذي تفقدينه. ولتقليل حرقة المعدة، لا تستلقي مباشرة بعد تناول الطعام، واحرصي على إنهاء وجبة العشاء قبل موعد النوم بما لا يقل عن 3 ساعات. وللوقاية من تورم الساقين ودوالي الأوردة، لا تقفي لفترات طويلة ولا تضعي ساقًا فوق الأخرى عند الجلوس. ألقي اليوم نظرة أخرى على حقيبة الولادة، فربما نسيتِ شيئًا ما؟') WHERE id = '97daa5bb-e709-4882-8a96-d104cbbdafc3';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تستعد رئتا طفلكِ ليوم ولادته من خلال أداء حركات تنفسية في كل لحظة. وعلى خلاف التنفس الطبيعي، تتم حركات التنفس التي يؤديها الجنين داخل الرحم باستخدام الماء (السائل الأمنيوسي) بدلًا من الهواء. ويحصل جسمه على حاجته من الأكسجين عبر المشيمة، وليس عن طريق التنفس. تؤدي هذه الحركات وظيفة التدريب على الشهيق والزفير. وبفضل هذا التدريب، تُنتَج داخل الرئتين مادة السرفاكتانت الضرورية لعملية التنفس. يعتمد انتقال الأكسجين من المشيمة إلى طفلكِ على نظام بسيط للغاية. إذ ينتقل الأكسجين وثاني أكسيد الكربون، وهما الغازان المشاركان في عملية التنفس، عبر المشيمة نتيجة اختلاف الضغط. وعندما يلتقي الأكسجين الذي يستخدمه جسم طفلكِ بالأكسجين الموجود بنسبة مرتفعة في دمكِ عند المشيمة، ينتقل الأكسجين من دمكِ إلى المشيمة بفعل فرق الضغط. وعلى الرغم من انخفاض ضغط الأكسجين، يستطيع دم طفلكِ نقل كمية كافية منه إلى الأنسجة. ويرجع ذلك إلى أن نسبة الهيموغلوبين في دم طفلكِ أعلى بنحو %50. بالإضافة إلى ذلك، فإن قدرة الهيموغلوبين في جهازه الدوري على حمل الأكسجين أعلى بكثير مقارنة بالحصول عليه عن طريق التنفس.'), baby_message_ar = COALESCE(baby_message_ar, 'أخزّن احتياطيًا من الحديد! 🔩 ماما، أنا الآن أسحب الحديد من دمكِ إلى جسمي. وأكوّن مخزونًا من الحديد في كبدي. سأحتاج إلى هذا المخزون لتكوين الدم خلال الأشهر الستة الأولى بعد ولادتي. قد تشعرين بالوهن لأنني "أسرق" طاقتكِ. سامحيني، لكنني أحتاج إليها!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام'), body_changes_ar = COALESCE(body_changes_ar, 'مع بداية الحمل، تطرأ بعض التغيرات على الفلورا المعوية لديكِ. ونتيجة لذلك، تزداد نسبة الدهون في جسمكِ وتقل حساسيته للإنسولين، وهو الهرمون الذي يتحكم في مستوى سكر الدم. وبينما توفر التغيرات الأيضية مزيدًا من الطاقة اللازمة لنمو طفلكِ، فإنها تساعد جسمكِ أيضًا على تكوين مخزون الدهون الذي سيحتاج إليه خلال الرضاعة الطبيعية. لكن ارتفاع مستويات هرمونات الحمل يؤدي إلى ارتخاء العضلات الملساء في الجهاز الهضمي، ما يبطئ حركة الطعام داخل الأمعاء. وقد ينتج عن ذلك عسر الهضم وتراكم الغازات والإمساك. وللوقاية من الإمساك، عليكِ شرب الكثير من السوائل وزيادة نشاطكِ الحركي. واحرصي على اتباع نظام غذائي يضم الخضراوات والفواكه والبقوليات والحبوب الغنية بالألياف.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام الحوض، لا تضعي ساقًا فوق الأخرى أثناء الجلوس، وتقلّبي في السرير من جانب إلى آخر ببطء شديد. ولتجنب حرقة المعدة، ابتعدي عن الأطعمة الثقيلة قبل النوم. راجعي "قائمة حقيبتكِ" للمرة الأخيرة هذا الأسبوع، وتأكدي من تجهيز رداء مريح لكِ، وأول طقم ملابس لطفلكِ، وحفاضات الرضيع. خصصي اليوم بعض الوقت لنفسكِ واستمعي إلى موسيقى هادئة.') WHERE id = 'b978e435-783d-4177-aada-9e6cd05f0950';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يستمر تكوّن الدهون في جسم طفلكِ بوتيرة سريعة جدًا. وفي الوقت نفسه، يكون معظم زغب الجنين الذي يغطي جسمه قد تساقط. وزغب الجنين هو شعر ناعم يبدأ بالظهور على جسم طفلكِ بالكامل منذ الثلث الأول من الحمل. ويزداد هذا الزغب كثافةً وكميةً بشكل ملحوظ مع بلوغ الأسبوع العشرين. وينمو للمساعدة على إبقاء درجة حرارة جسم طفلكِ مستقرة قبل تكوّن الطبقة الدهنية لديه، ثم يبدأ بالتساقط تدريجيًا عندما يبدأ إنتاج الدهون خلال الثلث الأخير. وفي الأسابيع الأخيرة من الحمل التي تمرين بها حاليًا، تتكوّن الطبقة الدهنية بسرعة كبيرة. لذلك يزداد معدل تساقط هذا الزغب بشدة، ويختلط الزغب المتساقط من سطح الجلد بالسائل الأمنيوسي. ويدخل الزغب الموجود في السائل الأمنيوسي إلى جسم طفلكِ أثناء حركات التنفس. ثم يتحد زغب الجنين الذي يبتلعه طفلكِ نتيجة هذه الحركات مع الطبقة المخاطية في الأمعاء، ويكوّن مع بقايا الجلد وغيرها من الفضلات مادة العقي.'), baby_message_ar = COALESCE(baby_message_ar, 'تعمل كليتاي بكامل طاقتهما! 💧 لقد اكتمل نمو كليتيّ، وأصبح كبدي قادرًا على معالجة بعض الفضلات. إذا وُلدت اليوم، فسيعمل نظام تنقية جسمي. أزداد "استقلالًا" يومًا بعد يوم. يمكنكِ أن تفخري بي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين من حين إلى آخر بوهن شديد وإنهاك وتعب. ومن الطبيعي أن تكوني أكثر تعبًا ووهنًا مقارنة بفترة ما قبل الحمل، بسبب التغيرات الهرمونية ووصول طفلكِ إلى حجم كبير نسبيًا والوزن الذي اكتسبتِه. وغالبًا ما يقل هذا التعب مع الراحة والنوم الجيد. لكن إذا كان التعب لا يزول حتى بعد الراحة، وتشعرين به عند الاستيقاظ ويستمر مدة طويلة، فقد يكون ذلك ما يُعرف بمتلازمة التعب المزمن. وهي حالة تتسم بتعب طويل الأمد لا يتحسن بالراحة، وقد يصاحبها عدد من الأعراض مثل مشكلات الذاكرة والتركيز، والصداع المتفاوت الشدة، وصعوبة الاستغراق في النوم، والتهاب الحلق المتكرر. ويُعد سوء التغذية أحد أبرز العوامل المسببة للتعب المزمن. وإذا لم تتمكني من الحصول على الفيتامينات والمعادن التي تحتاجين إليها أنتِ وطفلكِ من خلال الغذاء، فعليكِ بالتأكيد تناول المكملات التي يوصي بها طبيبكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لمواجهة الأرق، حاولي ألا ترهقي نفسكِ كثيرًا خلال النهار، وخذي حمامًا دافئًا قبل النوم. ولتخفيف آلام الظهر، احرصي على استخدام وسادة الحمل والاستلقاء على جانبكِ الأيسر. ولتقليل تورم ساقيكِ، اشربي الكثير من الماء واستريحي لمدة 15 دقيقة مع رفع ساقيكِ فوق مستوى القلب 3-4 مرات على الأقل خلال اليوم. لا ترهقي نفسكِ كثيرًا اليوم، واحتفظي بقوتكِ لليوم المنتظر.') WHERE id = '35db243b-b555-441f-ace2-1f8b3ddb076b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبلغ حجم الدم لدى طفلكِ في هذه المرحلة 80 ملليلترًا لكل كيلوغرام من وزن جسمه، ويحتوي جسمه في المتوسط على 250 غرامًا من الدم. وتُنتَج خلايا الدم في نخاع العظم، وهو نسيج إسفنجي يوجد داخل بعض العظام. ويحتوي نخاع العظم على خلايا جذعية متخصصة. واستجابةً لعوامل مختلفة ووفقًا لاحتياجات جسم طفلكِ، تنتج هذه الخلايا كريات الدم الحمراء والبيضاء والصفائح الدموية. ويختلف مقدار الهيموغلوبين في الدم الذي يدور داخل الجهاز الدوري لطفلكِ اختلافًا كبيرًا عن المعدل الطبيعي. فمن هذا الأسبوع وحتى الولادة، يكون مستوى الهيموغلوبين في دمه نحو  غ/دل. وعلى الرغم من أن هذا المستوى قد يرتفع لفترة قصيرة بعد الولادة ليصل إلى  غ/دل، فإنه ينخفض إلى نحو  غ/دل عند بلوغه الشهر الثالث. ومع ولادة طفلكِ، يتوقف إنتاج كريات الدم الحمراء في نخاع العظم مؤقتًا. ويرجع ذلك إلى تعرّض جسمه لضغط الأكسجين عند الولادة. وعلى الرغم من أن الوضع ينتظم بعد تكيّف نخاع العظم مع ضغط الأكسجين، فإن الأطفال حديثي الولادة غالبًا ما يصابون بنوع من فقر الدم يُسمى فقر الدم الفسيولوجي.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا "أتدحرج"! 🔄 كنت أركلكِ من قبل، لكن المساحة أصبحت الآن ضيقة جدًا، لذا لا أستطيع سوى التدحرج أو الدفع بمرفقيّ. قد ترين كعبي أو ركبتي بارزين على بطنكِ. ربّتي عليّ، فربما أتراجع إلى الداخل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام'), body_changes_ar = COALESCE(body_changes_ar, 'مع بداية الحمل، يؤدي الارتفاع الكبير في مستوى هرمون البروجستيرون في الدم إلى تغير قدرة القرنية، وهي الطبقة الشفافة الموجودة في الجزء الأمامي من العين، على الاحتفاظ بالماء. وقد ينتج عن ذلك تشوش الرؤية وفرط الحساسية تجاه العدسات، خاصة لدى مستخدمات العدسات اللاصقة. لذا ينبغي تجنب استخدام العدسات اللاصقة خلال هذه الفترة. بالإضافة إلى ذلك، قد يؤدي انخفاض هرمون الأندروجين أثناء الحمل إلى جفاف العينين. ويمكن لقطرات الدموع الاصطناعية التي تستخدمينها بناءً على توصية طبيبكِ أن تخفف الجفاف. وغالبًا ما تقل هذه الشكوى بعد الولادة ثم تزول تمامًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي شرب الكثير من الماء لتخفيف الوذمة، واستريحي بانتظام مع إبقاء ساقيكِ مرفوعتين. كما ستساعدكِ تمارين الحمل الخفيفة أو حركات اليوغا على تخفيف آلام الظهر.') WHERE id = '8220cf1e-c217-46c8-aaef-257724e08389';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يستمر جسم طفلكِ في إنتاج هرمون التستوستيرون، وينطبق ذلك على الأجنة الذكور والإناث على حد سواء. والتستوستيرون هرمون ستيرويدي ينتمي إلى مجموعة الأندروجينات، أي إنه يحتوي على الدهون في تركيبه. لدى الأجنة الذكور، يُفرز التستوستيرون أساسًا في الخصيتين والغدتين الكظريتين الواقعتين فوق الكليتين. أما لدى الأجنة الإناث، فيُنتَج التستوستيرون في المبيضين. ويُنظَّم إفراز هذا الهرمون لدى كلا الجنسين بواسطة منطقة تحت المهاد في الدماغ.;;;
على الرغم من إفراز التستوستيرون لدى الأجنة الإناث أيضًا، فإن كميته تكون قليلة جدًا مقارنةً بما يُفرَز لدى الأجنة الذكور. ويبدأ إفراز التستوستيرون بكميات كبيرة خلال مرحلة البلوغ، ويبلغ أعلى مستوياته في الجسم خلال العشرينيات، ثم يبدأ بالانخفاض تدريجيًا منذ الثلاثينيات. يؤدي التستوستيرون دورًا مهمًا في تكوّن الأعضاء التناسلية أثناء نمو طفلكِ داخل الرحم. ولدى الأجنة الذكور، يُعد توفر كمية كافية من التستوستيرون ضروريًا لنمو القضيب والخصيتين. وبينما يؤدي لدى الذكور وظائف مثل تغليظ الصوت ونمو الشعر ونمو الأعضاء التناسلية واكتسابها وظائفها، فإنه يساهم لدى الأجنة الإناث في تنشيط مستقبلات الإستروجين وتحفيز تعظّم الأنسجة الغضروفية، ويشارك خصوصًا خلال الحياة داخل الرحم في آلية هرمون LH المحفزة للإباضة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا مستعد بنسبة 99%! ✅ إذا وُلدت اليوم، فمن المرجح جدًا أن أبقى على قيد الحياة من دون أي مشكلات خطيرة (وقد أحتاج إلى رعاية خاصة لفترة قصيرة). رئتاي جاهزتان تقريبًا، لكن بقائي داخل رحمكِ يمنحني مزيدًا من الوزن والقوة. لا داعي للاستعجال!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة خس كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يطلب منكِ طبيبكِ إجراء تخطيط قلب الجنين وتقلصات الرحم (KTQ) أسبوعيًا بدءًا من هذا الأسبوع. وقد تؤثر عوامل مثل نوم طفلكِ وقت الفحص أو أسبوع الحمل الذي أنتِ فيه في النتيجة. لذلك، إذا لم يكن هناك خطر للولادة المبكرة، فلا يُجرى هذا التخطيط قبل الأسبوع الثامن والعشرين من الحمل. وللحصول على أفضل نتيجة، ينبغي بدء الفحص بعد ساعتين من تناول الطعام. أثناء الإجراء، يُثبَّت مستشعران على بطنكِ؛ يراقب أحدهما تقلصات الرحم، بينما يتابع الآخر نبضات قلب طفلكِ وحركاته.;;;
يُعد تخطيط قلب الجنين وتقلصات الرحم (KTQ) إحدى الوسائل المستخدمة لتقييم صحة طفلكِ داخل الرحم، ولا سيما خلال المراحل الأخيرة من الحمل. وتُتابَع صحة الجنين بهذا التخطيط خصوصًا في حالات السكري، ومرض الكلى المزمن، وارتفاع ضغط الدم الناجم عن الحمل، وانخفاض حركات الجنين، وتأخر النمو، ونقص السائل الأمنيوسي، وتجاوز الحمل الأسبوع الأربعين.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام الظهر والحوض، احرصي عند الجلوس على استخدام وسائد تدعم ظهركِ. وإذا كان التورم في ساقيكِ شديدًا، فارفعيهما مساءً وأسنديهما إلى الحائط لمدة 15-20 دقيقة. واصلي شرب الكثير من الماء، فهو مهم لعمل كليتيكِ وتجدد السائل الأمنيوسي. لا ترهقي نفسكِ كثيرًا اليوم، وقللي أنشطتكِ البدنية إلى الحد الأدنى.') WHERE id = 'ded751f7-f2a6-42dd-a319-bc879f101abf';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبحت تلافيف دماغ طفلكِ قريبة جدًا من شكلها عند الولادة. ويبلغ حجم الدماغ من دون تلافيف في المتوسط  سم. ولكي يتناسب الدماغ مع الجسم، لا بد من تكوّن التلافيف. وباختصار، تُعد تلافيف الدماغ اختلافًا بنيويًا يهدف إلى زيادة مساحة سطحه.'), baby_message_ar = COALESCE(baby_message_ar, 'أستجيب لصوتكِ! 🎤 عندما تتحدثين أتحرك، وعندما تضحكين أقفز فرحًا. أما صوت أبي فيبدو لي كحكاية جميلة. واصلي الحديث معي، فأنا أستمع إليكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة خس كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يجعل الألم في موضع اتصال عظمتَي العانة (التهاب الارتفاق العاني) المشي صعبًا، وقد يتحول التقلب من جانب إلى آخر في السرير إلى معاناة حقيقية. يحدث ذلك ضمن عملية تهيؤ الحوض واتساعه للولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تأكدي الآن من أن حقيبة الولادة جاهزة تمامًا وأن مستنداتكِ في متناول يدكِ. استريحي قليلًا اليوم وتحدثي إلى طفلكِ، فهو أصبح يعرف نبرة صوتكِ المليئة بالحب جيدًا جدًا.') WHERE id = '0307b519-8b14-459a-84c3-9d370f50a4be';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أوشك الجهاز العصبي لطفلكِ على اكتمال نموه. وفي هذه المرحلة ينقسم الجهاز العصبي إلى قسمين: الجهاز العصبي الذاتي والجهاز العصبي المحيطي. والجهاز العصبي الذاتي هو الجزء المسؤول عن تنظيم حركات الجسم اللاإرادية ووظائف الأعضاء. فهو يعمل خارج نطاق الإرادة في وظائف مثل معدل ضربات القلب، وهضم الطعام، وحركات التنفس اللازمة لتبادل الأكسجين وثاني أكسيد الكربون، وإفراز اللعاب، والتعرق، والتبول.'), baby_message_ar = COALESCE(baby_message_ar, 'تكوّنت طبقة الدهون في ذراعيّ! 💪 لم تعد ذراعاي وساقاي نحيلتين كالعصي، بل أصبحت لديّ طيات ممتلئة وواضحة. وبدأت تظهر تلك الغمازات اللطيفة عند مرفقَيّ وركبتَيّ. بشرتي ناعمة، وقد خُلقت لأُحتضن.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة خس كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'حان وقت إجراء تحليل المكورات العقدية من المجموعة B" (GBS). يُجرى هذا الفحص بين الأسبوعين 35-37 للتحقق من وجود بكتيريا المكورات العقدية من المجموعة B. سيأخذ طبيبكِ مسحة من المهبل للتأكد من وجود هذه البكتيريا أو عدمه. لا تسبب لكِ هذه البكتيريا ضررًا، لكنها قد تنتقل إلى طفلكِ أثناء الولادة. وإذا كانت موجودة، فستُعطين مضادًا حيويًا خلال الولادة. وإذا كنتِ ستلدين ولادة طبيعية، فيجب عليكِ إجراء هذا الفحص بالتأكيد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عند التقلب في السرير، أبقي ركبتيكِ ملتصقتين إحداهما بالأخرى (مثل حورية البحر). يساعد ذلك على تخفيف الألم والتوتر في عظام الحوض.') WHERE id = 'f9ddf067-2beb-491f-a9d9-5cef8bbb118b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ترتبط زيادة وزن طفلكِ السريعة بتكوّن الخلايا الدهنية في جسمه. وتُعد هذه الدهون ضرورية جدًا لتنظيم درجة حرارة جسمه بعد الولادة. وقد اكتمل نمو الكليتين، وأصبحتا تنتجان أكثر من 1 لتر من البول يوميًا. ويبدأ مقدار السائل الأمنيوسي في الرحم بالانخفاض هذا الأسبوع. وهذا طبيعي بسبب كبر حجم طفلكِ، ولا داعي للقلق ما دام لم يصل إلى مستوى خطير.;;;
من الآن فصاعدًا، سيواصل طفلكِ اكتساب الوزن، لكن نموه في الطول سيتباطأ قليلًا. وعادةً ما يتراوح طول الأطفال عند الولادة بين 48-52 سم.'), baby_message_ar = COALESCE(baby_message_ar, 'اكتمل الأسبوع 35! 👋 مرحبًا بالشهر التاسع! (وفقًا للتقويم). لقد اقتربنا كثيرًا من خط النهاية. أصبحت المساحة حولي ضيقة جدًا، لكنني ما زلت أتحرك. إذا قلّت حركاتي، فأخبري طبيبكِ بالتأكيد. أنا لا أهدأ لأنني أشعر بالملل، بل لأنني أكون نائمًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خسّة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'ينخفض خطر الولادة المبكرة. إذا بدأت الولادة الآن، فإن 99% من الأطفال يبقون على قيد الحياة ولا يعانون مشكلات خطيرة طويلة الأمد. ومع ذلك، لا تزال الولادة تُعد «مبكرة». وقد تصبح تقلصات براكستون هيكس أكثر انتظامًا، لذا تعلّمي كيفية تمييزها عن تقلصات المخاض الحقيقية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تفوّتي فحوصاتكِ الأسبوعية لدى الطبيب. فقد تتغير حالتكِ بسرعة خلال هذه الأسابيع الأخيرة. وإذا كانت لديكِ أي أسئلة، فدوّنيها جميعًا واطرحيها على طبيبكِ.') WHERE id = '7800e1ad-f092-45f7-8448-b5a2384087fa';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع اكتمال الأسبوع 36، تبدأ مرحلة جديدة لطفلكِ. وهذا هو الأسبوع الأخير الذي سيُوصف فيه طفلكِ بأنه خديج (مولود قبل أوانه) إذا حدثت الولادة.;;;
قد تحدث الولادة المبكرة خلال الحمل نتيجة حالات مثل ارتفاع ضغط الدم، وتسمم الحمل، والعدوى المختلفة، وقصور عنق الرحم، واضطرابات التخثر، والتدخين وتناول الكحول، وعدم كفاية متابعة الحمل، وتدني المستوى الاجتماعي والاقتصادي. ويُصنَّف الأطفال الذين يولدون قبل إكمال 37 أسبوعًا من الحمل على أنهم أطفال خدّج. وإذا حدثت ولادتكِ هذا الأسبوع، فيمكن لطفلكِ أن يعيش دون مشكلات بمساعدة دعم تنفسي قصير المدى. وخلال الفترة من 36+0 إلى 36+6 من الحمل، أي مع الدخول في الأسبوع 37، يكون طفلكِ قد أكمل بالفعل الجزء الأكبر من نموه وأصبح مستعدًا للولادة في أي لحظة.;;;
ومع ذلك، قد تظهر بعض المشكلات في حالات الولادة التي تحدث قبل الأسبوع 38، حين يكتمل إنتاج المادة الخافضة للتوتر السطحي في الرئتين وتصبح الأمعاء قادرة على أداء وظائفها بالكامل. ويربط بعض الخبراء مشكلة المغص (آلام الغازات لدى الأطفال) بحدوث الولادة قبل اكتمال نضج الأمعاء بدرجة كافية.'), baby_message_ar = COALESCE(baby_message_ar, 'لقد أصبحت ممتلئ الجسم! 🧸 ماما، امتلأت وجنتاي وذراعاي وساقاي بالدهون. ولم أعد كثير التجاعيد كما كنت. يزداد وزني كل يوم. وستساعدني هذه الطبقة الدهنية على البقاء دافئًا ومفعمًا بالطاقة بعد ولادتي. وسأكون ناعمًا عندما تحملينني بين ذراعيكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خسّة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'لا تنسي أهمية تناول الفاكهة طوال فترة الحمل من أجلكِ ومن أجل طفلكِ. ومن هذه الفواكه الموز، الغني بالكالسيوم والبوتاسيوم وفيتامين C وحمض الفوليك وفيتامين B6. يساعد الموز على تلبية احتياجاتكِ من الحديد، وهو عنصر مهم جدًا أثناء الحمل. كما أنه غني جدًا بحمض الفوليك، الضروري لنمو العمود الفقري والجهاز العصبي لدى طفلكِ. ويحتوي الموز أيضًا على كمية جيدة من الكالسيوم الذي يحتاج إليه طفلكِ في عملية تكوّن العظام. لذلك ينبغي لكِ تناوله، خصوصًا لدعم النمو الصحي لعظام طفلكِ. ويُعد الموز أيضًا مصدرًا جيدًا لفيتامين B6، الذي يؤدي وظيفة ناقل عصبي في جهازكِ العصبي، كما يساهم في تكوين خلايا الدم الحمراء في جسمكِ. ويُعد الموز الغني بفيتامين C مضادًا جيدًا للأكسدة؛ لذا فهو يساعد على إبطاء شيخوخة الخلايا وتقوية جهازكِ المناعي. ويحتوي أيضًا على ألياف مفيدة للأمعاء. لكن نظرًا إلى بطء الجهاز الهضمي، قد يؤدي الإفراط في تناوله إلى الإمساك. لذلك يكفي أن تضيفي حبتين صغيرتين من الموز يوميًا إلى نظامكِ الغذائي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف ضيق التنفس، احرصي على إبقاء ظهركِ مستقيمًا عند الجلوس. ولتقليل الثقل والتورم في ساقيكِ، استريحي بانتظام مع رفعهما. وفي هذه الأيام، ابدئي بمراجعة محتويات حقيبة المستشفى تدريجيًا وتأكدي من أن كل شيء جاهز. وحاولي أن تكون وجبات العشاء خفيفة وصغيرة حتى لا تحرمكِ حرقة المعدة من النوم.') WHERE id = 'e948b641-0b79-4f83-9869-a66d090c81f1';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح جذع دماغ طفلكِ في موضعه، وبدأ في التحكم بعمليات مثل النوم واليقظة وحتى الأحلام. وتُعد هذه المنطقة الصغيرة الواقعة في الجزء السفلي من الدماغ بالغة الأهمية، لأن جميع الوصلات العصبية بين الدماغ والجسم تمر عبرها. وينظم جذع الدماغ الوظائف الحيوية مثل التنفس والبلع ونبض القلب. كما يبدأ في هذه المرحلة تشكّل الإيقاع اليومي لطفلكِ، أي ساعته البيولوجية. وينظم هذا الإيقاع تلقائيًا كيفية عمل الجسم على مدار 24 ساعة. فعلى سبيل المثال، يحدث إفراز هرمون الميلاتونين الذي يسبب النعاس ليلًا، أو ارتفاع ضغط الدم صباحًا، بفضل هذه الساعة البيولوجية.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خسّة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'ترجع مشكلات بشرتكِ إلى التغيرات الهرمونية التي تحدث أثناء الحمل. وبعد الولادة بفترة قصيرة، تبدأ مختلف مشكلات البشرة بالتحسن، ولا سيما تغيرات لون البشرة. وتظهر هذه التغيرات اللونية أساسًا على الوجنتين والشفة العليا والأنف والذقن والجبهة، على شكل بقع بنية فاتحة أو داكنة. وعادةً ما تختفي بعد الولادة هذه البقع المعروفة باسم «قناع الحمل».'), daily_tip_ar = COALESCE(daily_tip_ar, 'خصّصي اليوم وقتًا أطول للراحة. ولتخفيف آلام الحوض، احرصي على استخدام وسائد تدعم ظهركِ. وإذا لم تكوني قد فعلتِ ذلك بعد، فتأكدي من اكتمال المستندات التي ستأخذينها إلى المستشفى. وابتداءً من الغد، ندخل الأسبوع 37، أي مرحلة «الاستعداد» التي قد تحدث فيها الولادة في أي لحظة!') WHERE id = 'e930fbe3-29bc-4413-bfef-dc68f6603a0e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتكوّن الجهاز المناعي لطفلكِ بفضل الأجسام المضادة التي تنتقل منكِ إليه عبر المشيمة. الأجسام المضادة هي بروتينات سكرية، أي جزيئات عضوية تتكوّن من السكريات والأحماض الأمينية. ويُطلق اسم الأجسام المضادة على المواد الدفاعية التي ينتجها الجسم لمواجهة المواد الغريبة التي تدخله. يبدأ جسم طفلكِ بإنتاج أجسامه المضادة بعد مدة معينة من الولادة. وإلى أن يكوّن جهازه المناعي الخاص، يحمي نفسه من الكائنات الحية الدقيقة الضارة، التي تُسمى المستضدات، باستخدام الأجسام المضادة القادمة من جسمكِ. تقضي الأجسام المضادة في الدم على الكائنات الحية الدقيقة الضارة والفيروسات والجسيمات الغريبة الأخرى قبل دخولها إلى الخلايا. عندما تدخل أي بكتيريا إلى الدم، تتعرّف خلايا الجهاز المناعي، مثل الخلايا اللمفاوية والبلاعم، على البنية الجزيئية المختلفة الموجودة في جدار البكتيريا وتبدأ بإنتاج الأجسام المضادة. تتكوّن في الجسم خلية لمفاوية مخصّصة لكل مستضد، وتنتج الخلايا اللمفاوية بدورها الأجسام المضادة الخاصة بها. وينشأ عدم توافق فصائل الدم نتيجة التفاعل بين المستضدات والأجسام المضادة.'), baby_message_ar = COALESCE(baby_message_ar, 'لقد كبرت كثيرًا الآن. وأصبحت أشغل كل المساحة المتاحة تقريبًا داخل الرحم. لا أفعل الآن سوى اكتساب الوزن، إذ أزداد نحو 200-250 غرامًا أسبوعيًا. وأصبح خدّاي وذراعاي وساقاي ممتلئة ومستديرة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمّام'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه الأيام التي تقتربين فيها من نهاية الحمل، ربما ازدادت كثيرًا معاناتكِ من الوذمة والتورّم. تحدث الوذمة أساسًا نتيجة اضطراب الدورة الدموية. ففي الثلث الأخير من الحمل، يضغط الرحم الذي ازداد حجمه كثيرًا على الأوعية الدموية في حوضكِ وساقيكِ، ما يؤدي إلى إبطاء دورتكِ الدموية. وينتج عن تباطؤ الدورة الدموية حدوث الوذمة. وقد يشكّل هذا التورّم الناجم عن احتباس السوائل نحو 25% من الوزن المكتسب أثناء الحمل. لا يمكن التخلّص من الوذمة تمامًا خلال الحمل، لكن يمكن تقليلها إلى حد ما باتباع بعض التدابير، مثل ممارسة التمارين الرياضية بانتظام يوميًا، وتجنّب الجلوس أو الوقوف لفترات طويلة، ورفع ساقيكِ خلال النهار للمساعدة على تنشيط الدورة الدموية، والاستلقاء على الجانب الأيسر عند النوم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي تمارين كيجل. فهي الطريقة الأكثر فعالية للوقاية من مشكلة سلس البول بعد الولادة. مارسيها 3 مرات يوميًا، وكرّري التمرين 10 مرات في كل مرة.') WHERE id = 'f7c92a09-eddb-4b29-936d-0133e3378e1e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يرجع سبب عدم اكتمال نمو الجهاز المناعي لطفلكِ قبل الولادة، بأبسط تعبير، إلى أنه يعيش داخل جسمكِ. فطوال وجود طفلكِ داخل الرحم، يظل جهازه المناعي في حالة تثبيط. وهكذا تستطيع خلاياه الدفاعية وخلايا جسمكِ الدفاعية التعايش معًا دون مهاجمة بعضها بعضًا. وبدءًا من الولادة، يبدأ الجهاز المناعي بالنمو وإنتاج عامل دفاعي آخر ذي بنية بروتينية سكرية يُسمى الإنترفيرون، إلى جانب الأجسام المضادة. الإنترفيرون هو بروتين سكري تنتجه خلايا الجسم بوصفه استجابة دفاعية ضد الفيروسات. تمنع الإنترفيرونات تكاثر الفيروسات داخل الخلايا، وهي من أسرع عوامل الدفاع التي ينتجها الجسم ومن أقواها في مقاومة الفيروسات. ويبدأ إنتاجها عندما تستشعر الخلايا وجود فيروس أو مادة غريبة أخرى. وتعمل على النحو الآتي: عندما تتعرض خلية لهجوم فيروسي، يُفعّل جين في الحمض النووي للخلية مسؤول عن إنتاج الإنترفيرون. ثم تحفّز الإنترفيرونات المُفرزة الخلايا المحيطة على إنتاج بروتينات تغيّر عملية تصنيع البروتين بطريقة تمنع الفيروس من مواصلة التكاثر داخل الخلايا. وبهذه الطريقة يُمنع انتشار الفيروسات في الجسم.'), baby_message_ar = COALESCE(baby_message_ar, 'يبدو أن رأسي أصبح متجهًا إلى الأسفل! ⬇️ لقد اتخذت وضعية الولادة، ودخل رأسي بين عظام حوضكِ. هذا غير مريح قليلًا بالنسبة إليّ، لكنه أقرب طريق إلى الخارج. وإذا لم أكن قد استدرت بعد، فقد يوصيكِ طبيبكِ ببعض التمارين.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمّام'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين بأن تنفّسكِ أصبح أسهل قليلًا. فمع نزول طفلكِ إلى الأسفل، يقل الضغط على الرئتين والمعدة. ويمكنكِ الآن التنفّس براحة أكبر وتناول كمية أكبر من الطعام. لكن في المقابل، يزداد الضغط على منطقة الأربية والمثانة.;;;
وإلى جانب ذلك، قد تشعرين بأن تنفّسكِ أصبح أسهل قليلًا. فمع نزول طفلكِ إلى الأسفل، يقل الضغط على الرئتين والمعدة. ويمكنكِ الآن التنفّس براحة أكبر وتناول كمية أكبر من الطعام. لكن في المقابل، يزداد الضغط على منطقة الأربية والمثانة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'كافئي نفسكِ اليوم واستريحي احتفاءً باجتيازكِ بنجاح هذه الرحلة التي استمرت 35 أسبوعًا. احرصي على استخدام وسائد تدعم ظهركِ لتخفيف آلامه. وإذا كان طفلكِ قد نزل إلى الأسفل وكنتِ تشعرين بألم في الحوض أثناء المشي، فتحرّكي ببطء وهدوء أكبر. واعتبارًا من الغد، نبدأ الأسبوع 36، أي المنعطف الكبير الأخير في طريقنا نحو الولادة!') WHERE id = '3e398e58-41a7-4c07-9c59-78972adc37be';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يستمر تراكم العِقي في أمعاء طفلكِ. والعِقي هو الاسم الذي يُطلق على البراز الأول لطفلكِ، ويكون شديد اللزوجة وذا لون أخضر داكن أو أسود. تتكوّن هذه المادة بنسبة %90 من الماء، وتحتوي أيضًا على شعر الزغب المتساقط من جلد طفلكِ، وخلايا ظهارة الأمعاء، والمخاط، والعصارة الصفراوية. ويُعد ارتفاع محتوى العِقي من البيليروبين أحد أهم أسباب اليرقان لدى حديثي الولادة. وقد تُلاحظ مستويات يرقان أعلى من الطبيعي لدى الأطفال الذين لا يطرحون العِقي عبر الشرج خلال أول 48 ساعة بعد الولادة. البيليروبين مادة صفراء تنتج بصورة طبيعية عندما يحلّل الجسم خلايا الدم الحمراء. وتُعالَج هذه المادة في الكبد ثم يتخلص منها الجسم أثناء عملية الهضم. أما لدى طفلكِ، فيظل الشرج مغلقًا حتى لحظة الولادة، لذلك يتراكم البيليروبين ضمن العِقي في الأمعاء الغليظة. وإذا لم يتخلص الجسم من هذا العِقي خلال مدة معينة بعد الولادة، تمتص الأمعاء البيليروبين وتعيده إلى الدم، وقد يؤدي ارتفاع مستواه في الدم بدرجة كبيرة إلى الإصابة باليرقان.'), baby_message_ar = COALESCE(baby_message_ar, 'أحلامي واضحة ونابضة بالحياة! ماما، أقضي وقتًا طويلًا في مرحلة نوم حركة العين السريعة. إن دماغي نشط للغاية! وعندما أكون مستيقظًا، أراقب ما حولي بعينيّ، رغم أن المكان مظلم. أستطيع التمييز بين الضوء والظل بصورة ممتازة. حتى لو لم تتمكني من رؤيتي، فأنا أشعر بكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'رأس خس كبير'), body_changes_ar = COALESCE(body_changes_ar, 'قد يجعلكِ الأرق سريعة الانفعال. فلا يمكنكِ النوم براحة، وتشعرين بالألم في أنحاء جسمكِ. كما لا تفارق ذهنكِ أفكار مثل: «كيف ستكون الولادة؟». هذه طريقة الطبيعة في إعدادكِ للاستيقاظ ليلًا من أجل رعاية طفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يُنصح بأن تراجعي طبيبكِ أسبوعيًا ابتداءً من هذا الأسبوع. افحصي حقيبة الولادة للمرة الأخيرة، وأكملي التفاصيل الصغيرة الناقصة. ولتخفيف آلام الحوض، لا تضعي ساقًا فوق الأخرى أثناء الجلوس، ولا تبقي في الوضعية نفسها مدة طويلة. واصلي الاستراحة بالاستلقاء على جانبكِ الأيسر ومراقبة حركات طفلكِ خلال اليوم.') WHERE id = 'df4bd1af-d6a3-4228-b3e2-3e6d8392ce93';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ كبد طفلكِ بالفعل في تنقية بعض الفضلات والمشاركة في عملية الهضم. ويؤدي هذا العضو الحيوي دور نوع من «المختبر» داخل جسم طفلكِ:;;;
• التنقية: يحوّل الكبد الأمونيا السامة الموجودة في الجسم إلى مواد أقل ضررًا، ويفكك خلايا الدم الهرمة ليساعد على التخلص منها خارج الجسم.;;;
• الطاقة والهضم: يعالج العناصر المستمدة من الغذاء ويوزعها على الأعضاء الأخرى. كما ينتج العصارة الصفراوية الضرورية لهضم الدهون والبروتينات.;;;
• جهاز المناعة: ينتج الأجسام المضادة التي تعزز المناعة، ويساعد على تنظيم درجة حرارة الجسم.;;;
• البروتينات المهمة: يتولى إنتاج بروتين الألبومين الذي يساعد على إبقاء الدم داخل الأوعية الدموية.;;;
باختصار، ينقّي كبد طفلكِ جسمه ويستعد أيضًا لحمايته من الأمراض.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا آكل شعري! 😮 (أعرف أن هذا يبدو غريبًا بعض الشيء). بدأ ذلك الشعر الناعم المسمى «لانوغو» وطبقة «الطلاء الجبني» اللذان يغطيان جسمي بالتساقط. وأنا أبتلعهما مع السائل الأمنيوسي. يتجمعان في أمعائي ويكوّنان برازي الأول (العِقي). سترينه عندما تغيّرين حفاضتي الأولى!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'السلق'), body_changes_ar = COALESCE(body_changes_ar, 'يُحاوَل تعويض العناصر التي لا يمكن الحصول عليها بكميات كافية من الطعام خلال حملكِ بواسطة المكملات التي يوصي بها طبيبكِ. وتشمل هذه المكملات حمض الفوليك والحديد والكالسيوم والمغنيسيوم والزنك وفيتامين D وأحماض أوميغا الدهنية. ومن المعادن التي توصف لجميع الحوامل تقريبًا بدءًا من الثلث الثاني من الحمل الحديد. فالحديد مهم جدًا لإنتاج الدم لديكِ ولدى طفلكِ، ويساعد على الوقاية من خطر الإصابة بفقر الدم. كما أن نقص الحديد يزيد خطر ولادة طفلكِ بوزن أقل من المتوسط. وقد تُوصف أيضًا مجموعة متكاملة من الفيتامينات الأخرى. وعلى الرغم من فائدتها الكبيرة، يجب ألا تستخدمي هذه المكملات من دون توصية طبيبكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بما أن طفلكِ قد اكتمل نموه، فكوني منتبهة لعلامات بدء المخاض. مارسي بانتظام تمارين تمدد خفيفة لتخفيف آلام الحوض، وتجنبي رفع الأشياء الثقيلة. ضعي حقيبة الولادة بجوار الباب، ونسّقي للمرة الأخيرة مع طبيبكِ. لا ترهقي نفسكِ كثيرًا اليوم، وادّخري طاقتكِ لليوم المنتظر.') WHERE id = 'cc423b6f-434a-47b7-97ce-c5b407e5861b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبحت جميع وظائف جسم طفلكِ الآن مكتملة وقادرة على العمل، ويشمل ذلك أعضاء الحواس. وقد تطورت المنطقة الدماغية التي تتحكم في مركز الإحساس تحديدًا إلى درجة جعلت طفلكِ حساسًا بما يكفي للاستجابة لصوتكِ. يتكون دماغ طفلكِ من نصفين كرويين، أيسر وأيمن. ويرتبط هذان النصفان ببعضهما بواسطة ألياف عصبية معقدة تتيح لهما التواصل المستمر. تتمثل المهمة الأساسية للدماغ في الحفاظ على صحة الجسم واستمرار الحياة من خلال تنظيم وظائف الأعضاء الداخلية. وفي الوقت نفسه، يعالج جميع الإشارات الواردة من البيئة عبر أعضاء الحواس ويفسرها ويخزن ما يلزم منها في الذاكرة. وبفضل حاسة السمع، بدأ طفلكِ بالفعل في استخدام النصف الأيمن من دماغه بنشاط كبير. وقدرته على تمييز صوتكِ عن الأصوات الخارجية الأخرى أصبحت ممكنة بفضل هذا التطور في الدماغ والجهاز العصبي.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أنزل إلى الأسفل! 📉 هل تشعرين بذلك؟ استقر رأسي تمامًا داخل حوضكِ. المكان ضيق قليلًا بالنسبة إليّ، لكنه الأقرب إلى المخرج. من المرجح أنكِ تتنفسين بسهولة أكبر الآن، لكنكِ تذهبين إلى الحمام بوتيرة أكثر.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'السلق'), body_changes_ar = COALESCE(body_changes_ar, 'يُعد اتباعكِ نظامًا غذائيًا متوازنًا ومنتظمًا خلال الحمل بالغ الأهمية لنمو طفلكِ بصورة صحية. ومن أهم الأطعمة التي تدعم نمو طفلكِ المكسرات والبذور التي تؤكل نيئة. فهي غنية جدًا بالأحماض الدهنية غير المشبعة والسيلينيوم ومختلف الفيتامينات والمعادن. يؤدي الجوز دورًا فعالًا في نمو دماغ طفلكِ، كما يتميز بخصائص مضادة للأكسدة ويُعد مصدرًا جيدًا للألياف والبروتين. والفستق من البذور التي يُنصح بتناولها للمساعدة على تلبية حاجة جسمكِ إلى الأحماض الدهنية خلال الحمل. أما البندق فيدعم نمو عظام طفلكِ بدرجة كبيرة بفضل احتوائه على الكالسيوم، كما أنه مصدر جيد للطاقة. واللوز غني جدًا بالفيتامينات والمعادن، ويساعد بفضل غناه بالزنك خصوصًا على تحسين جودة حليبكِ بعد الولادة. ويساعد الكاجو، بفضل احتوائه على النحاس، على تلبية احتياج جسمكِ اليومي من هذا المعدن. أما التين المجفف فهو غني جدًا بالزنك والحديد والبوتاسيوم والكالسيوم، ويمكنكِ من خلال تناوله الحصول على المعادن التي يحتاج إليها طفلكِ خلال مرحلة نموه. وعلى الرغم من الفوائد الكبيرة للمكسرات والبذور، فإن قيمتها الغذائية وسعراتها الحرارية مرتفعة لكونها من البذور الزيتية؛ لذا ينبغي ألا تتجاوز الكمية المتناولة منها حفنة واحدة يوميًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حافظي على طاقتكِ لأنكِ في مرحلة قد يبدأ فيها المخاض في أي لحظة. قللي تناول الملح واشربي الكثير من الماء لتخفيف تورم القدمين. إذا كانت تقلصات براكستون هيكس غير منتظمة، فهي مجرد تدريب لجسمكِ، فلا تقلقي. خصصي لنفسكِ بعض الوقت اليوم، وهدّئي نفسكِ بالنظر إلى الغرفة أو الملابس التي أعددتِها لطفلكِ.') WHERE id = 'cd1a59da-8207-4de3-b297-f013b1d7c429';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن الهيكل العظمي لطفلكِ يتكون حاليًا بصورة أساسية من الغضاريف، فإنه يواصل التعظّم بسرعة. وفي هذه المرحلة يمتص طفلكِ تقريبًا كل الكالسيوم الذي تحصلين عليه. وإذا لم يحتوِ غذاؤكِ على كمية كافية من الكالسيوم، فسيستمد حاجته منه من مخزون الكالسيوم في عظامكِ.;;;
للنسيج الغضروفي خاصية مثيرة للاهتمام، إذ لا يحتوي على أوعية دموية أو أعصاب. وتحصل خلايا غضاريف طفلكِ على الأكسجين والغذاء اللازمين من الأنسجة المحيطة عن طريق الانتشار، وتتخلص من الفضلات بالطريقة نفسها. وتسمى هذه الخلايا التي تكوّن الهيكل العظمي لطفلكِ بالغضروف الليفي. وهذا النسيج شديد المقاومة للضغط والحركة لأنه يحتوي على كمية وفيرة من ألياف الكولاجين. وتتكون ألياف الكولاجين أساسًا من البروتين، وهي التي تمنح الأنسجة المرونة والمتانة.'), baby_message_ar = COALESCE(baby_message_ar, 'هل تنتظرينني؟ ⏳ أعرف أنكِ متلهفة. وتسألين: «متى ستأتي؟». لكنني لم أصبح مستعدًا تمامًا بعد. لا يزال دماغي ينمو، ورئتاي تُجريان استعداداتهما الأخيرة. كل يوم أبقى فيه داخل رحمكِ يجعلني أقوى. تحلّي بالصبر يا ماما.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'السلق'), body_changes_ar = COALESCE(body_changes_ar, 'على الرغم من أن السبب الدقيق الذي يحفّز بدء المخاض غير معروف، فمن المعلوم أن مستوى هرمون البروستاغلاندين الذي ينتجه الرحم في أواخر الحمل يرتفع بدرجة كبيرة أثناء الولادة. ويعمل هذا الهرمون، الذي تدخل الأحماض الدهنية في تركيبه، كمركّب كيميائي يزيد حساسية مستقبلات الألم للمحفزات الميكانيكية والكيميائية. وفي حين أنه يسبب تقلصات الدورة الشهرية خارج فترة الحمل، فإنه يحفز انقباض عضلات الرحم أثناء الولادة.;;;
إضافة إلى ذلك، تبدأ الأمعاء بالإفراغ بوتيرة أكثر في الأيام الأخيرة من الحمل. وقد تسبب هذه الحالة الشعور بألم في منطقة البطن. ويُعد الإسهال الذي يحدث قبل الولادة جزءًا من استعداد الجسم لها، إذ يساعد على تنظيف الأمعاء ويتيح لعضلات الرحم العمل براحة أكبر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لمواجهة الأرق في هذه المرحلة، خذي قيلولات قصيرة مدة كل منها 15-20 دقيقة خلال النهار. ارفعي ساقيكِ بانتظام للمساعدة على تقليل الوذمة. وإذا لم تكوني قد فعلتِ ذلك بعد، فثبّتي مقعد السيارة المخصص لطفلكِ وافحصيه استعدادًا للعودة به من المستشفى إلى المنزل. لا ترهقي نفسكِ اليوم، وتحركي بهدوء وتأنٍّ.') WHERE id = 'ff965161-e8f2-4262-b993-4dbf99f22a66';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تزداد قوة ردود فعل طفلكِ يومًا بعد يوم. ورغم أنه لا يستطيع الكلام بعد، فإنه يدرك محيطه ويحمي نفسه ويتواصل معكِ من خلال هذه الحركات اللاإرادية. وبفضل منعكس التوجّه، يكون طفلكِ حساسًا للضوء، وما إن يراه حتى يدير رأسه نحوه محاولًا استكشاف محيطه. أما منعكسا البحث والمص، وهما من أهم ردود الفعل، فيساعدانه على الرضاعة؛ فعندما تلمسين جانب فمه، يدير رأسه فورًا نحو تلك الجهة ويبدأ بالبحث عن الحليب. وبعد نحو 3-4 أشهر، تتحول هذه الاستجابة إلى حركة إرادية. ويُعد منعكس الرمش إحدى آليات الحماية الذاتية لدى طفلكِ؛ فعندما يرى ضوءًا قويًا وساطعًا، يرمش بعينيه ليحمي نفسه من الانزعاج. وتُعد هذه المنعكسات كلها من أهم المؤشرات على نمو طفلكِ بصورة صحية وعمل جهازه العصبي بشكل سليم.'), baby_message_ar = COALESCE(baby_message_ar, 'حركاتي تتغير! 🛑 لأن المساحة حولي أصبحت ضيقة جدًا، لم يعد بإمكاني توجيه ركلات قوية. وبدلًا من ذلك، تشعرين بي وأنا "أنزلق" و"أدور". ورغم تغيّر طبيعة حركاتي، ينبغي ألا يقل تواترها. يجب أن أبقى نشيطًا كل يوم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'السلق'), body_changes_ar = COALESCE(body_changes_ar, 'توجد بعض العلامات التي تظهر على جسمكِ مع اقتراب الولادة. وقد تبدأ التغيرات الجسدية التي تسبق الولادة قبلها بساعات، أو حتى قبلها بشهر. ومن هذه العلامات حالة تحدث خصوصًا في الشهر الأخير، وتُعرف شائعًا باسم "نزول البطن إلى الأسفل". وإذا كان هذا حملكِ الأول على وجه الخصوص، فعادةً ما يبدأ طفلكِ بالنزول نحو الحوض خلال الشهر الذي يسبق بدء المخاض. ومع استقرار طفلكِ في قناة الولادة، قد تشعرين بضغط في المهبل والمستقيم، ويعود ذلك إلى ضغطه على عظام حوضكِ.;;;
مع اقتراب الولادة، تلاحظ نصف النساء تقريبًا توقف زيادة الوزن، بل وقد يفقدن 1-2 كيلوغرام. ورغم أن السبب الدقيق لذلك غير معروف، فقد يُعزى إلى تسارع حركة الأمعاء وتباطؤ زيادة وزن الطفل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'الأرق طبيعي في هذه المرحلة، لذلك ستمنحكِ القيلولات القصيرة خلال النهار بعض الطاقة. خصصي لنفسكِ بعض الوقت هذا المساء وتحدثي إلى طفلكِ، فهو يعرف صوتكِ المفعم بالحب جيدًا الآن.') WHERE id = '152b266a-9f3e-44b6-ad2a-c45afaa30675';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تهانينا! لقد أتممتِ 8 أشهر من حملكِ وتدخلين الآن الشهر الأخير، وأصبح طفلكِ مستعدًا للمجيء إلى العالم في أي لحظة. في هذه المرحلة، يعمل كبد طفلكِ وكليتاه بكامل طاقتهما، كما يعمل جهازاه الدوري والمناعي بصورة جيدة. وهو يتدرب باستمرار على التنفس بصورة مستقلة والتكيف مع الحياة. يغطي جسم طفلكِ بالكامل غشاء أبيض دهني يُسمى "الطلاء الجبني". وتعمل هذه الطبقة المميزة كدرع طبيعي يحمي المولود الجديد، الذي لم يكتمل جهازه المناعي بعد، من الجراثيم. كما تسهّل هذه الطبقة الدهنية التكيف مع اختلاف درجة الحرارة بين الرحم والبيئة الخارجية، وتحمي الطفل من التعرض لصدمة حرارية. باختصار، يستعد طفلكِ للمجيء إلى العالم محميًا من التأثيرات السلبية للبيئة الخارجية بفضل هذا الكريم الطبيعي الواقي.'), baby_message_ar = COALESCE(baby_message_ar, 'هل أتدرب على البكاء؟ 😢 يقول بعض العلماء إنني أقوم بحركات "البكاء" بصمت داخل الرحم، فأُرعش ذقني وأغيّر نمط تنفسي. وهذا مهم لكي أرسل إليكِ إشارات بعد الولادة. فالبكاء سيكون وسيلتي الوحيدة للتواصل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'السلق'), body_changes_ar = COALESCE(body_changes_ar, 'قد تصبح بشرتكِ شديدة الحساسية. فقد تمدد جلد بطنكِ إلى درجة أنه يبدو لامعًا. وإذا أزعجتكِ الحكة، فضعي كمادة باردة. كما يساعد شرب الكثير من السوائل على ترطيب البشرة من الداخل.;;;
قد يستمر تورم يديكِ وقدميكِ حتى الصباح. لا ترتدي خاتمكِ. وقد يزعج نومكِ أيضًا خدر ذراعيكِ ليلًا. ومن المهم جدًا مراقبة ضغط دمكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام الحوض، ضعي وسادة بين ركبتيكِ عند النوم واحرصي على الاستلقاء على جانبكِ الأيسر. واصلي شرب الكثير من الماء لتقليل الوذمة، فالماء يساعد الجسم على التخلص من السوائل الزائدة. راجعي خلال هذه الأيام المعلومات المتعلقة بالعلامات المبكرة للمخاض. حاولي الحفاظ على هدوئكِ وطمأنينتكِ، فاليوم المنتظر بات قريبًا جدًا!') WHERE id = '225c7f32-cf83-462a-bfe6-21c45812a3e6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يواصل طفلكِ اكتساب الوزن بسرعة، إذ يخزن نحو 15-20 غرامًا من الدهون يوميًا. ورغم خفة هذه الخلايا الدهنية، فإنها تشغل مساحة كبيرة وتُعد أغنى مصدر للطاقة لدى طفلكِ. ولا تقتصر وظيفة الدهون المتراكمة في الجسم على توفير الطاقة، بل تؤدي أيضًا دورًا مهمًا في تكوين الأغشية الواقية للخلايا الأخرى، ونقل فيتامينات A وD وE وK إلى الدم، وإنتاج الهرمونات الضرورية للنمو. أما أهم وظائف هذا النسيج الدهني، فهي تكوين طبقة واقية تحت الجلد لحماية طفلكِ من البرد وتغيرات درجات الحرارة. كما تحيط هذه الدهون بالأعضاء الداخلية وتوفر مخزونًا من الطاقة يمكن لطفلكِ الاستفادة منه عند الحاجة.'), baby_message_ar = COALESCE(baby_message_ar, 'أجمع الأجسام المضادة! 🛡️ بلغت الخلايا المناعية التي تنتقل إليّ من دمكِ أعلى مستوياتها. عندما أولد، لن أكون بلا حماية تمامًا في مواجهة جراثيم العالم. فكل مرض أُصبتِ به وتعافيتِ منه ينتقل إليّ كدرع واقٍ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الشمام الشتوي'), body_changes_ar = COALESCE(body_changes_ar, 'في المراحل الأخيرة من الحمل، يؤدي ترقق عنق الرحم وبدء اتساعه إلى خروج السدادة المخاطية التي كانت تغلقه. وتُعرف هذه السدادة المخاطية شائعًا باسم "علامة الولادة"، ويشير خروجها إلى اقتراب بدء تقلصات المخاض الحقيقية. وقد يكون لونها أحمر فاتحًا أو ورديًا أو بنيًا أو مائلًا إلى الصفرة. وهناك عدة عوامل تحدد لونها.;;;
قد تخرج السدادة قبل الولادة بساعات، كما قد يطرحها الجسم قبلها بأسبوع. ولا يعني خروجها أنكِ بحاجة إلى الذهاب إلى المستشفى فورًا، لكن من المهم إبلاغ طبيبكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اعتني ببشرتكِ. يساعد تدليكها بالزيوت الطبيعية (اللوز والكاكاو) على تخفيف الشد. لا ترتدي الملابس المصنوعة من الألياف الصناعية، فالقطن هو الخيار الأفضل.') WHERE id = '58a80f20-6823-4c80-8b83-b7ba46702490';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتراوح وزن طفلكِ هذا الأسبوع في المتوسط بين 2400 و2800 غرام، وطوله بين 46 و52 سم؛ وتزداد لثته صلابة، فيما تصبح بشرته أكثر نعومة وملمسًا حريريًا تدريجيًا. في هذه المرحلة، يكون منعكس القبض لدى طفلكِ متطورًا للغاية، وهو أحد المؤشرات الأساسية على سلامة عمل جهازه العصبي. يظهر منعكس القبض بوضوح في اليدين والقدمين، وهو استجابة لا إرادية للمحفزات. تتكوّن هذه الحركة قبل الولادة، وتظل نشطة خلال الشهرين الأولين بعدها، ثم تضعف تدريجيًا لتحل محلها حركة الإمساك الإرادية. ومن المثير للاهتمام أن منعكس القبض في القدمين يستمر مدة أطول مقارنة باليدين، وقد يستغرق تحوله إلى حركة إرادية حتى الشهر السادس.'), baby_message_ar = COALESCE(baby_message_ar, 'الأسبوع 37! 🎉 تهانينا يا ماما! اليوم يوم مهم. لم أعد أُعدّ مولودًا «مبتسرًا»! لقد دخلت رسميًا مرحلة «تمام الحمل المبكر». وهذا يعني أنني إذا وُلدت الآن، فسأُعدّ طفلًا مكتمل النمو. يقترب وزني من 3 كغ. قد آتي إلى العالم في أي لحظة! هل حقيبتكِ جاهزة؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام شتوي'), body_changes_ar = COALESCE(body_changes_ar, 'محطة مهمة: تمام الحمل المبكر! قد يبدأ المخاض الآن في أي لحظة، ويُعدّ طفلكِ «مولودًا في موعده». قد يفحص طبيبكِ حالة عنق الرحم، بما في ذلك مدى اتساعه وليونته. استعدادًا للولادة، يتحرك عنق الرحم إلى الأمام ويصبح أكثر ليونة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'افتخري بنفسكِ لأنكِ اجتزتِ بنجاح هذه الرحلة الرائعة التي استمرت 37 أسبوعًا! استريحي اليوم قدر الإمكان للحفاظ على طاقتكِ. ضعي حقيبة الولادة بجانب الباب، وتأكدي من اكتمال جميع المستندات. إذا شعرتِ بآلام منتظمة ومتزايدة الشدة في بطنكِ أو نزل ماء الجنين، فتواصلي فورًا مع طبيبكِ. تحلّي بالصبر، فلم يتبقَّ سوى القليل على قدوم المعجزة!') WHERE id = 'cca07f51-052d-4eba-bb6f-e780658e5cc2';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتراوح وزن طفلكِ هذا الأسبوع في المتوسط بين 2500 و2900 غرام، وطوله بين 48 و52 سم. وبما أن إنتاج المادة الخاصة التي تساعد على التنفس في الرئتين، وهي السورفاكتانت، قد اكتمل، فقد أصبح قادرًا على التنفس تلقائيًا من دون مساعدة فور ولادته.;;;
نظرًا إلى نمو طفلكِ وضيق المساحة داخل الرحم، قد تقل حركاته قليلًا مقارنة بالأسابيع السابقة، لكنها تصبح أقوى وأكثر وضوحًا. يُعدّ هذا طبيعيًا ابتداءً من الأسبوع 37، لكن إذا لم تشعري بحركته مدة طويلة، فمن الأفضل استشارة طبيبكِ. كذلك، تقل كمية السائل الأمنيوسي في الرحم قليلًا مع نمو طفلكِ. ويكون ذلك طبيعيًا عادةً، ولكن إذا انخفضت كمية السائل إلى مستوى قد يشكّل خطرًا على طفلكِ، فقد يُدخلكِ طبيبكِ إلى المستشفى للمراقبة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتدرّب! 🏋️‍♂️ عملية الولادة ليست شاقة عليكِ وحدكِ، بل عليّ أيضًا. يجب أن أضغط جسمي وأدير رأسي وأدفع لأعبر القناة الضيقة. أتدرّب الآن على هذه الحركات. سنعمل كفريق يا ماما. ستفتحين لي الطريق، وسآتي إلى العالم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'شمام شتوي'), body_changes_ar = COALESCE(body_changes_ar, 'ستساعدكِ تمارين البيلاتس التي مارستِها خلال الحمل خصوصًا على الاستعداد للولادة، وستجعل هذه العملية أكثر راحة. يتغير مركز توازن جسمكِ باستمرار بسبب تغيّر موضع الرحم مع نمو بطنكِ خلال الحمل. تساعد تمارين البيلاتس على تصحيح اضطرابات وضعية الجسم الناجمة عن هذه التغيرات في التوازن، ما يمنحكِ قوامًا أفضل. كما تسهم في تخفيف آلام ظهركِ وأسفل ظهركِ.;;;
إلى جانب ذلك كله، يجب أن تكون تمارين البيلاتس مناسبة للحمل، وأن تؤدَّى حتمًا بمساعدة مختصين في هذا المجال. تذكّري أن أداء الحركات الخاطئة بطريقة غير احترافية قد يضر بكِ وبطفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بما أن المخاض قد يبدأ في أي لحظة، فاستريحي كثيرًا للحفاظ على طاقتكِ. عند مغادرة المنزل، تأكدي من أن هاتفكِ مشحون بالكامل وأن حقيبة المستشفى موجودة في السيارة. إذا خرجت السدادة المخاطية أو نزل ماء الجنين، فأخبري طبيبكِ فورًا.') WHERE id = '9bb1bfbd-4fc9-4fdd-8462-715ca0719a8a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يكون طفلكِ قد اتخذ هذا الأسبوع الوضعية الأنسب للولادة المهبلية، واستقر في قناة الولادة ورأسه إلى الأسفل. إذا كان هذا حملكِ الأول خصوصًا، فقد تلاحظين ذلك من خلال الشعور بالثقل في منطقة الحوض وصعوبة المشي. ويمنحكِ نزول طفلكِ إلى الأسفل بعض الراحة أيضًا؛ فمع انخفاض الضغط على القفص الصدري والمعدة، تبدئين بالتنفس بسهولة أكبر وتقل أعراض حرقة المعدة لديكِ.;;;
ومن المثير للاهتمام أن الأطفال يتخذون هذه الوضعية قبل الولادة بشهر في الحمل الأول، بينما قد لا يحدث ذلك في الأحمال اللاحقة إلا قبل الولادة بساعات قليلة. كذلك، يكون شعر الزغب الناعم الذي كان يغطي جسم طفلكِ قد تساقط بالكامل هذا الأسبوع. وهذا يعني أن طفلكِ قد تطور بما يكفي للحفاظ على حرارة جسمه بنفسه بفضل خلاياه الدهنية، وأصبح مستعدًا تمامًا للقدوم إلى العالم.'), baby_message_ar = COALESCE(baby_message_ar, 'أصبح حجمي بحجم ثمرة يقطين. لقد أصبحت طفلًا كبيرًا. المكان ضيق جدًا لدرجة أنني لم أعد أستطيع الركل، بل أتمدد فقط. قد تتمكنين من رؤية كعب قدمي بارزًا عبر بطنكِ. المسيني!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطين'), body_changes_ar = COALESCE(body_changes_ar, 'يكاد النوم يكون معدومًا. الاستيقاظ كل ساعة ليلًا، والذهاب إلى المرحاض، وعدم القدرة على النوم براحة... هكذا يهيئكِ جسمكِ لاستيقاظ طفلكِ ليلًا. حاولي النوم بعد الظهر. حافظي على طاقتكِ، فستحتاجين إليها أثناء الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد يساعدكِ الاستماع قبل النوم إلى تسجيلات التأمل أو «الولادة بالتنويم المغناطيسي» (Hypnobirthing) على الاسترخاء والاستغراق في النوم. الخوف يسبب التوتر، أما الهدوء فيسهّل الولادة.') WHERE id = '01bba5ce-c513-4ffc-af67-bbc602f0ece1';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لم يكتمل تعظّم الهيكل العظمي لطفلكِ بعد، لذا لا يزال لينًا ومرنًا للغاية. وتسمح هذه المرونة لجسمه بالانثناء بسهولة أثناء مروره عبر قناة الولادة، ما يساعده على الخروج دون مضاعفات. وفي الوقت نفسه، أصبحت طبقة "الطلاء الجبني" السميكة التي تغطي جلد طفلكِ مكتملة السماكة؛ إذ تحمي جلده من تأثير السائل الأمنيوسي وتمنع تجعّده.;;;
يكاد جسم طفلكِ يكون مغطى بالكامل بشعيرات لا تُرى بالعين المجردة، وبمادة دهنية تُسمى "الزهم" تفرزها الغدد الموجودة عند جذور هذه الشعيرات. ويكوّن بروتين الكيراتين الموجود في الزهم طبقة عازلة للماء على الجلد، ما يحافظ على نعومته ويمنع تجعّده رغم بقائه في الماء مدة طويلة. لكن أطراف الأصابع وراحتي اليدين وأخمصي القدمين لا تحتوي على شعر أو طبقة سميكة من الكيراتين، ولذلك يتسرب الماء إلى هذه المناطق؛ ولهذا يُلاحظ التجعّد فيها تحديدًا عند ولادة الطفل.'), baby_message_ar = COALESCE(baby_message_ar, 'ليست لديّ دموع! 💧 عندما أولد سأبكي بصوت عالٍ ("واااه!"), لكن الدموع لن تنهمر من عينيّ. فقنواتي الدمعية لم تنفتح بالكامل بعد. وستظهر دموعي الحقيقية بعد عدة أسابيع من الولادة. أما أحبالي الصوتية؟ فهي تعمل بكامل طاقتها، وستسمعين صوتي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'اليقطين'), body_changes_ar = COALESCE(body_changes_ar, 'قد تعانين من حرقة المعدة أيضًا نتيجة عودة الغثيان والقيء وفقدان الشهية خلال الأسابيع الأخيرة من الحمل. ولأن معدتكِ تتعرض لضغط الرحم، فقد يساعدكِ تناول وجبات صغيرة ومتكررة، وتقليل حجم الحصص، وتجنب شرب السوائل مع الطعام على تخفيف هذه المشكلة. بالإضافة إلى ذلك، ينبغي ألا تستلقي أو تنامي مباشرة بعد تناول الطعام، واحرصي على عدم البقاء دون حركة. ويمكنكِ القيام بنزهات قصيرة وبطيئة للمساعدة على هضم الطعام. كما تُعد زيادة الوزن المفرطة، ولا سيما في أواخر الحمل، من العوامل المسببة لحرقة المعدة. لذلك حاولي ألا تتناولي كمية كبيرة جدًا من السعرات الحرارية في وجبة واحدة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تقلقي عند خروج "السدادة المخاطية"، فهذا أمر طبيعي. لكن إذا كان النزيف غزيرًا مثل نزيف الدورة الشهرية ولونه أحمر فاتح، فتوجهي إلى المستشفى فورًا.') WHERE id = '9cfe44a2-80b6-4626-b317-1135744027c8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد تظنين أنه لا يزال هناك وقت حتى اكتمال 40 أسبوعًا، لكن تذكري أن نحو 80% من حالات الحمل تنتهي بالفعل بحلول الأسبوع 39. وفي حالات الحمل الصحية والطبيعية، يمكن أن تبدأ الولادة في أي وقت بين الأسبوعين 37 و42، لأن نمو الطفل يكون قد اكتمل وأصبح مستعدًا للولادة. لقد اكتمل نضج طفلكِ الآن، ولم يتبقَ سوى وقت قصير جدًا حتى تلتقي به.;;;
بينما لم يكن وزن طفلكِ يزداد في الأسابيع الأولى إلا بمقدار 1-2 غرام، ارتفع هذا المعدل في المراحل الأخيرة، مع تكوّن الخلايا الدهنية، ليصل في المتوسط إلى نصف كيلوغرام أسبوعيًا. وتُعد زيادة وزن الطفل السريعة مع اقتراب موعد الولادة ضرورية لمساعدته على التكيف مع العالم الخارجي والحفاظ على درجة حرارة جسمه بصورة مستقلة. ومع ذلك، ينبغي مراعاة أن معدل زيادة الوزن قد يختلف من طفل إلى آخر بحسب الجنس والعوامل الوراثية والبيئية.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أنظر إلى الأسفل! ⬇️ لقد استقر رأسي تمامًا بين عظام الحوض. أنا في وضعية "الانطلاق". هذه الوضعية غير مريحة قليلًا بالنسبة إليّ، لكنها أفضل زاوية لدخول قناة الولادة. أنا مستعد للقائكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'اليقطين'), body_changes_ar = COALESCE(body_changes_ar, 'ترتفع مستويات هرموني البروجستيرون والإستروجين مع الحمل، وتزداد بشكل ملحوظ خلال أشهره الأخيرة. وقد يسبب ذلك احتقان الأنف.;;;
قد يصاحب احتقان الأنف جفاف الفم، والشعور بالحاجة إلى السعال، والصداع، والأرق. بالإضافة إلى ذلك، عندما يصبح التنفس عبر الأنف صعبًا، تقل قدرة الغشاء المخاطي للأنف على التقاط الكائنات الدقيقة الضارة واحتجازها، وقد يصبح جسمكِ أقل مقاومة للأمراض.;;;
عندما تبدأ انقباضات المخاض، يكون التنفس الصحيح مهمًا جدًا للمساعدة على تخفيفها. وقد يزيد الصداع والسعال والأرق صعوبة هذه المرحلة لأنها تعوق قدرتكِ على التنفس بشكل صحيح. لذلك سيكون من المفيد ممارسة تمارين التنفس بانتظام، والقيام بنزهات قصيرة في الهواء النقي، والاستلقاء على جانبكِ الأيسر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قلّلي تناول السوائل قبل النوم حتى تستيقظي مرات أقل للذهاب إلى المرحاض. واحرصي على أن تكون غرفة النوم مظلمة وباردة.') WHERE id = 'f767f4b5-3cd7-4998-b9f7-8ee66f29236d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اعتبارًا من هذا الأسبوع، أصبح الجهاز اللمفاوي لطفلكِ متطورًا بدرجة كبيرة. ويتكون جهازه اللمفاوي من الأوعية اللمفاوية والعقد اللمفاوية. وتشمل أعضاء الجهاز اللمفاوي: العقد اللمفاوية، واللوزتين، والعقيدات الموجودة داخل الأغشية المخاطية، والطحال. وتتمثل المهمة الأساسية للجهاز اللمفاوي في ضمان دوران السائل اللمفاوي في أنحاء الجسم. والسائل اللمفاوي سائل بالغ الأهمية يحتوي على أعداد كبيرة من خلايا الدم البيضاء، ويساعد الجسم على مكافحة العدوى في مختلف أجزائه.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بطيخة صغيرة! المكان ضيق جدًا هنا لدرجة أنني أستخدم مرفقيّ لأفسح لنفسي مجالًا للحركة. أعلم أنني أؤلمكِ أحيانًا، لكنني أيضًا عالق هنا في مساحة ضيقة!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة صغيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تكون شهيتكِ قد ازدادت بشكل ملحوظ في هذه المرحلة من الحمل. لذلك ينبغي الانتباه إلى الزيادة السريعة في الوزن خلال الفترة الأخيرة، ومحاولة الحفاظ على وزنكِ ضمن مستوى مناسب. وخلال هذه الفترة التي تعيشين فيها الأسابيع الأخيرة من الحمل، تُعد زيادة الوزن بمقدار 250-500 غرام أسبوعيًا أمرًا طبيعيًا. وإذا واصلتِ اتباع نظام غذائي متوازن ومنتظم، فيمكنكِ إكمال زيادة الوزن بصورة طبيعية. كما قد يسهم نمو طفلكِ وكونه أكبر من المتوسط في زيادة وزنكِ. وليست كل الزيادة المكتسبة خلال الحمل زيادة فعلية في وزن جسمكِ؛ إذ يعود نحو 3000-3500 غرام منها إلى وزن الطفل، و800 غرام إلى المشيمة، و700 غرام إلى السائل الأمنيوسي، و800 غرام إلى نمو الرحم، بينما تمثل الدهون والوذمة المتراكمة في جسمكِ نحو 5000 غرام.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بما أن الولادة قد تبدأ في أي لحظة خلال هذه الفترة، فاستخدمي طاقتكِ باعتدال. وإذا شعرتِ بآلام تمتد من ظهركِ نحو بطنكِ وتزداد قوة تدريجيًا، فابدئي بتسجيل توقيتها. واصلي شرب الكثير من الماء لتقليل تورم ساقيكِ، واستريحي مع رفعهما إلى أعلى. لا ترهقي نفسكِ كثيرًا اليوم، واكتفي بالأنشطة التي تمنحكِ الشعور بالسكينة.') WHERE id = '5ba8c0c5-91c9-4151-91cf-d3f16e08e88d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'وصلت الصفائح الدموية وخلايا الدم البيضاء في جهاز طفلكِ الدوري إلى العدد الأمثل. تؤدي الصفائح الدموية دورًا فعالًا في تخثر الدم. ويبلغ متوسط عمرها 10 أيام، وبعد إتمام مهامها تتحلل في الطحال أو الكبد ثم يتخلص منها الجسم. ونظرًا إلى دورها في تخثر الدم، يزداد عددها عند فقدان الدم لتكوين خثرة فعالة. أما خلايا الدم البيضاء في جهاز طفلكِ الدوري، فتؤدي دورًا فعالًا في الدفاع عن الجسم من خلال إنتاج الأجسام المضادة. ولأنها لا تمتلك خاصية الانقسام ولا تجدد نفسها، فإنها تُنتج في نخاع عظام طفلكِ وعقده اللمفاوية.;;;
في حالات العدوى، يزداد عددها بشكل ملحوظ، وعندما يتطور الجهاز المناعي لطفلكِ يصل عددها إلى أعلى مستوى قد يبلغه طوال حياته. وقد تعيش بضع ساعات أو بضعة أيام، وفقًا لاستجابة الجهاز المناعي للكائنات الدقيقة الضارة. وبعد إتمام مهامها، تتحلل في طحال طفلكِ وكبده.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أُصاب بالفُواق! 🤭 أصبح فُواقِي الآن أقوى. يمكنكِ الشعور باهتزاز بطنكِ كله. وهذا يدل على أن حجابي الحاجز لا يزال يتدرب. أنا أستعد للتنفس.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة صغيرة'), body_changes_ar = COALESCE(body_changes_ar, 'يُعد النوم الجيد طوال فترة حملكِ مهمًا للغاية لكِ ولطفلكِ. فالحصول على قسط كافٍ من النوم لا يساعدكِ على الشعور بمزيد من النشاط فحسب، بل يفيدكِ أيضًا خلال عملية الولادة.;;;
يُعد انخفاض سكر الدم ليلًا أحد العوامل المسببة للأرق. وقد تؤدي هذه الحالة إلى صداع شديد وتعرق الجسم. وقد يفيدكِ شرب الحليب الدافئ قبل النوم. كما تُعد حرقة المعدة، التي تحدث غالبًا ليلًا، سببًا آخر للأرق. ومن أهم أسبابها الاستلقاء بعد تناول الطعام مباشرة. لذلك، يجب أن تظلي في وضعية مستقيمة وألا تستلقي أو تنامي لمدة لا تقل عن 2 ساعة، خصوصًا بعد وجبة العشاء.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قيسي ضغط دمكِ صباحًا ومساءً. إذا كان أعلى من 140/90، فأخبري طبيبكِ. وامتنعي تمامًا عن الأطعمة المالحة لتقليل التورم.') WHERE id = 'c2434362-3321-422e-8c43-c14fba4ebb39';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتراوح محيط رأس طفلكِ في هذه المرحلة بين 32 sm و37 sm. ووقوع محيط رأس طفلكِ ضمن هذا النطاق يدل على نمو دماغه بصورة سليمة. ويُعد نمو محيط الرأس مهمًا للغاية لتطور دماغ طفلكِ. فقد يؤثر انخفاض النمو عن المعدلات الطبيعية أو ارتفاعه عن المتوسط سلبًا في نمو الدماغ. لذلك، يجب قياس محيط الرأس ومتابعته خلال الفحوصات الشهرية. ومن الضروري قياسه كل شهر خلال الأشهر الستة الأولى بالتزامن مع الفحوصات الروتينية. وبينما يتيح قياس وزن طفلكِ وطوله الحصول على معلومات عن صحته العامة، يُعد محيط الرأس بالغ الأهمية لأنه يساعد على تقييم وظائف الدماغ. ففي حالات اضطراب وظائف الدماغ، قد تكون قياسات محيط الرأس غير طبيعية.;;;
ينمو دماغ طفلكِ بسرعة كبيرة، إذ يزداد نموه بنسبة 88% خلال السنة الأولى بعد الولادة، كما تتزايد باستمرار الروابط الجديدة التي يشكلها بين خلايا الدماغ من خلال ما يتعلمه.'), baby_message_ar = COALESCE(baby_message_ar, 'يقول الأطباء إن الفترة بين الأسبوعين 38 و42 هي الوقت الطبيعي للولادة. وهذا يعني أنني قد آتي في أي لحظة. هل فكرتِ في الاسم الذي ستطلقينه عليّ يا ماما؟ ها أنا آتي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة صغيرة'), body_changes_ar = COALESCE(body_changes_ar, 'خلال فحصكِ الطبي هذا الأسبوع، سيُجرى لكِ فحص للحوض إذا لم توجد مشكلة تستدعي الولادة القيصرية. وفحص الحوض هو إجراء يهدف إلى تحديد مدى ملاءمة عظام حوضكِ للولادة الطبيعية.;;;
يُجرى هذا الفحص قبل بدء المخاض، بين الأسبوعين 36 و38، لتقييم إمكانية الولادة الطبيعية بصورة أوضح. أما إذا تقررت الولادة القيصرية، فلا حاجة إلى فحص الحوض. كذلك لا تكون هناك حاجة إلى تقييم ملاءمة الحوض في حالات انسداد قناة الولادة بالمشيمة، أو تسمم الحمل، أو الحمل المتعدد بتوأم أو ثلاثة توائم.;;;
يُجرى هذا الفحص أساسًا لتحديد طريقة الولادة، والتحقق مما إذا كان طفلكِ قد نزل إلى قناة الولادة وتحديد وضعيته، والكشف عن وجود عدوى في المهبل، وتقييم درجة اتساع عنق الرحم وليونته.;;;
إذا وجد طبيبكِ أن الحوض ضيق، فسيحدد موعدًا للولادة القيصرية وفقًا لدرجة ضيق الحوض ووزن طفلكِ. فقد يمنع ضيق الحوض طفلكِ من المرور عبر قناة الولادة، كما قد يؤدي إلى حدوث بعض المضاعفات أثناء الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عندما تبدأ الانقباضات، تذكري قاعدة "5-1-1": إذا كانت الانقباضات تأتي كل 5 دقائق، وتستمر كل واحدة منها لمدة 1 دقيقة، واستمر هذا النمط لمدة 1 ساعة، فتوجهي إلى المستشفى.') WHERE id = '4a0b4b38-f357-4956-99dd-b078f66f4393';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'الجهاز المناعي هو أهم درع يحمي صحة طفلكِ. ويُنشئ هذا الجهاز خط دفاع متكاملًا من ثلاث مراحل في مواجهة الكائنات الدقيقة الضارة:;;;
خط الدفاع الأول (مراقبة الحدود): يتكون من الحواجز المادية التي تمنع دخول الجراثيم إلى الجسم. وتشمل الجلد، والأغشية المخاطية في الأنف والفم، إلى جانب الإنزيمات الخاصة الموجودة في الدموع واللعاب.;;;
خط الدفاع الثاني (الاستجابة السريعة): إذا تمكنت الجراثيم من الدخول، يُنتج الجسم فورًا بروتينات مضادة للميكروبات، ويرفع درجة حرارته أو يسبب التهابًا في محاولة للقضاء على العدو.;;;
خط الدفاع الثالث (القوات الخاصة): في مواجهة الجراثيم التي تتجاوز خطي الدفاع الأولين، يُنتج الجسم "أسلحة" خاصة، وهي الخلايا اللمفاوية والأجسام المضادة. وفي هذه المرحلة، يتعرف الجهاز على العدو ويحارب ذلك النوع تحديدًا.;;;
في حين يستجيب خطا الدفاع الأول والثاني بالطريقة نفسها لجميع المواد الغريبة، يستجيب الخط الثالث لكل نوع من الأمراض باستراتيجية خاصة. وبفضل هذا الجهاز، يكون جسم طفلكِ مستعدًا لمواجهة مختلف أنواع المخاطر.'), baby_message_ar = COALESCE(baby_message_ar, 'أشعر بالضيق! 🏠 المكان هنا ضيق جدًا. أريد أن أتحرك، لكن لا توجد مساحة كافية. قد تظنين أن حركاتي قد قلت، لكن انتبهي: حتى إذا تغير نوعها (انزلاق بدلًا من الركلات)، فلا ينبغي أن يقل عددها. يجب أن أكون نشيطًا كل يوم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة صغيرة'), body_changes_ar = COALESCE(body_changes_ar, 'أنتِ الآن في الأيام الأخيرة من الثلث الأخير من الحمل. وقد تشعرين بوهن شديد نتيجة الإرهاق الذي سببته الأشهر الـ9 الصعبة الماضية.;;;
تتغير مستويات الهرمونات في جسمكِ بشكل كبير خلال الحمل. وينتج جسمكِ دمًا أكثر بنسبة 50% لتوفير الظروف المثلى لطفلكِ، كما تتسارع ضربات قلبكِ، وينخفض سكر الدم لديكِ، ويستهلك الأيض قدرًا أكبر من الطاقة. ولهذه الأسباب قد تشعرين بوهن شديد، خصوصًا في الفترة الأخيرة. بالإضافة إلى ذلك، قد تؤدي مخاوف الولادة الناتجة عن اقتراب موعدها إلى بعض التغيرات النفسية. وقد يؤدي عدم حصول جسمكِ على كمية كافية من السوائل إلى تفاقم الشعور بالوهن. لذلك، يجب أن تشربي ما لا يقل عن 2 لتر من الماء يوميًا، وأن تحرصي على عدم البقاء من دون سوائل لفترة طويلة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي عد حركات طفلكِ خلال اليوم. إذا لم تشعري بأي حركة، فتناولي شيئًا حلوًا واستلقي على جانبكِ الأيسر. وإذا لم يستجب طفلكِ، فتوجهي إلى الطبيب فورًا.') WHERE id = 'f9044cd4-84b9-4a00-86de-1671dcaabd83';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في بداية الحمل، كان وزن رحمكِ نحو 60 غرامًا وحجمه بحجم كرة تنس، أما في هذه المرحلة فقد بلغ وزنه 1500 غرام وأصبح بحجم كرة قدم. يتكوّن الرحم، وهو أقوى عضو في جسم المرأة، من أنسجة عضلية عديدة تمتد في اتجاهات مختلفة. ويتألف من السطح الخارجي إلى الداخلي من ثلاث طبقات: الطبقة المصلية، والطبقة العضلية، والطبقة الداخلية التي ينمو فيها طفلكِ. ترتخي الطبقة العضلية السميكة الموجودة في أنسجة الرحم وتتمدد، ما يزيد من سعته الداخلية ويتيح لطفلكِ النمو. ولدعم هذا النمو في الرحم، تتغير آلية عمل جسمكِ بالكامل، ويؤثر هذا التغيير في جميع أعضائكِ. في هذه المرحلة، يصل وزن عضلات رحمكِ القوية والرحم عمومًا إلى 1500 غرام، وتتسع سعته بدرجة تمكّنه من حمل أكثر من 5 كيلوغرامات داخله. واعتبارًا من هذا الأسبوع، يحمل جسمكِ في المتوسط أكثر من 7 كيلوغرامات، تشمل وزن الرحم نفسه البالغ 1500 غرام، ومتوسط وزن طفلكِ البالغ 3500 غرام، ووزن المشيمة البالغ 1000 غرام، ووزن السائل الأمنيوسي البالغ 1200 غرام.'), baby_message_ar = COALESCE(baby_message_ar, 'قلبي مرتبط بكِ! ❤️ لا تزال دورتي الدموية تُنظَّم عبر مشيمتكِ. وعندما أولد، سينتقل جهازي القلبي الوعائي إلى العمل بصورة مستقلة فور قطع الحبل السري. ستُغلَق بعض الفتحات الموجودة في قلبي، وسيتدفق الدم إلى رئتيّ. إنه انتقال مذهل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة صغيرة'), body_changes_ar = COALESCE(body_changes_ar, 'يتسبب الرحم المتضخم الذي يحمل طفلكِ، بتأثير الحمل، في تغيير مركز ثقل جسمكِ، ما يؤدي إلى الشعور بألم في المهبل وأسفل الظهر وأسفل البطن.;;;
بالإضافة إلى ذلك، قد يسبب بدء اتساع عنق الرحم قبل الولادة بأيام ألمًا في منطقة المهبل. وقد تكون هذه الآلام الناتجة عن الاتساع شديدة جدًا أحيانًا، وقد تشعرين بها على شكل تقلصات.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تدرّبي على تقنيات التنفس التي ستستخدمينها أثناء الولادة. يُعد التنفس بعمق من أفضل الطرق للسيطرة على آلام التقلصات.') WHERE id = '5df96ea7-65a1-4678-8453-5c3a6e6b2deb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'انخفض معدل نمو طفلكِ قليلًا بسبب ضيق المساحة المتاحة له. ويزداد وزن طفلكِ في هذه المرحلة بمعدل 15 غرامًا يوميًا. يكتمل خروج طفلكِ أثناء الولادة عبر مروره من عنق الرحم. لذلك، يساعد تقوية العضلات في هذه المنطقة على جعل ولادتكِ أكثر سهولة وتقليل خطر حدوث أي مضاعفات أثناءها. عضلات قاع الحوض هي مجموعة العضلات التي تحيط بالرحم والمهبل والمثانة والمستقيم، وهو الجزء الأخير من الأمعاء، وتدعم هذه الأعضاء بالكامل.;;;
من المهم جدًا أن تكون عضلات حوضكِ قوية خلال الحمل. فالرحم الذي ينمو ويتطور فيه طفلكِ يقع داخل مجموعة عضلات الحوض، كما يمر طفلكِ عبر هذه المنطقة عند مجيئه إلى العالم.;;;
أثناء الولادة، تدفع مجموعات عضلات الحوض طفلكِ إلى أسفل بقوة كبيرة من خلال الدفع والشد. ويتسبب كل تقلص للرحم في ضغط يبلغ في المتوسط نحو 25 كيلوغرامًا. ويوضح هذا الضغط مقدار القوة اللازمة لدفع طفلكِ إلى الخارج أثناء الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أسمع كل شيء! 👂 أصبحت أذناي الآن قادرتين على السمع جيدًا لدرجة أنني أسمع نبضات قلبكِ وأصوات معدتكِ والأحاديث في الخارج. عندما أولد، ستبدو لي أصوات المستشفى غريبة، لذلك سأهدأ إذا احتضنتِني وتحدثتِ إليّ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة صغيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تؤدي الهرمونات إلى تغير الفلورا المهبلية، ما يهيئ الظروف لتكاثر البكتيريا بصورة غير منضبطة. وقد تكون صعوبة الحفاظ على النظافة الشخصية بشكل كامل بسبب كبر حجم البطن عاملًا آخر في حدوث هذه الحالة. تتكاثر البكتيريا التي تدخل الجسم عبر المهبل وتسبب العدوى بسرعة كبيرة في المناطق التي يُعاق فيها تدفق البول ويتجمع فيها. ورغم أن علاج هذه العدوى سهل نسبيًا، يجب التعامل معها بجدية، لأن إهمالها قد يؤدي إلى حدوث بعض المشكلات أثناء الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اطلبي من شريككِ تدليك ظهركِ. ففرك منطقة أسفل الظهر بكرة تنس يمنحكِ راحة كبيرة أثناء التقلصات.') WHERE id = '7cd91bfd-2c65-4ec8-b473-970178378a3f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن الجزء غير النوعي من الجهاز المناعي قد تكوّن بالفعل، فإن الجزء النوعي من المناعة لم يكتمل نموه بعد، لأن طفلكِ لا يستطيع إنتاج الأجسام المضادة بنفسه.;;;
الجزء غير النوعي من الجهاز المناعي هو الجزء الذي يتصدى للمواد الضارة التي تدخل الجسم دون تمييز بينها. ويتكوّن من الحواجز التي تمنع دخول المواد المسببة للعدوى إلى الجسم، مثل الفم والأنف والعينين والجلد والإفرازات التي تنتجها هذه الأعضاء.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يحفّز فحص الحوض الذي تجريه طبيبتكِ أو طبيبكِ عنق الرحم، ومن ثم قد يؤدي إلى بدء الولادة. لذلك، يُفضّل إجراء هذا الفحص بعد الأسبوع 36.;;;
يمكن إجراء فحص الحوض بطريقتين مختلفتين: يدويًا أو باستخدام أداة تُسمى المنظار المهبلي. ويُقيَّم خلال هذا الفحص وضع عظام حوضكِ. ويهدف فحص الحوض إلى تقييم مدى التوافق بين رأس طفلكِ وقناة الولادة التي سيمر عبرها.;;;
أثناء فحص الحوض اليدوي، سيُطلب منكِ الجلوس على كرسي فحص أمراض النساء، ثم يفحص الطبيب بإصبعين مدى اتساع عنق الرحم ووضع عظام الحوض.;;;
أما أثناء الفحص باستخدام المنظار المهبلي، فتُدخَل هذه الأداة في المهبل لتوسيعه. وبعد وضع المنظار، يفحص الطبيب عنق الرحم ومدى ملاءمة الحوض لتحديد طريقة الولادة.;;;
إذا أظهرت نتيجة الفحص أن عرض عظام حوضكِ مناسب، فلن تكون هناك عوائق متعلقة بالحوض أمام الولادة الطبيعية. أما إذا اكتُشف ضيق في عظام الحوض، فسيحدد الطبيب معكِ طريقة الولادة وفقًا لدرجة الضيق.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي ألا تبقي وحدكِ في المنزل. فإذا بدأت الولادة، فمن المهم أن يكون إلى جانبكِ شخص يساعدكِ ويأخذكِ إلى المستشفى. حافظي على هدوئكِ، فلم يتبقَّ سوى القليل جدًا على اللقاء الكبير!') WHERE id = 'e4196ad3-1e48-4295-82c8-6c810ea2f084';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن جميع أنسجة طفلكِ وأعضائه وأجهزته قد اكتمل تطورها الوظيفي، فإن رئتيه تستمران في النضج حتى يوم ولادته. تتطور الرئتان منذ الأسبوع 24 من الحمل بما يكفي للعمل بمساعدة دعم التنفس. ومع ذلك، قد تظهر بعض صعوبات الشهيق والزفير حتى الأسبوع 38 من الحمل، إذ لا يكون إنتاج المادة الخافضة للتوتر السطحي (السرفاكتانت) قد اكتمل بعد. وبوجه عام، لا يكتمل نضج الجهاز التنفسي تمامًا إلا عند بلوغ طفلكِ عمر سنتين، لأن الرئتين تواصلان تطورهما حتى ذلك الحين.;;;
سيكون النفس الأول الذي يأخذه طفلكِ فور ولادته أصعب نفس يأخذه طوال حياته. فعند انقطاع حصوله على الأكسجين من المشيمة وملامسة جلده للأكسجين، يُفعّل الجهاز العصبي عملية التنفس. وقبل أن يصل الهواء الذي يستنشقه طفلكِ لأول مرة إلى الحويصلات الهوائية، يجب التخلص من السوائل الموجودة في رئتيه عبر المسالك التنفسية. ولهذا السبب، لا تمتلئ الحويصلات الهوائية في رئتيه بالهواء بالكامل عند النفس الأول. ومع النفس الثاني، تبدأ الرئتان في أداء وظيفتهما التنفسية. ومع الأنفاس التالية، تتمدد رئتا طفلكِ وتنتشر مادة السرفاكتانت على سطح الحويصلات الهوائية. وتُهيئ هذه المادة سطح الحويصلات للتنفس وتمنع التصاقها ببعضها. وهكذا تصل رئتا طفلكِ إلى قدرتهما الوظيفية الكاملة.'), baby_message_ar = COALESCE(baby_message_ar, 'شكرًا على صبركِ! 🙏 أعلم أنكِ متعبة جدًا، وأن جسمكِ يؤلمكِ ولا تستطيعين النوم. لكن هذه الأيام الأخيرة مهمة جدًا بالنسبة إليّ. يجري دماغي وجهازي العصبي آخر التعديلات. لقد منحتِني أكثر بيت آمن في العالم. والآن حان وقت الخروج.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, '🍉 أنا بحجم بطيخة كبيرة! يقول الأطباء إن الأسبوع 39 هو الوقت المثالي للولادة. دماغي ورئتاي وكبدي – كل شيء لديّ جاهز تمامًا. لم يعد لديّ أي عذر، أنا فقط أنتظر أن يُفتح الباب!'), daily_tip_ar = COALESCE(daily_tip_ar, 'تحلّي بالصبر. قد يكون الرد عن سؤال "متى ستلدين؟" مرهقًا. ضعي هاتفكِ على الوضع الصامت وركّزي فقط على نفسكِ وطفلكِ.') WHERE id = '37c59540-1af3-42e8-95c8-2c53b72f2a9f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع حلول هذا الأسبوع، أصبح طفلكِ يشغل كامل المساحة المتاحة داخل رحمكِ. ولذلك، من الطبيعي جدًا أن تشعري بانخفاض حركاته. ففي هذه المساحة الضيقة، يسحب طفلكِ ساقيه المتقاطعتين نحو جذعه ويضم ذراعيه إلى صدره ليحصل على أكبر مساحة ممكنة داخل الرحم. ولأنه لم يعد هناك متسع للحركة، فقد تؤلمكِ حتى أصغر حركة يقوم بها في هذه المرحلة. واستعدادًا للولادة، وضع طفلكِ رأسه في قناة الولادة. وإذا لم يكن هذا حملكِ الأول، فقد لا يكون قد ثبّت رأسه بعد في الوضعية اللازمة للولادة. ومع اتخاذ طفلكِ وضعية الولادة ودخوله قناة الولادة، قلّ ضغط الرحم على معدتكِ وحجابكِ الحاجز. ونتيجة لذلك، خفّت كثيرًا حرقة المعدة ومشكلات التنفس لديكِ. لكن بما أن الضغط على المثانة ازداد أكثر من أي وقت مضى، فقد تشعرين بالحاجة إلى الذهاب إلى المرحاض كثيرًا.'), baby_message_ar = COALESCE(baby_message_ar, 'خدّاي يمتلئان! 🐹 أصبح وجهي الآن أكثر امتلاءً واستدارة. عضلات المصّ لديّ قوية جدًا لدرجة أن وسائد دهنية تكوّنت في خدّيّ. سيساعدني ذلك على الرضاعة منكِ. عندما ترينني، سترغبين في قرص هذين الخدّين!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشهدين في المرحلة الأخيرة من حملكِ تقلبات مفاجئة في مشاعركِ بسبب التغيرات الهرمونية. كما قد تمرين بحالات اكتئابية نتيجة أسباب مثل الخوف من الولادة.;;;
عند التعرض لهذه المشكلات، تنتقل هرمونات الكورتيزول والأدرينالين التي يفرزها جسمكِ عبر الدم والمشيمة مباشرةً إلى طفلكِ. وقد يؤدي تعرضه لكميات مرتفعة من هذه الهرمونات إلى ظهور مشكلات في مراحل لاحقة من حياته، مثل تشتت الانتباه وضعف المهارات اللغوية وصعوبة التكيف مع المستجدات والاضطرابات الاكتئابية.;;;
إلى جانب ذلك، قد يؤدي التوتر خلال الحمل إلى مضاعفات جسدية إضافة إلى آثاره النفسية. فازدياد الأرق والتوتر وعدم نزول الحليب بعد الولادة يرتبط مباشرةً بهرموناتكِ.;;;
إذا كنتِ تشعرين بأنكِ تعانين من توتر مفرط، فقد تحتاجين إلى طلب المساعدة من مختص.'), daily_tip_ar = COALESCE(daily_tip_ar, 'الأرق الذي يحدث في هذه الأيام طبيعي، لذا استريحي خلال النهار كلما سنحت لكِ الفرصة. انتبهي إلى علامات مثل نزول "العلامة" (السدادة المخاطية) أو تسرّب ماء الجنين. اختاري أطعمة خفيفة وسهلة الهضم للحفاظ على طاقتكِ. وتأكدي للمرة الأخيرة من أن حقيبة المستشفى جاهزة بالكامل وموضوعة في مكان يسهل الوصول إليه. حافظي على هدوئكِ، فكل شيء يسير وفق الخطة!') WHERE id = '89f0050d-f633-47d8-92b8-7c424334510d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يُكمل طفلكِ الآن استعداداته الأخيرة للاستقبال الكبير. وفي هذه المرحلة، يتخذ وضعية الرأس إلى الأسفل ويبدأ بالضغط الكامل على قناة الحوض. وهذا الضغط ليس مجرد ثقل جسدي، بل هو محفز طبيعي مهم لبدء الولادة.;;;
يؤثر ضغط رأس طفلكِ نحو الأسفل ميكانيكيًا في عنق الرحم، ما يساعد على تليينه وانفتاحه تدريجيًا. كما تحفز هذه العملية إفراز هرمون الأوكسيتوسين في جسمكِ، مما يُهيئ انقباضات الرحم. وبما أن طفلكِ أصبح كبيرًا بما يكفي وضاقت المساحة داخل الرحم، أصبحت حركاته "البهلوانية" محدودة. لكن تذكّري أنه رغم تغير طبيعة الحركات، كأن تشعري بالاحتكاك أو التمدد بدلًا من الركلات القوية، يجب أن تستمري في الشعور بها بانتظام. فحركة طفلكِ هي أبسط مؤشر على سلامته وحصوله على كمية كافية من الأكسجين. إذا شعرتِ بانخفاض مفاجئ في حركاته أو بعدم حركته لفترة طويلة، فمن المهم استشارة طبيبكِ فورًا.'), baby_message_ar = COALESCE(baby_message_ar, 'قد ينزل مائي! 💧 عندما أتحرك أو أضغط برأسي، قد يتمزق الكيس الأمنيوسي. أحيانًا يندفع الماء مثل "دفقة"، وأحيانًا يتسرّب فقط "قطرة قطرة". إذا نزل ماؤكِ، فهذا يعني أنه لم يتبقَّ على لقائنا سوى ساعات! لا تخافي، فهذا غير مؤلم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'تُشعَر انقباضات الولادة في منطقتي أسفل الظهر والأربية، وتكون في بدايتها شبيهة بآلام الدورة الشهرية. وهي أكثر انتظامًا من الانقباضات الكاذبة المعروفة بانقباضات براكستون هيكس. ولا تقل شدتها عند الراحة، بل تتقدم تدريجيًا وتزداد قوتها وتواترها وتدوم لفترة أطول مع مرور الوقت.;;;
أما ما يُعرف عاميًا باسم "نزول البطن إلى الأسفل"، فهو مؤشر على استقرار طفلكِ في الحوض. وتشعر النساء، ولا سيما في الحمل الأول، بشيء من الراحة والخفة قبل الولادة ببضعة أسابيع. وعندما يستقر رأس طفلكِ في قناة الولادة، تتنفسين بسهولة أكبر وتشعرين بانخفاض الضغط على أضلاعكِ.;;;
إذا انفتح كيس الماء المحيط بطفلكِ (نزول ماء الجنين)، فعليكِ التواصل مع طبيبكِ دون انتظار بدء الانقباضات. ففي هذه الحالة، يصبح طفلكِ أكثر عرضة للعدوى، لذا يجب أن تبقي تحت المراقبة.;;;
يُعد نزول ماء الجنين علامة مؤكدة على بدء الولادة. ويكاد يكون من المستحيل عدم ملاحظة ذلك، إذ يكون على شكل تدفق غزير لا يمكن التحكم فيه، مستمر أو متقطع بفواصل قصيرة، وقد يبلل ساقيكِ. وعادةً ما تبدأ الانقباضات أيضًا خلال بضع ساعات.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بعد أن قطعتِ بنجاح هذه الرحلة الطويلة التي استمرت 39 أسبوعًا، وفّري لنفسكِ هذا المساء أجواءً هادئة. تذكّري علامات الولادة 3 الأساسية: الانقباضات المنتظمة والمتزايدة الشدة، ونزول ماء الجنين، أو نزول العلامة. إذا حدث أي منها، فتواصلي مع طبيبكِ. حافظي على طاقتكِ وثقي بأن كل شيء سيمر بأفضل حال.-') WHERE id = '46262d69-53e1-4e37-8004-ee9b3e95fbbb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'إن استقبال طفلكِ للمحفزات الخارجية عبر حواسه، وتفسيره لها بطريقته الخاصة، وحركاته الانعكاسية، ونظام نومه — باختصار، كل هذه العمليات المعقدة تنتج عن العمل الفعال لأجهزة جسمه. ويضمن نظام متطور للغاية للتحكم والتنظيم أن تعمل أجهزة جسم طفلكِ بانتظام وانسجام ومن دون مشكلات.;;;
ولا يكفي الجهاز العصبي وحده لتنظيم النشاط بين أنسجة طفلكِ وأعضائه، بل تتم هذه العملية بفضل العمل المشترك بين الجهاز العصبي والغدد الصماء. إذ تؤدي الغدد الصماء دورها التنظيمي من خلال إنتاج إفرازات خاصة تُسمى الهرمونات، استجابةً للإشارات الواردة من دماغ طفلكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت هرموناتي تعمل! 🧪 يفرز جسمي ومشيمتكِ هرمونات خاصة لتسريع عملية الولادة. قد تشعرين بأنكِ شديدة التأثر، وربما تميلين إلى البكاء. هذا هو تواصلنا الكيميائي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخ كبير'), body_changes_ar = COALESCE(body_changes_ar, 'كما قد تواجهين خلال حملكِ بعض المتاعب الناتجة عن عوامل بيئية، فقد تعانين أيضًا من أعراض مختلفة في جسمكِ مرتبطة بالتغيرات الهرمونية. ويُشخَّص تسمم الحمل، أو ما يُعرف بمقدمات الارتعاج، الذي يظهر في المراحل الأخيرة من الحمل، بارتفاع ضغط الدم ووجود البروتين في البول. ومع تقدم الحمل، تزداد كثيرًا كمية الدم والعناصر الغذائية التي تحتاج إليها المشيمة؛ لذلك تتوسع الأوعية الدموية المغذية لها. لكن عند حدوث تسمم الحمل، تضيق هذه الأوعية بسبب تغيرات في بنيتها، فلا تتمكن المشيمة من الحصول على ما تحتاج إليه من الدم والعناصر الغذائية. وعلى الرغم من أن احتمال حدوث هذه الحالة منخفض جدًا، فإنها تتطلب تدخّلًا عاجلًا إذا ظهرت، لأنها قد تهدد حياتكِ وحياة طفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حافظي على طاقتكِ. لا تتناولي وجبات ثقيلة، ولا تفرطي في ملء معدتكِ لأن الولادة قد تبدأ في أي لحظة وقد يحدث لديكِ منعكس القيء.') WHERE id = '938fd655-5567-4125-a9f7-ead570f3ba8c';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بعد اكتمال تكوّن جميع الغدد الصماء، أصبح جسم طفلكِ قادرًا على تصنيع مختلف الهرمونات بالنسب نفسها الموجودة لدى الإنسان البالغ. ومن بين هذه الهرمونات، يُعد هرمون النمو أهم هرمون يدعم نمو طفلكِ، ويُفرَز خصوصًا أثناء النوم.;;;
هرمون النمو هو بروتين تصنعه الفصّة الأمامية للغدة النخامية الموجودة في الدماغ، ويتكون من نحو 200 حمض أميني مختلف. ويؤدي هذا الهرمون دورًا في العديد من العمليات الفسيولوجية المعقدة، بما فيها نمو طفلكِ ومعدل الأيض لديه. وعلى خلاف الهرمونات الأخرى، لا يستهدف عضوًا محددًا، بل جميع خلايا الجسم. فهو يسرّع تصنيع البروتين داخل الخلايا خلال النمو، وينظم أيض الكربوهيدرات والدهون.;;;
يبدأ تصنيع هرمون النمو وإفرازه في ساعات المساء وينتهي مع شروق الشمس. ويبلغ إفرازه أعلى مستويات نشاطه بين الساعة 23:00 والساعة 05:00، ويصل خصوصًا قرابة الساعة 03:00 إلى أعلى مستوى ممكن له في الجسم. وتزداد كمية هذا الهرمون في الدم ليلًا، فيسرّع الانقسام المتساوي للخلايا ويساعد على نمو الأنسجة والأعضاء، ولا سيما العضلات الهيكلية والعظام والغضاريف.'), baby_message_ar = COALESCE(baby_message_ar, 'لقد تغير لوني! 🎨 لم أعد أحمر اللون. بفضل طبقة الدهون الموجودة تحت جلدي، أصبح لوني ورديًا أو فاتحًا. كما اختفت طبقة الطلاء الجبني تقريبًا. قد تكون بشرتي جافة قليلًا. لقد أصبحت إنسانًا مكتمل الاستعداد تمامًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخ كبير'), body_changes_ar = COALESCE(body_changes_ar, 'قد يحدث نزيف الأنف من حين إلى آخر لدى بعض الحوامل، بينما قد تتعرض أخريات لنوبات نزيف مشابهة كل يوم تقريبًا. وتُعد كلتا الحالتين شائعتين خلال الحمل، ولا تضرّان عادةً بكِ أو بطفلكِ. فلتلبية احتياجات طفلكِ المتزايدة والحفاظ على صحتكِ، ينتج جسمكِ كمية أكبر من الدم أثناء الحمل، وبذلك تزداد كمية الدم المتداولة في جهازكِ الدوري بدرجة ملحوظة. ومع زيادة حجم الدم، يزداد الضغط الواقع على الأوعية الدموية الرقيقة والسطحية داخل الغشاء المخاطي للأنف. وقد يؤدي هذا الضغط المرتفع إلى تمزق جدران تلك الأوعية وحدوث النزيف. عندما يبدأ أنفكِ بالنزف، اضغطي عليه وانتظري نحو 10 دقائق.'), daily_tip_ar = COALESCE(daily_tip_ar, 'استمتعي بجلسة تدليك أو حمام دافئ للقدمين. دعم شريككِ مهم جدًا؛ راجعي معه خطة الولادة مرة أخرى.') WHERE id = '4e4de332-7546-4ae2-8266-e548c84af11c';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'إن استجابة طفلكِ لصوتكِ عندما تتحدثين دليل على امتلاكه أعضاء حسية متطورة جدًا وجهازًا عصبيًا يمكّنه من تفسير هذه المحفزات والاستجابة لها. والمادة التي تثير حماس طفلكِ أثناء حديثكِ هي هرمون الأدرينالين. ويُعرف الأدرينالين أيضًا باسم الإبينفرين، وهو هرمون وناقل عصبي بالغ الأهمية يعمل في دماغ طفلكِ وجسمه. ويُفرَز الأدرينالين في الجسم من الغدد الكظرية، وفي الدماغ من بعض الخلايا العصبية المتخصصة الموجودة حول جذع الدماغ.;;;
ويساعد ارتفاع سكر الدم على تزويد خلايا جسم طفلكِ بمزيد من الطاقة، بينما يهدف تسارع ضربات القلب إلى تلبية حاجة الجسم المتزايدة إلى الأكسجين.;;;
ونتيجةً لكل هذه الاستعدادات، يهيئ الأدرينالين البيئة اللازمة لانقباض عضلات طفلكِ واستهلاكها للطاقة، وبذلك يستجيب لصوتكِ بالحركة.'), baby_message_ar = COALESCE(baby_message_ar, 'هل غدًا هو اليوم المنتظر؟ 📅 غدًا هو "موعد ولادتي المتوقع" رسميًا، لكن قد آتي اليوم أيضًا. أسمع صوتكِ وأنتِ تقولين: "تعالَ الآن". وأنا أيضًا أريد أن آتي إليكِ يا ماما. الطريق طويل، لكن نهايته مضيئة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخ كبير'), body_changes_ar = COALESCE(body_changes_ar, 'يُعد الأرق من أكثر المشكلات شيوعًا، ولا سيما مع اقتراب المراحل الأخيرة من الحمل. وقد تزداد مشكلة الأرق إذا كان جسمكِ يعاني نقصًا في المغنيسيوم. وللحفاظ على المستويات المناسبة من هرمونات الجهاز العصبي، أي النواقل العصبية التي تساعد على تحسين جودة النوم، يجب أن يحتوي الجسم على كمية كافية من معدن المغنيسيوم. ومن أغنى الخضراوات بالمغنيسيوم السبانخ والفاصولياء الخضراء والبروكلي والملفوف.;;;
كما تحتوي بذور اليقطين وبذور دوار الشمس والفول السوداني واللوز والكاجو والموز والأفوكادو ومنتجات الحبوب والحليب والزبادي على كميات وفيرة من المغنيسيوم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اجعلي هذا اليوم يوم "الهدوء الأخير". لا تستهلكي طاقتكِ مطلقًا في التنظيف أو الأعمال المرهقة. قد تبدأ الولادة في أي لحظة؛ لذلك لا تتناولي أطعمة ثقيلة، وفضّلي الوجبات الخفيفة التي تمنحكِ الطاقة. إذا نزل ماء الجنين، حتى إن لم تشعري بانقباضات، أو إذا تكررت الانقباضات بانتظام كل 5-7 دقائق، فقد حان وقت التوجه إلى المستشفى. ثقي بنفسكِ، فأنتِ مستعدة لهذا!') WHERE id = '7abac408-c74e-44ce-86ac-a1a2470ea25a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ الآن في هيئة "بطل صغير" مستعد تمامًا للولادة. وقد اكتمل تصلّب معظم عظامه وتقوّت، باستثناء عظام الجمجمة.;;;
أما بقاء عظام الجمجمة لينة وقابلة للحركة حتى الآن فهو إحدى معجزات الطبيعة؛ إذ تتيح هذه المرونة لطفلكِ المرور عبر قناة الولادة بسهولة وأمان أكبر. وقد طالت أظافر طفلكِ حتى تجاوزت أطراف أصابعه، بل إن بعض الأطفال يولدون بشعر طويل وكثيف نسبيًا.;;;
والأهم من ذلك أن "الساعة" الداخلية لطفلكِ، أي نظامه الهرموني، أصبحت مستعدة تمامًا لإرسال "إشارة الولادة". يفرز دماغ طفلكِ وغدته الكظرية هرمونات خاصة تُخبر جسمكِ بأن وقت بدء الولادة قد حان. ويحفّز هذا الحوار الهرموني عضلات الرحم، ليبدأ اللقاء الكبير بينكِ وبين طفلكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا جاهز رسميًا. هذا الأسبوع هو موعد ولادتي. ربما اليوم، وربما غدًا... لكنني أعدكِ بألّا أجعلكِ تنتظرين طويلًا. أنا أيضًا أريد رؤيتكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'تدعم التغذية السليمة خلال فترة الحمل التطور الذهني لطفلكِ، وتساعده على بلوغ إمكاناته المتوقعة للنمو. وخلال الحمل، ينبغي لكِ تناول كميات مناسبة وبانتظام من مختلف أنواع الأغذية، مثل الفيتامينات الموجودة في الخضراوات والفواكه، والبروتينات الموجودة في الأغذية الحيوانية، والدهون الصحية، والحليب ومنتجات الألبان، والحبوب.;;;
من المهم تناول الأغذية الغنية بالبروتين من أجل صحتكِ وصحة طفلكِ. كما ينبغي لكِ إدراج الخضراوات والفواكه الغنية بالكربوهيدرات في نظامكِ الغذائي، إضافة إلى البيض واللحوم والخضراوات الورقية الخضراء الداكنة لتلبية احتياجاتكِ من الحديد. وإلى جانب ذلك، يساعد تناول الأغذية التي تحتوي على فيتامينات A وC وD وشرب الكثير من الماء على قضاء فترة حمل صحية ومتوازنة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مارسي تمارين التنفس للتحكم في التوتر الذي قد تشعرين به خلال هذه الأيام. وللمساعدة على تحفيز بدء الولادة، امشي بخفة داخل المنزل ما لم ينصحكِ طبيبكِ بخلاف ذلك. تذكّري أن 5% فقط من الأطفال يولدون في الموعد المحدد تمامًا، لذلك لا تقلقي إذا تأخرت الولادة بضعة أيام. وتأكدي من أن هاتفكِ وحقيبتكِ جاهزان في كل لحظة.') WHERE id = 'c09d4d91-1d82-48b0-8145-2433217890b4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تظل أمعاء طفلكِ معقمة تمامًا حتى لحظة ولادته. وفي هذه المرحلة، تستعد الفلورا المعوية لاحتضان أكثر من 500 نوع مختلف من البكتيريا. ويُطلق اسم الميكروفلورا على هذه المنظومة الموجودة في الأمعاء الدقيقة والغليظة لطفلكِ، ويوجد فيها نحو %70 من خلايا الجهاز المناعي.;;;
بعد أن تظل الأمعاء معقمة حتى لحظة الولادة، يبدأ تكوّن الفلورا فيها وفقًا لطريقة ولادة طفلكِ وخصائصه الوراثية ومدى احتكاكه بالبيئة وطريقة تغذيته. وبعد ولادته، تبدأ بعض البكتيريا المرتبطة بالتغذية والمساعدة على الهضم بالظهور في الأمعاء في اليوم 4 إذا كانت الولادة طبيعية، وفي اليوم 7 إذا كانت الولادة قيصرية.;;;
بعض الكائنات الموجودة في الفلورا المعوية بكتيريا نافعة، وبعضها الآخر بكتيريا ضارة. وهذا ضروري للحفاظ على توازن الفلورا المعوية. إذ يحقق كلا النوعين من البكتيريا توازنًا في الجهاز الهضمي، ويمنع كل منهما الآخر من التكاثر المفرط أو الانخفاض الشديد في العدد. وبينما قد تؤدي زيادة البكتيريا في الفلورا عن الحد الطبيعي إلى الإسهال وفقدان السوائل بصورة مفرطة، فإن انخفاضها قد يهيئ للإصابة بالإمساك.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا قادم مع التقلصات! ⚡ إذا كان بطنكِ يتصلب ثم يرتخي بانتظام، وكان هذا الإحساس يزداد قوة تدريجيًا، فهذا يعني أنني أطرق الباب. تدفعني التقلصات إلى الأسفل نحو المخرج. يصلني قدر أقل قليلًا من الأكسجين مع كل تقلص، لكنني قادر على التحمّل. خذي نفسًا عميقًا لتساعديني.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يرهقكِ التوتر الناتج عن تأخر الولادة. فالجميع يسألكِ: "أما زلتِ لم تلدي؟"، وهذا يسبب ضغطًا نفسيًا. أما جسديًا، فقد بلغ الضغط على عظام الحوض أقصى مستوياته. ويستمر الأرق والانزعاج. جسمكِ مستعد تمامًا للولادة، وقد ارتخت أربطة الحوض إلى أقصى درجة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا أصبحت تقلصات براكستون هيكس منتظمة، فاحرصي على الاستلقاء والراحة واشربي الكثير من الماء. وإذا لم تختفِ التقلصات حتى بعد استلقائكِ، وكانت تتكرر كل 10 دقائق، فقد يكون ذلك بداية الولادة. لا ترهقي نفسكِ كثيرًا اليوم، واستمعي إلى موسيقى هادئة، واستمتعي مع طفلكِ بهذه اللحظات الأخيرة من اتحادكما داخل رحمكِ.') WHERE id = '7bc0ef79-b157-4b4f-94b8-a06d51f2d8d7';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تتوازى سرعة نمو دماغ طفلكِ مع نمو رأسه. ويبلغ محيط الرأس عند الولادة في المتوسط 33-35 sm، ثم ينمو بسرعة خلال الأشهر الستة الأولى. وبعد ذلك يستمر نموه ولكن بوتيرة أبطأ. ويُقيّم نمو دماغ طفلكِ بعد الولادة، أي نمو رأسه، استنادًا إلى منحنيات النمو المعيارية المحددة حسب العمر:;;;
صِغَر الرأس: إذا كان محيط رأس الطفل أقل من %3 من نطاق القيم المتوقعة لعمره، فتُسمى هذه الحالة صِغَر الرأس. وعندئذ تُبحث العوامل التي قد تعيق نمو الدماغ، مثل العوامل الوراثية أو العدوى الشديدة التي حدثت أثناء الحمل.;;;
ضخامة الرأس: عندما يزيد محيط الرأس على %90 من القيم الطبيعية، يُشخّص الطفل بضخامة الرأس. وفي هذه الحالة، تُبحث الأسباب التي تؤدي إلى نمو غير طبيعي للدماغ والبُنى الداعمة له وتُعرّضه للضغط.;;;
ينمو دماغ طفلكِ بسرعة كبيرة؛ إذ يزداد حجم الدماغ بنحو %88 خلال السنة الأولى بعد الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'أما زلت هنا؟ 🏠 إذا لم أكن قد وُلدت بعد، فلا تحزني. قد يكون هناك خطأ في حساب الموعد أحيانًا، أو ربما أحتاج فقط إلى بضعة أيام إضافية. كل يوم أقضيه في رحمكِ يعود عليّ بالفائدة (إذا كانت المشيمة تعمل جيدًا). أنا أعرف موعدي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا صادف حملكِ أشهر الصيف خصوصًا، فسيكون من المفيد جدًا تناول فواكه الصيف الموسمية. فهذه الفواكه غنية بالفيتامينات والمعادن، ولها خصائص مضادة للأكسدة وقيمة غذائية مرتفعة.;;;
إذا تناولتِ الفواكه الغنية بالألياف مثل الفراولة، فستشعرين بالشبع مدة طويلة، ويمكنكِ التحكم في وزنكِ بسهولة أكبر طوال فترة الحمل.;;;
يساعد حمض الفوليك الموجود في الفراولة على نمو الجهاز العصبي لطفلكِ، بينما يساهم المغنيسيوم الموجود فيها في نمو عظامه وسلامة عملية تكوّنها.;;;
أما الأفوكادو فهو من أكثر الفواكه احتواءً على الأحماض الدهنية غير المشبعة. وإلى جانب الدهون الصحية، يحتوي أيضًا على مستويات مرتفعة من الفولات والبوتاسيوم. ويساعد البوتاسيوم على تخفيف تشنجات ساقيكِ في المراحل الأخيرة من الحمل.;;;
تحتوي هذه الفواكه على الكربوهيدرات الصحية وفيتامين C والألياف. وهي غنية خصوصًا بفيتامين C الضروري لامتصاص الحديد في جسمكِ. كما أن فيتامين C مهم أيضًا لصحة بشرتكِ ووظائف جهازكِ المناعي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنتِ تشعرين بثقل شديد، فخذي حمامًا فاترًا مع إسناد ظهركِ؛ إذ يساعد ذلك على إرخاء العضلات وتقليل تقلصات براكستون هيكس. ومن المهم أن تستمري في الشعور بحركات طفلكِ؛ فإذا لاحظتِ انخفاضًا مفاجئًا في حركته، فأبلغي طبيبكِ فورًا. قد يصبح النوم صعبًا خلال هذه الأيام الأخيرة، لذا استلقي على جانبكِ الأيسر وضعي وسادة بين ساقيكِ.') WHERE id = 'fd795c4a-8409-4cb2-89fc-4a9fbcef21a6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لا تتكوّن الفلورا المعوية، التي تساعد على امتصاص الأغذية التي يتناولها طفلكِ في الأمعاء وتُنتج بعض البكتيريا الضرورية لجسمه، إلا بعد الولادة نتيجة تناوله حليب الأم وتفاعله مع البيئة المحيطة. في هذه المرحلة، لا يبتلع طفلكِ سوى السائل الأمنيوسي داخل الرحم، ويُكمل المرحلة الأولى من تطور جهازه الهضمي مع أول رضعة بعد ولادته. ولا يكتمل نمو جهازه الهضمي، الذي يكون داخل الرحم في بيئة معقمة تمامًا، إلا بعد الولادة. يتغير حجم معدة طفلكِ بسرعة منذ لحظة ولادته:;;;
خلال أول 24 ساعة: بحجم حبة كرز (نحو 5-7 ml).;;;
في اليوم 3: بحجم حبة جوز (نحو 22-27 ml).;;;
في نهاية 30 يومًا: يصل إلى حجم بيضة متوسطة (نحو 60-150 ml).;;;
يبدأ جهاز طفلكِ الهضمي بالتشابه مع جهاز الشخص البالغ اعتبارًا من الشهر 6، خلال مرحلة إدخال الأغذية التكميلية، ويصل منذ عمر عامين تقريبًا إلى درجة نضج مماثلة للجهاز الهضمي لدى البالغين.'), baby_message_ar = COALESCE(baby_message_ar, 'ازداد وزني قليلًا! ⚖️ ماما، ما زلت أكتسب الوزن. هذه الأيام الإضافية تجعل وجنتيّ ألطف وذراعيّ أكثر امتلاءً وثنيات. وسيصبح احتضاني أمتع عندما أخرج إلى العالم. اجمعي طاقتكِ، فسأحتاج إليكِ كثيرًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'من المهم طوال فترة حملكِ أن تحصلي بانتظام على كل الفيتامينات والمعادن من خلال الأغذية التي تتناولينها. ومن هذه الفيتامينات فيتامين K، الذي يُعد بالغ الأهمية لوظائف جسمكِ وصحة طفلكِ على حد سواء. فهو يدعم تراكم الكالسيوم في بنية عظام الجهاز الهيكلي، وبذلك يساهم في الحفاظ على صحة العظام. كما يمنع تراكم الكالسيوم في الأوعية الدموية والكليتين. وباختصار، يساعد على موازنة كمية الكالسيوم في الجسم. ومن وظائفه الأخرى تنشيط البروتينات التي تؤدي دورًا فعالًا في الحفاظ على صحة القلب. أما الكمية الزائدة من فيتامين K في الجسم فتُخزّن في الكبد. وفيتامين K من الفيتامينات القابلة للذوبان في الدهون. تحتاجين خلال الحمل إلى ما لا يقل عن 90 mcg من فيتامين K يوميًا. لذلك، ينبغي أن تتناولي الخضراوات الورقية الخضراء والبيض واللحوم ومنتجات الألبان.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تبدأ الولادة في أي لحظة، لذا كوني لطيفة جدًا مع نفسكِ اليوم. وللابتعاد عن التوتر، شاهدي فيلمًا تحبينه أو خذي نفسًا عميقًا وأنتِ تتأملين الطبيعة من النافذة.') WHERE id = 'ab9a202d-7f8e-48d6-9bd2-ce62eab926ef';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح كبد طفلكِ مستعدًا تمامًا للولادة؛ فهو ينظم أيض الكربوهيدرات ويحوّل الغلوكوز الموجود في الدم إلى غليكوجين بمساعدة الإنسولين ثم يخزّنه. ويساعد هذا الاستعداد الذي يقوم به الكبد على منع انخفاض سكر دم طفلكِ وحرمان خلاياه من الغذاء خلال الولادة وحتى بدء إرضاعه. تُنتج قنوات الحليب لديكِ في اليوم الأول بعد ولادة طفلكِ كمية من الحليب تتناسب مع سعة معدته التي تكون بحجم حبة كرز. وبفضل الغليكوجين المخزّن في الكبد، لا يشكل انخفاض كمية حليبكِ في الأيام الأولى خطرًا على طفلكِ. ومع اقتراب الولادة، تصبح كمية السائل الأمنيوسي التي يبتلعها طفلكِ أكبر من كمية السوائل التي يطرحها في البول. وتتجمع هذه السوائل الزائدة التي يحتفظ بها جسمه بين الأنسجة، ثم تستخدمها الخلايا بعد الولادة.;;;
وبما أن هذه السوائل الزائدة التي يحتفظ بها جسم طفلكِ تُستخدم بعد الولادة ثم تُطرح في البول، فقد ينخفض وزن الولادة بنسبة تصل إلى 10% خلال الأيام الأولى. ويُعد فقدان الوزن هذا طبيعيًا. وفي غضون 7-10 أيام في المتوسط، يخزّن طفلكِ الدهون بدلًا من الماء الذي طرحه جسمه، ويستعيد وزن ولادته.'), baby_message_ar = COALESCE(baby_message_ar, 'هل حان وقت العناية بأظافري؟ 💅 تعلمين أن أظافري قد طالت كثيرًا، حتى إنني أخدش نفسي أحيانًا عندما ألمسها. وربما يكون قص أظافري أول ما سنفعله فور ولادتي. كما يستمر شعري في النمو أيضًا (إن كان لديّ شعر). سأصل إليكِ بكامل زينتي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'عليكِ أن تتذكري أن ولادتكِ قد تبدأ في أي لحظة، وأن تكوني مستعدة لها دائمًا. عندما يحين موعد الولادة، تبدأ التقلصات بشدة خفيفة. ورغم أنها تكون متباعدة في البداية، فإن الآلام التي تشعرين بها على فترات منتظمة تصبح تدريجيًا أكثر تقاربًا وأطول مدة وأشد قوة. تختلف مدة كل حمل عن غيرها، ولذلك عليكِ أن تتذكري أن كل عملية ولادة تختلف أيضًا، لكن هذه الآلام تُشبَّه عمومًا بتقلصات الدورة الشهرية الشديدة. إذا بدأت هذه التقلصات بالحدوث كل 10-15 دقيقة، فقد يكون ذلك مؤشرًا على اقتراب ولادتكِ. ومع ذلك، بما أن طبيبكِ هو الأقدر على إجراء التقييم الصحيح، فلا تنتظري طويلًا وتوجهي إلى المستشفى.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أصغي إلى جسدكِ. إذا شعرتِ بأي قلق، فاستلقي فورًا وتحدثي إلى طفلكِ. هدوؤكِ هو أكبر دعم له في طريقه إلى القدوم إلى العالم.') WHERE id = '2c4fb6e2-626f-4582-b7ad-da6ef85b1258';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'من أكثر الحالات شيوعًا التي قد تواجهينها عند ولادة طفلكِ يرقان حديثي الولادة. وقد تظهر هذه الحالة لدى نحو %60% من الأطفال المولودين في موعدهم، ولدى %80% من الأطفال المولودين قبل الأوان (الخُدّج). ورغم أن هذه الحالة ترتبط غالبًا في الاعتقاد الشائع بعدم حصول الطفل على تغذية كافية، فإن هذه معلومة خاطئة. فهي في الواقع عملية فسيولوجية تمامًا واستجابة من الجسم للتكيف مع البيئة الخارجية.;;;
طوال فترة الحمل، يحصل طفلكِ على الأكسجين الذي يحتاج إليه من دمكِ عبر المشيمة. إلا أن مستوى الأكسجين داخل الرحم أقل بكثير مقارنة بمستواه في العالم الخارجي. ولذلك يجعل جسم طفلكِ نخاع العظم يعمل بكثافة أكبر لتوزيع هذه الكمية القليلة من الأكسجين على جميع الخلايا والحفاظ على التوازن. وينتج الجسم عددًا كبيرًا من خلايا الدم الحمراء نتيجة هذا النشاط المكثف لنخاع العظم. وتصل هذه الخلايا بسهولة إلى كل خلية في جسم طفلكِ، فتمنع نقص الأكسجين.;;;
أما بعد الولادة مباشرة، فينتقل طفلكِ إلى بيئة غنية بالأكسجين، فلا يعود جسمه بحاجة إلى هذا العدد الكبير من خلايا الدم الحمراء، ويبدأ الكبد بتفكيك الخلايا الزائدة. وتؤدي مادة البيليروبين الناتجة عن هذا التفكك إلى ظهور اليرقان الفسيولوجي على جلد طفلكِ وفي عينيه.'), baby_message_ar = COALESCE(baby_message_ar, 'أصبحت مساحتي ضيقة جدًا! 🏠 ماما، صار المكان هنا أصغر حتى من "شقة استوديو". أصبحت الحركة صعبة جدًا، ولذلك قد تقل حركاتي. لكن ينبغي أن تشعري بي كل يوم. إذا ظننتِ أنني هادئ، فتناولي شيئًا حلوًا وسأجيبكِ فورًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تزداد بعض المشكلات الفسيولوجية لديكِ بشكل ملحوظ في هذه المرحلة بسبب نمو طفلكِ بما يكفي. وقد تشتد حرقة المعدة خصوصًا نتيجة الضغط الواقع عليها. تنتج حرقة المعدة أثناء الحمل عن تغير هرموناتكِ والضغط الواقع على المعدة مع نمو الرحم.;;;
يُعد الحليب الدافئ من الأطعمة التي قد تساعد على تخفيف حرقة المعدة خلال الحمل. فكوب من الحليب الدافئ قبل النوم يهدئ معدتكِ ويخفف الإحساس بالحرقة الناجم عن الحمض.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ضعي جميع الأعمال جانبًا اليوم واسترخي كما لو كنتِ في عطلة. تذكري أنكِ تصنعين معجزة، وأن جسدكِ يستعد لأداء أصعب عمل في العالم وأجمله في الوقت نفسه.') WHERE id = 'd01cbe86-cb64-4e22-98cc-8f8bd1c8a6d5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع إتمامكِ الأسبوع 40 من الحمل، يكون طفلكِ قد بلغ وزنه وطوله النهائيين عند الولادة. يتكوّن نحو %20 من إجمالي وزن جسم طفلكِ من الخلايا الدهنية البيضاء والبنية، ما يمنح بشرته لونًا ورديًا وملمسًا ناعمًا. وبما أن أجهزة جسمه قد اكتمل نموها، واكتمل أيضًا إنتاج المادة الخافضة للتوتر السطحي في رئتيه، فقد أصبح طفلكِ مستعدًا تمامًا للحياة خارج الرحم.;;;
إذا أتممتِ الأسبوع 40 ولم تحدث الولادة بعد واستمر حملكِ، فعليكِ مراقبة علامات الولادة بعناية أكبر:;;;
الإفرازات المهبلية: نتيجة ضغط الرحم الذي ازداد حجمه كثيرًا، قد تصبح إفرازاتكِ أكثر سيولة. وقد تظهر أيضًا بلون بني أو أصفر.;;;
تحذير من العدوى: تُعد الرائحة الكريهة المصاحبة لهذه الإفرازات المتسربة علامة على وجود عدوى.;;;
اختبار السائل الأمنيوسي: إذا لم تتمكني من التمييز بين الإفرازات العادية والسائل الأمنيوسي المحيط بطفلكِ، فيمكن التأكد من ذلك في المؤسسات الصحية من خلال اختبارات بسيطة تقيس درجة الحموضة pH، مثل اختبار النيترازين.'), baby_message_ar = COALESCE(baby_message_ar, 'تهانينا يا ماما! لقد أكملنا ماراثونًا دام 40 أسبوعًا. اليوم هو يوم ميلادي الرسمي! 🎂 إذا كنتُ قد وصلتُ اليوم إلى ذراعيكِ، فمرحبًا أيها العالم! وإذا لم أصل بعد، فلا تقلقي، فأنا لم أتأخر، بل أجعلكِ تنتظرين تماشيًا مع "الموضة". سنلتقي بالتأكيد خلال 1-2 أسبوع على الأكثر. أحبكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'اعتبارًا من اليوم، أتممتِ 40 أسبوعًا من الحمل. إذا حان موعدكِ ولم تحدث الولادة بعد، فلا داعي للقلق. لقد انتظرتِ طوال أشهر، وربما ترغبين في لقاء طفلكِ في أقرب وقت ممكن. وقد تدور في ذهنكِ بعض الأسئلة حول سبب تأخر الولادة. قد يرجع عدم حدوث الولادة في نهاية الأسبوع 40 إلى خطأ في حساب تاريخ آخر دورة شهرية أو إلى حدوث الإخصاب في وقت متأخر. وقد تتأخر ولادتكِ أيضًا من دون سبب، حتى إذا كان موعدكِ محسوبًا بدقة. لا داعي للذعر، وتذكّري أنه لا يزال أمامكِ أسبوعان. لكن عليكِ خلال هذه الفترة الانتباه أكثر إلى بعض المضاعفات المحتملة، وزيادة وتيرة زياراتكِ الطبية، وإجراء بعض الفحوصات. ومع اكتمال مدة الحمل، سيواصل طفلكِ اكتساب الوزن بالمعدل نفسه، ما قد يجعل عملية الولادة الطبيعية أكثر صعوبة. ووفقًا لبيانات منظمة الصحة العالمية، لا يشكّل وزن الطفل البالغ 4500 غرام أي عائق أمام الولادة الطبيعية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'رغم أن هذا اليوم هو اليوم الأخير وفقًا للتقويم، حافظي على هدوئكِ وراحة بالكِ. إذا لم تبدأ الانقباضات، فاذهبي في نزهة خفيفة أو خذي حمامًا دافئًا. تحققي للمرة الأخيرة من حقيبة الولادة والوثائق الموضوعة قرب الباب. إذا أصبحت الانقباضات تأتي كل 5 دقائق أو نزل ماء الرحم، فتوجهي فورًا إلى المستشفى. تذكّري: لقد أنجزتِ عملًا مذهلًا، وأنتِ الآن على وشك نيل أعظم مكافأة!') WHERE id = '08e8895d-cc10-4825-8aac-fb6a2a6d3d95';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يظل الجهاز العصبي لطفلكِ ونمو دماغه نشطين للغاية حتى وهو داخل رحمكِ، إذ ينموان باستمرار وبسرعة استثنائية. ولا سيما في الثلث الأخير من الحمل، حين تبدأ عملية التعلّم جزئيًا، تؤثر كل مشاعركِ مباشرةً في طفلكِ عن طريق الهرمونات:;;;
تأثير الكورتيزول: عندما تشعرين بقلق أو توتر أو خوف مفرط، يرتفع مستوى الكورتيزول في جسمكِ. ويؤثر هذا الهرمون في الجهاز العصبي لطفلكِ بالكامل.;;;
التفاعل الكيميائي: ينتقل الكورتيزول المُفرز بسبب هذه المشاعر الشديدة إلى جسم طفلكِ، ما يؤدي إلى إفراز بعض المواد الكيميائية التي تؤثر في وظائف دماغه.;;;
في هذه الفترة التي تعيشين فيها الأيام الأخيرة من حملكِ، من المهم للغاية لصحة الجهاز العصبي لطفلكِ أن تحافظي قدر الإمكان على توازن مشاعركِ.'), baby_message_ar = COALESCE(baby_message_ar, 'ما زلتُ هنا! 👋 مرحبًا يا ماما! لقد مضى التاريخ المحدد في التقويم، لكنني ما زلتُ في رحمكِ الدافئ. لا تقلقي، فوفقًا للإحصاءات لا يولد في موعدهم المحدد تمامًا سوى 5% من الأطفال. أشعر براحة شديدة فحسب، لذلك لا أتعجل الخروج. لدينا توقيتنا الخاص.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي للحوامل اللواتي لم تحدث ولادتهن بعد مرور 40 أسبوعًا أن يكنّ أكثر انتباهًا في بعض الحالات. ومن أهم الأمور معدل حركة طفلكِ. قد يثير تباطؤ حركاته قلقكِ أحيانًا، وقد يرجع ذلك إلى عدم وجود مساحة كافية له للحركة داخل الرحم بسبب وزنه. ومع ذلك، إذا شعرتِ بانخفاض ملحوظ في حركات طفلكِ، فعليكِ استشارة طبيبكِ. ولأن موعد الولادة أصبح قريبًا جدًا، ربما صارت انقباضات براكستون هيكس، المعروفة بالانقباضات الكاذبة، مؤلمة. تساعدكِ مراقبة الانقباضات الكاذبة والتحقق من مدى تكرارها على عدم الخلط بينها وبين انقباضات الولادة الحقيقية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بهذا اليوم! اشتري لنفسكِ كعكة، والتقطي صورة سيلفي بعنوان "لم ألد بعد". لن تعود هذه الأيام مرة أخرى. أعظم مغامرة في حياتكِ على وشك أن تبدأ!') WHERE id = '2d2b31a8-8f73-4858-b9b0-2f01ec75aada';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذه المرحلة، يحصل طفلكِ على الأكسجين والكربوهيدرات والدهون والبروتينات والفيتامينات والمعادن التي يحتاج إليها جسمه مباشرةً من جسمكِ عبر المشيمة. ومع ذلك، يكون جهازه الهضمي بأكمله قد تطوّر بما يكفي ليبدأ العمل منذ لحظة ولادته، كي يهضم الحليب ويستفيد من مكوناته في نموه. وفي كل يوم يقضيه طفلكِ داخل الرحم، يبتلع بفمه لترات من السائل الأمنيوسي ليدرّب جهازه الهضمي. ويُعد هذا "التدريب" بالغ الأهمية لضمان سير عملية الهضم بسلاسة بعد الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'لا تستمعي إلى الأقارب! 🙉 أعلم أن الجميع يتصلون ويسألونكِ: "ألم تلدي بعد؟" وهذا يرهقكِ، أليس كذلك؟ أخبريهم بأنني "ضيف VIP" وأنتظر اللحظة المثالية تمامًا للظهور على المسرح. ما عليكِ سوى الراحة وتجاهل هذه الأسئلة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تجدين صعوبة من وقت إلى آخر في ضبط وزنكِ وكبح شهيتكِ المتزايدة خلال الحمل. لكن عدم تناولكِ كمية كافية من الطعام خوفًا من اكتساب الوزن أمر غير صحي إطلاقًا. عليكِ ألا تنسي أن الأطعمة التي تتناولينها ذات أهمية حيوية لنمو طفلكِ. ولتزويده بالفيتامينات والمعادن اللازمة مع الحفاظ على وزنكِ تحت السيطرة، قللي خلال هذه الفترة من تناول الأطعمة الغنية بالكربوهيدرات، وفضّلي نظامًا غذائيًا غنيًا بالبروتين.;;;
يكفي أن تُنهي حملكِ بزيادة قدرها 10-12 كيلوغرامًا لضمان نمو طفلكِ بصحة جيدة. وهذه الأرقام هي قيم متوسطة؛ فقد تنخفض الزيادة إلى 6 كيلوغرامات أو ترتفع إلى 16 كيلوغرامًا وفقًا لمؤشر كتلة جسمكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد ترهقكِ في هذه الأيام أسئلة من حولكِ مثل: "ألم تلدي بعد؟". ابتسمي بلطف وذكّريهم بأن طفلكِ سيختار بنفسه أنسب وقت للولادة. حافظي على سلامكِ الداخلي.') WHERE id = '912237d6-e1bb-4ef4-b942-ca1a90b3bc59';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ابتداءً من اليوم الثالث بعد الولادة، تبدأ البكتيريا التي تُسمى «الميكروبيوتا» بالتكاثر سريعًا ضمن الفلورا المعوية التي تتكوّن في أمعاء طفلكِ. وتشارك ميكروبيوتا أمعاء طفلكِ في عمليات معقدة تحفّز تكاثر الخلايا التي تغطي الجدار الداخلي للأمعاء. ويزداد وزن هذه التجمعات البكتيرية، التي تُسمى الميكروبيوتا، بالتوازي مع نمو طفلكِ، ليصل إلى نحو 2 كيلوغرام عند بلوغه سن الرشد. تعمل هذه البكتيريا كحاجز واقٍ يمنع غزو الكائنات الحية الدقيقة الضارة والمسببة للأمراض لجسم طفلكِ. كما تساعد على هضم بعض الأطعمة التي لا يستطيع طفلكِ هضمها، وتنظّم وظائف جهازه المناعي. وتشارك هذه الميكروبيوتا الموجودة في الفلورا المعوية لطفلكِ، خصوصًا، في إنتاج الفيتامينات الذائبة في الدهون وبعض المواد التي يحتاج إليها الجسم. ونظرًا إلى احتواء الفلورا المعوية على ملايين البكتيريا ومواد ناقلة عصبية تفوق كميتها ما يوجد في الجهاز العصبي بـ9 أضعاف، فقد بدأ العلماء في السنوات الأخيرة يعدّونها عضوًا من أعضاء الجسم.'), baby_message_ar = COALESCE(baby_message_ar, 'مشيمتي ما زالت تعمل! 🔋 لعل الأطباء يفحصون السائل الأمنيوسي والمشيمة لديّ. كل شيء على ما يرام. ما زلت أتنفس وأتغذى من خلالكِ. نحن فريق واحد وسنبقى معًا حتى النهاية. لا تخافي، فأنا أنتظر الإشارة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'لقد وصلتِ إلى مرحلة متقدمة جدًا من حملكِ. ولهذا أصبح الاهتمام بتغذيتكِ أكثر أهمية. وبما أن الرحم الذي يحتضن طفلكِ، وقد أصبح كبيرًا بما يكفي، يضغط على أعضائكِ الداخلية، فقد يسبب لكِ بعض المشكلات في الجهاز الهضمي.;;;
يجب عليكِ تجنّب الأطعمة المقلية والحارة والغنية جدًا بالدهون، ولا سيما على العشاء، وتناول وجبات خفيفة لا تزعج معدتكِ. وتُعد أطباق الخضراوات على العشاء مفيدة جدًا، لكن عليكِ التأكد من طهي الخضراوات جيدًا، لأن الخضراوات غير الناضجة بما يكفي قد تزيد حرقة المعدة. كما ينبغي لكِ تقليل المشروبات الغازية والمحتوية على الكافيين، والفواكه شديدة الحموضة مثل الجريب فروت والبرتقال، أو تجنّبها تمامًا. واحرصي أيضًا على عدم الإفراط في تناول مشروبات مثل القهوة أو الشاي. حاولي تناول وجباتكِ ببطء ومن دون استعجال، وتجنّبي شرب السوائل أثناء الطعام لتقليل الانتفاخ إلى أدنى حد ممكن.'), daily_tip_ar = COALESCE(daily_tip_ar, 'خذي حمامًا دافئًا لتخفيف التوتر، ودعي الماء يمنح جسمكِ الاسترخاء. حاولي أن تتخيلي لحظة الولادة، لا بخوف، بل بفرحة اللحظة الأولى التي ستلتقين فيها بطفلكِ.') WHERE id = '1682ff26-3ced-4844-9a8e-8e67a40347cb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'نظرًا إلى ازدياد معدل حدوث بعض المضاعفات في حالات الحمل المتأخر، فمن المهم جدًا أن تنتبهي إلى بعض العلامات التي قد تظهر في جسمكِ. وقد تصبح مشكلات مثل انفصال المشيمة المبكر، أو خروج العِقي (البراز الأول) المتراكم في أمعاء طفلكِ إلى السائل الأمنيوسي ثم دخوله إلى رئتيه عبر مجرى التنفس، أكثر شيوعًا ابتداءً من الأسبوع 40 من الحمل.;;;
تُعرف حالة انفصال المشيمة التي تغذي طفلكِ عن جدار الرحم قبل الولادة باسم "انفصال المشيمة". ولأن هذا الانفصال قد يشكل خطرًا جسيمًا عليكِ وعلى طفلكِ، يجب عليكِ مراجعة الطبيب فورًا، كما هي الحال مع جميع حالات النزيف. وعلى الرغم من أن انفصال المشيمة المبكر نادر نسبيًا، فإنه يحدث في حالة واحدة من كل 200 حالة حمل. ومن أكثر علاماته شيوعًا نزيف مهبلي داكن اللون وغير متخثر، مصحوب بألم. وقد تظهر لديكِ أعراض انخفاض ضغط الدم والصدمة، ولا سيما في حالات الانفصال الشديد، كما قد يتدهور معدل ضربات قلب طفلكِ. لذلك، يجب عليكِ مراجعة الطبيب حتمًا إذا تعرضتِ لأي نزيف.'), baby_message_ar = COALESCE(baby_message_ar, 'أحلم... 💤 أنام معظم الوقت. تُرى، كيف يبدو وجهكِ؟ لقد أصبح صوتكِ مألوفًا جدًا لديّ. وأسمع صوت أبي أيضًا. صرت أراكما في أحلامي. وسيتحول هذا الحلم إلى حقيقة قريبًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'يساعدكِ التنفس بطريقة صحيحة وممارسة تمارين التنفس بانتظام على تخفيف المشكلات التي تواجهينها خلال الحمل، كما يساعدانكِ على خوض ولادة أكثر راحة.;;;
يحتاج جسمكِ، ولا سيما في هذه المرحلة من الحمل، إلى كمية من الأكسجين أكبر من أي وقت مضى. ويعمل التنفس الفعّال والجيد كمسكّن طبيعي للألم طوال فترة الحمل وأثناء الولادة، كما يساعد الجسم على الاسترخاء. ولأن تمارين التنفس تزيد كمية الأكسجين التي تصل إلى أعضائكِ، فقد تخفف إلى حد ما أعراضًا مثل حرقة المعدة، وعسر الهضم، والإمساك، والانتفاخ، والغازات. بالإضافة إلى ذلك، تؤثر تمارين التنفس العميق والبطيء والمنضبط إيجابيًا في الغثيان والدوار لديكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنا لا نزال ننتظر اليوم، فهذا يعني أن طفلكِ يُكمل استعداداته الأخيرة في رحمكِ. تحلّي بالصبر وثقي بجسمكِ. أنتِ امرأة قوية جدًا، وستجتازين كل شيء على أكمل وجه.') WHERE id = '5ae12c1c-33a8-4883-a677-24cfe3025ffd';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بحلول الأسبوع 38 من الحمل، تكون نحو %80 من الولادات قد حدثت بالفعل. لذلك، إذا لم تبدأ ولادتكِ بعد وقد دخلتِ الأسبوع 42، فقد تشعرين بتوتر شديد. والخبر السار هو أنه إذا لم تبدأ الولادة تلقائيًا حتى الأسبوع 42 في هذه المرحلة، التي تُسمى الحمل المتأخر، فيمكنكِ احتضان طفلكِ بعد تحفيز المخاض أو إجراء عملية قيصرية وفقًا لتوصية طبيبكِ. وعلى الرغم من أن حركات طفلكِ قد تكون مؤلمة جدًا من وقت إلى آخر، فقد تلاحظين انخفاض معدلها مقارنة بالأسابيع السابقة. فطفلكِ الآن في مكان أضيق من أي وقت مضى، ولذلك لم تعد لديه مساحة واسعة للحركة. عليكِ عدّ حركاته خلال اليوم، واستشارة طبيبكِ إذا لاحظتِ أنها أصبحت أقل بكثير من المعدل المتوقع. ويُعد انخفاض كمية السائل الأمنيوسي بدرجة ملحوظة خلال هذه الأسابيع أمرًا طبيعيًا. لكن إذا انخفضت كميته إلى حد يسبب ضغطًا على طفلكِ، فقد يتدخل طبيبكِ ويحفّز الولادة قبل إتمام الأسبوع 42.'), baby_message_ar = COALESCE(baby_message_ar, 'أهلًا بالأسبوع 41! 🎈 نعم، نحن نُعد رسميًا "متأخرين" (overdue). لكنني أفضل وصف ذلك بأنه "قيمة إضافية". لقد اختفت تقريبًا الطبقة الدهنية الشبيهة بالجبن (الطلاء الجُبني) تمامًا. قد تكون بشرتي جافة قليلًا عند ولادتي، لكنكِ سترطّبينها لي، أليس كذلك؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا لم تحدث الولادة حتى هذه المرحلة من حملكِ، ولم تظهر أي علامات تدل عليها، وكان وزن طفلكِ قد اقترب من الحد الأعلى، فيمكنكِ التحدث مع طبيبكِ بشأن العملية القيصرية.;;;
العملية القيصرية هي إجراء جراحي يُلجأ إليه عندما تتعذر الولادة الطبيعية، إذ يُفتح شق جراحي أسفل البطن بنحو عرض 4 أصابع، ثم يُخرج طفلكِ من خلاله. والقيصرية نوع من العمليات الجراحية، ولها بعض السلبيات مقارنة بالولادة الطبيعية، مثل الحاجة إلى التخدير وطول فترة التعافي. ولكن رغم هذه السلبيات، توجد حالات تكون فيها القيصرية الخيار الأفضل بسبب المضاعفات التي قد تنشأ عند محاولة الولادة الطبيعية، أو المشكلات التي قد يتعرض لها طفلكِ. وقد يُحتمل خضوعكِ لعملية قيصرية في حالات مثل عدم اتخاذ طفلكِ الوضع المناسب في قناة الولادة، أو عدم بدء انقباضات المخاض رغم بلوغ حملكِ موعده، أو إصابتكِ بمقدمات الارتعاج التي تُعرف أيضًا باسم "تسمم الحمل".;;;
وسواء كانت ولادتكِ طبيعية أم قيصرية، فلا تنسي أبدًا أنكِ في النهاية، وبعد مغامرة استمرت 9 أشهر، ستلتقين بطفلكِ. 😊'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تؤدي هرمونات التوتر إلى تأخير الولادة. لذلك، استمعي اليوم إلى الأخبار السارة فقط، وابتعدي عن الأشخاص والموضوعات التي تمنحكِ طاقة سلبية. صحتكِ النفسية الآن أهم من أي شيء آخر.') WHERE id = '7f952d08-70cf-40a7-af2e-4095f1619337';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ أكثر استعدادًا للعالم الخارجي من أي وقت مضى. فقد تطورت جميع أعضائه وأجهزته وأصبحت قادرة على أداء وظائفها بكفاءة عالية. وتواصل المشيمة الموجودة في رحمكِ إنتاج الأجسام المضادة لحماية طفلكِ من العدوى ومساعدته على مكافحة الأمراض بعد ولادته. وسيحتاج طفلكِ إلى بعض الوقت بعد الولادة حتى يتمكن من إنتاج أجسامه المضادة بنفسه.;;;
في هذه المرحلة، يُعد عدم اكتمال نمو الجهاز المناعي لطفلكِ وعدم قدرته على إنتاج أجسامه المضادة أمرًا بالغ الأهمية، إذ يمنع حدوث تفاعل ضار بين مستضدات جسمكِ ومستضدات طفلكِ.;;;
يبدأ الجهاز المناعي لطفلكِ بالتطور سريعًا منذ لحظة ولادته بفضل الرضاعة الطبيعية، ويستمر في التطور طوال مرحلة الطفولة.;;;
ومن خلال الحليب الذي تنتجه قنوات الحليب لديكِ، تدخل إلى جسم طفلكِ الأجسام المضادة المساعدة من نوع IgA، والأجسام المضادة للنمط المناعي، والخلايا اللمفاوية B وT، إلى جانب مكونات مفيدة مضادة للبكتيريا مثل اللاكتوفيرين.;;;
تُمتص جميع عناصر الجهاز المناعي هذه عبر الزغابات الموجودة في الأمعاء، ثم تنتقل إلى الدم والسائل اللمفاوي، وبذلك يبدأ تكوّن الجهاز المناعي بوتيرة سريعة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا ذكي جدًا! 🧠 يتطور دماغي بسرعة خلال هذه الأيام الأخيرة. جميع حواسي يقظة، فأنا أشعر بالضوء والصوت واللمس. وأشعر بحماسكِ أيضًا. اهدئي يا ماما. كل شيء يسير وفق الخطة (خطتي أنا 😉).'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'لكي تتم الولادة، يجب أن يتسع عنق الرحم بالكامل بما يسمح بمرور طفلكِ. إذا لم يبدأ اتساع عنق الرحم حتى هذه المرحلة من حملكِ، ولم يكشف تخطيط قلب الجنين وتقلصات الرحم (KTQ) عن وجود تقلصات، فهناك خياران أمامكِ: الولادة القيصرية أو تحفيز المخاض. الأوكسيتوسين هو الهرمون الذي ينشّط عضلات الرحم، أي إنه الهرمون الذي يبدأ المخاض. فهو يسبب انقباض عضلات الرحم ويولّد القوة التي تدفع طفلكِ إلى الأسفل. ومع ضغط رأس طفلكِ على عنق الرحم، يزداد الاتساع، وعندما يكتمل يمر طفلكِ عبر قناة الولادة ويأتي إلى العالم. عندما لا يفرز الجسم هرمون الأوكسيتوسين، يُعطى الأوكسيتوسين المعروف بمحفّز المخاض عبر محلول وريدي. ومع ارتفاع مستواه في الدم، تبدأ عضلات الرحم بالانقباض. وتستمر هذه المرحلة، مصحوبة بالتقلصات المنتظمة التي تشعرين بها، حتى يكتمل اتساع عنق الرحم. توجد عدة أسباب لتحفيز المخاض، منها بطء تقدم الولادة بدرجة كبيرة، وعدم بدء المخاض تلقائيًا عند تجاوز موعد الولادة، والتهابات الرحم، وارتفاع ضغط الدم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي النوم أبكر قليلًا هذا المساء. من المهم أن تدّخري طاقتكِ للولادة. رتّبي وسائدكِ بحيث يشعر جسمكِ براحة تامة. عسى أن تري ابتسامة طفلكِ في منامكِ!') WHERE id = '4884c66b-3927-4354-8b35-abb2fd62f234';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح جهاز الغدد الصماء لدى طفلكِ مستعدًا لتنظيم وظائف جسمه ومساعدته على التكيف مع العالم الخارجي بعد أن أمضى 9 أشهر في بيئة الرحم الآمنة. ومن هذه الهرمونات الكورتيزول، الذي يؤدي دورًا فعالًا في استقلاب الكربوهيدرات ويسبب درجة معينة من استجابة الجسم للتوتر. الكورتيزول هرمون ستيرويدي تُنتجه الغدة الكظرية لطفلكِ وتفرزه في الدم. ويساعد إنتاج هذا الهرمون جسم طفلكِ في أوقات التوتر. كما تسهم استجابة التوتر التي يسببها الكورتيزول في تقوية قلب طفلكِ وعضلات جسمه ودماغه إلى حد ما. وبفضل ذلك، يحتاج طفلكِ إلى مساعدة أقل للتكيف والبقاء بعد ولادته.;;;
يحفّز الكورتيزول، الذي يُفرز خصوصًا أثناء الولادة، إفراز الأدرينالين أيضًا، وهو هرمون آخر يرتبط بالتوتر. ويمنح الأدرينالين طفلكِ الطاقة والقدرة على الحركة. وتساعد هذه الطاقة طفلكِ بكل الطرق الممكنة على التكيف مع بيئته الجديدة أثناء الولادة وفي الساعات الأولى من لقائه بالعالم الخارجي.'), baby_message_ar = COALESCE(baby_message_ar, 'حقيبتي جاهزة! 🧳 أنا مستعد تمامًا. رئتاي مستعدتان لأخذ أول نفس، ومعدتي مستعدة لحليب الأم. أنا فقط أنتظر أن «يُفتح الباب». ما رأيكِ في الخروج لنزهة قصيرة؟ فقد يساعدني ذلك على إيجاد الطريق.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا لم تحدث ولادتكِ بعد، فقد تشعرين بإرهاق شديد. وقد تزيد الليالي المتتالية التي قضيتِها بلا نوم بسبب التوتر والقلق من شعوركِ بالتعب. إذا لاحظتِ خروج الحليب من حلمتيكِ في هذه المرحلة، فهذا ناتج عن تأثير الهرمونات التي تهيئ ثدييكِ للرضاعة الطبيعية.;;;
إذا أكملتِ مدة الحمل البالغة 40 أسبوعًا ولم تبدأ الولادة، فقد يتعرض طفلكِ لمشكلة شفط العقي. تحدث هذه المشكلة عندما يطرح طفلكِ، قبل ولادته، برازه الأول المتراكم في أمعائه، والذي يُطرح عادةً خلال أول 24 ساعة بعد الولادة، وذلك بسبب تعرضه للتوتر أو انخفاض الأكسجين. وقد يشكل هذا البراز خطرًا إذا استنشقه طفلكِ ووصل إلى رئتيه. ولأن العقي لزج القوام، فقد يعيق التنفس عند دخوله إلى الرئتين. وتُسمى هذه الحالة شفط العقي. وعندما يطرح طفلكِ العقي، يتحول لون السائل الأمنيوسي إلى الأخضر. لذلك، تحققي من إفرازاتكِ باستمرار، وإذا لاحظتِ انخفاضًا ملحوظًا في حركات طفلكِ، فتوجهي فورًا إلى أقرب منشأة طبية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اطلبي من زوجكِ أو أحد المقرّبين منكِ أن يدلّك كتفيكِ برفق. فالراحة التي تمنحكِ إياها اللمسات سترفع مستوى الأوكسيتوسين (هرمون الحب) في جسمكِ وتساعد على تسهيل الولادة.') WHERE id = 'acaaba70-7d7b-40eb-88be-941234cfb162';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد تكون مشيمة طفلكِ قد بدأت بالتقدم في العمر نتيجة تجاوز مدة الحمل المتوقعة. ولا يسبب هذا التقدم مشكلة ما دامت المشيمة توفر لطفلكِ كمية كافية من الأكسجين ولا تعيق زيادة وزنه. المشيمة هي العضو الذي يضمن تبادل جميع المواد بين جسمكِ وطفلكِ طوال فترة الحمل. وتتكون وتتطور في مرحلة مبكرة جدًا بعد الإخصاب، ثم تنفصل عن الرحم وتخرج بعد ولادة طفلكِ بوقت قصير. يبلغ وزن المشيمة التي تنفصل بعد الولادة نحو 500 غرام، ويتراوح قطرها بين 20-25 سم، وسماكتها بين 2-3 سم، ويكون شكلها مسطحًا. ويُعد تقدم المشيمة في العمر أمرًا طبيعيًا، خصوصًا بعد الأسبوع 36 من الحمل. وفي الواقع، فإن الحالة المعروفة باسم شيخوخة المشيمة هي تراكم معادن الكالسيوم فيها.'), baby_message_ar = COALESCE(baby_message_ar, 'ربما نحتاج إلى بعض المساعدة؟ 🩺 قد يتحدث الأطباء عن بدء المخاض (التحريض). لا تخافي. أريد أن آتي، لكن الطبيعة تحتاج أحيانًا إلى دفعة صغيرة. وبغض النظر عن طريقة قدومي، فإن الأهم هو أننا سنلتقي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تبدأ شكواكِ من ضيق التنفس مع بداية الثلث الثاني من الحمل، ثم تزداد بشكل ملحوظ خلال الثلث الثالث. فنتيجة ارتفاع عضلة الحجاب الحاجز إلى الأعلى، تتعرض رئتاكِ للضغط. ومع ضيق المساحة المتاحة لهما، تقل كمية الهواء التي تستطيعان استيعابها. لذلك قد يصبح التنفس صعبًا للغاية، وينشأ شعور يُعرف باسم «الجوع إلى الهواء».;;;
يمكن تقليل صعوبة التنفس، التي تعاني منها معظم النساء تقريبًا خلال الحمل، بدرجة كبيرة من خلال ممارسة تمارين التنفس التي تقوّي عضلة الحجاب الحاجز. كما تساعدكِ ممارسة تمارين التنفس بانتظام على زيادة سعة رئتيكِ ورفع كمية الأكسجين الواصلة إلى طفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا شعرتِ اليوم بأي تقلص، فلا تخافي. فكل تقلص هو «موجة» تقرّبكِ خطوة أخرى من طفلكِ. اركبي هذه الموجة بثقة ولا تستسلمي للخوف.') WHERE id = '39da3e28-3bb4-466f-a4b2-49f4aa6296da';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من اكتمال المدة اللازمة للولادة في هذا الأسبوع من حملكِ، فقد تحول بعض العوامل الفسيولوجية دون حدوثها، ما قد يؤدي إلى تأخر ولادتكِ. لكن خلال هذه الفترة، يواصل طفلكِ النمو والتطور. وعندما يولد طفلكِ في الأسبوع 42 من الحمل، قد تلاحظين أن شعره وأظافره طويلان جدًا. وبما أنه يولد متأخرًا عن أقرانه بنحو 2-3 أسابيع، فعادةً ما تكون عيناه مفتوحتين ويكون أكثر يقظةً مقارنةً بهم. كما تكون جميع ردود أفعاله، ولا سيما منعكس المص، أكثر تطورًا مقارنةً بغيره من الأطفال حديثي الولادة، ولذلك يكون أكثر نشاطًا. ومع ذلك، ونظرًا إلى المخاطر المرتبطة بالحمل في الأسبوع 42، قد يطلب منكِ طبيبكِ الحضور للفحص مرة كل يومين على أقصى تقدير لمراقبة طفلكِ عن كثب. ويُجرى فحص الحمل في الأسبوع 42 لتقييم حالة طفلكِ بناءً على مؤشرات مثل التصوير بالموجات فوق الصوتية، وتخطيط قلب الجنين، وعدّ حركاته، وكمية السائل الأمنيوسي.'), baby_message_ar = COALESCE(baby_message_ar, 'أشعر بكِ... ❤️ أعلم أن صبركِ أوشك على النفاد. ظهري يؤلمني وقدماكِ متورمتان. لم يتبقَّ سوى القليل يا ماما، أعدكِ. ستنسين كل هذه الصعوبات عندما تضمينني إلى صدركِ. أنتِ أقوى امرأة في العالم!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا لم تبدأ انقباضات المخاض لديكِ بصورة طبيعية، فقد يجري طبيبكِ الولادة بعملية قيصرية، لأن بعض المشكلات المتعلقة بكِ أو بطفلكِ قد تؤدي إلى مضاعفات أثناء الولادة الطبيعية.;;;
تُجرى ولادتكِ بعملية قيصرية في حال انخفاض معدل نبض طفلكِ بسبب نقص الأكسجين أثناء انقباضات الرحم، أو تموضع المشيمة بحيث تغطي عنق الرحم، أو عدم ملاءمة وضعية طفلكِ للولادة الطبيعية، أو تدلّي جزء من الحبل السري عبر عنق الرحم، أو وجود مشكلات في عنق الرحم قد تعيق الولادة الطبيعية، مثل الأورام الليفية أو الهربس التناسلي أو العدوى.;;;
وفي هذه الحالات أيضًا، لا يمكن استخدام الطلق الصناعي، وهو الشكل الاصطناعي من هرمون الأوكسيتوسين الذي تفرزه الغدة النخامية الموجودة في مقدمة الدماغ ويحفّز بدء انقباضات المخاض.;;;
إذا كنتِ ستخضعين لعملية قيصرية، فسيخدّركِ طبيب التخدير تخديرًا عامًا أو نصفيًا في المرحلة الأولى. وبعد إجراء شق عبر 7 طبقات تشمل الجلد، والأنسجة تحت الجلد، واللفافة، والجدار الأمامي للبطن، والصفاق الخارجي، والصفاق الداخلي، وعضلات الرحم، يجري الوصول إلى الكيس الأمنيوسي الذي يوجد طفلكِ بداخله.;;;
يفتح الطبيب هذا الكيس ثم يُخرج طفلكِ. وبعد قطع الحبل السري ونقل طفلكِ جانبًا، تُستخرج المشيمة ويُنظَّف الرحم. وفي المرحلة الأخيرة، تُخاط الطبقات السبع التي فُتحت بطريقة صحيحة وتجميلية، وبذلك تكتمل العملية القيصرية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ردّدي لنفسكِ كثيرًا: "أنا مستعدة، جسدي مستعد، وطفلي مستعد". تساعد التأكيدات الإيجابية على رفع عتبة تحمّل الألم وخوض تجربة الولادة بصورة أكثر إيجابية.') WHERE id = '3c9f9854-9405-4f6e-90ed-de351c308dea';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال الأسبوع 42 من الحمل، يُرجح أن تكون بشرة طفلكِ قد بدأت بامتصاص طبقة الطلاء الجبني ذات اللون الأصفر الفاتح التي تغطي جسمه. والطلاء الجبني طبقة واقية رقيقة يبدأ إنتاجها في الثلث الثالث من الحمل، وتتكون بنسبة 80% من الماء، كما تحتوي على كميات وفيرة من الدهون والبروتينات. ويختلف توزيع الطلاء الجبني على سطح الجلد وفقًا لأسبوع الحمل ونوع الولادة ووزن الجسم. ويحتوي الطلاء الجبني على مادة الليزوزيم التي تتميز بقدرتها على القضاء على الميكروبات، كما يحتوي على خلايا دفاعية تحمي من نوع من البكتيريا قد يضر بالرئتين ويسبب التهابهما. وتضم هذه الطبقة الكريمية أيضًا نحو 40 نوعًا مختلفًا من البروتينات التي تدعم المناعة الطبيعية في جسم طفلكِ.;;;
لكن نتيجةً للتأثيرات السلبية لتأخر الحمل، تكون البشرة قد امتصت جزءًا كبيرًا من هذه الطبقة قبل موعد الولادة. وقد يسبب امتصاص طبقة الطلاء الجبني بعض الجفاف على سطح بشرة طفلكِ في هذه المرحلة. ومع انخفاض كمية السائل الأمنيوسي، قد يؤدي هذا الجفاف أيضًا إلى تقشر الجلد وانسلاخه في بعض المناطق.'), baby_message_ar = COALESCE(baby_message_ar, 'أنتظر الإشارة الكبرى! 🚦 يزيد جسدكِ من إفراز هرمونات الولادة (الأوكسيتوسين). وأنا أيضًا أضغط برأسي إلى الأسفل. قد تبدأ الانقباضات في أي لحظة. هل حقيبتكِ عند الباب؟ أظن أن موعد الذهاب إلى المستشفى قد اقترب.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا لم تكن لديكِ في هذه المرحلة أي مشكلة تستدعي إجراء عملية قيصرية، فقد يرغب طبيبكِ في تحفيز الولادة باستخدام الطلق الصناعي. في الظروف الطبيعية، عندما تقتربين من الأسابيع الأخيرة من حملكِ، يحفّز هرمون الأوكسيتوسين الذي تفرزه الغدة النخامية في دماغكِ عضلات الرحم على الانقباض. وتؤدي هذه الانقباضات إلى اتساع عنق الرحم تدريجيًا. وعندما يتسع عنق الرحم بالكامل، تبدأ المرحلة الأساسية من الولادة ويمر طفلكِ عبر قناة الولادة. لكن قد لا يُفرز هرمون الأوكسيتوسين في دماغكِ لأسباب غير معروفة، وبالتالي قد لا تبدأ انقباضات المخاض.;;;
الطلق الصناعي هو بدء الولادة الطبيعية باستخدام الأدوية عندما لا يبدأ المخاض تلقائيًا لأسباب معينة. ويتكون الدواء المستخدم في الطلق الصناعي من هرمون الأوكسيتوسين الذي يحفّز عضلات الرحم على الانقباض، ومن ثم بدء الولادة. ويُستخدم هذا الإجراء، الذي يُسمى "تحريض المخاض"، لمساعدة الأطفال الذين اكتملت مدة حملهم لكنهم ما زالوا في الرحم على الولادة طبيعيًا (عن طريق المهبل). كما قد يستخدم طبيبكِ هذه الطريقة لتسريع الولادة إذا بدأت لديكِ انقباضات المخاض، لكن اتساع عنق الرحم لا يتقدم بالسرعة الكافية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لقد وصلنا إلى نهاية الرحلة وبداية اللقاء. استريحي اليوم فحسب. ولتكن كل دعواتكِ وأمنياتكِ مع طفلكِ. لم يتبقَّ سوى القليل جدًا؛ تفصلكِ ساعات عن استنشاق تلك الرائحة الساحرة.') WHERE id = '9ac98c98-32af-413c-ad09-92ec7b838b44';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'إذا لم تحدث ولادتكِ حتى هذه المرحلة، فستلتقين بطفلكِ ابتداءً من اليوم. 😊 توجد بعض العلامات التي تؤكد بدء المخاض. وإذا ظهرت لديكِ إحدى هذه العلامات، فعليكِ التواصل مع طبيبكِ فورًا من دون إضاعة الوقت. قد تخرج هذه البنية، التي تُسمى "السدادة المخاطية" أو "علامة الولادة"، من الجسم قبل الولادة بأسابيع أو قبلها بساعات. وهي تحمي عنق الرحم من الكائنات الدقيقة الضارة طوال الحمل، ما يساعد على بقاء السائل الأمنيوسي معقمًا. ويُعد خروج هذه الإفرازات المخاطية الكثيفة الممزوجة بالدم علامةً على أن عنق الرحم يستعد للولادة.;;;
تُعد الانقباضات المنتظمة التي تزداد شدة ألمها مع الوقت أوضح علامة على بدء المخاض. وتكون هذه الانقباضات أشد من انقباضات المخاض الكاذب، وتساعد على اتساع عنق الرحم بسرعة.;;;
أما إذا نزل السائل الأمنيوسي (ماء الجنين)، فعليكِ الذهاب إلى الطبيب فورًا من دون إضاعة الوقت. وقد ينزل هذا السائل على شكل تدفق سريع أو تسرب بسيط. ويشير نزول السائل الأمنيوسي إلى أنه لم تتبقَّ سوى ساعات على ولادتكِ. 😊'), baby_message_ar = COALESCE(baby_message_ar, 'هل هذه آخر 24 ساعة؟ ⏳ أوشك الأسبوع 42 على الانتهاء. ومن الناحية الطبية، لا بد أن نلتقي الآن. لقد اشتقت إليكِ أنا أيضًا. لا أطيق الانتظار للانتقال من عالمي المظلم إلى عالمكِ المضيء. استعدّي، سنلتقي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بطيخة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'مع اكتمال الأسبوع 42، يُفترض أن تكون ولادتكِ قد حدثت بالفعل. وبعد مغامرة طويلة ومتعبة استمرت 9 أشهر، التقيتِ بطفلكِ. 😊 نحن أسرة Anacan نهنئكِ أنتِ وزوجكِ، ونتمنى لكما ولطفلكما حياةً طويلةً وصحيةً وسعيدة. شكرًا لدعمكِ لنا طوال هذه المدة. نلتقي في قسم "الأم" من تطبيقنا!'), daily_tip_ar = COALESCE(daily_tip_ar, 'اليوم هو يوم تحقق المعجزة. عندما تضمين طفلكِ إلى صدركِ، سيزول كل تعبكِ. والآن خذي نفسًا عميقًا واستمتعي بهذه اللحظة التاريخية. لقد نجحتِ!') WHERE id = '67f8b3d3-cbfc-4995-af5b-fd9e49e105ef';

