UPDATE public.safety_items SET name_ar = COALESCE(name_ar, 'جبن موتال'), description_ar = COALESCE(description_ar, 'قد يكون مصنوعًا من الحليب غير المبستر ويحتوي على نسبة عالية من الملح. كوني حذرة.') WHERE id = '16141dbb-2ea0-46a1-92bb-a4a9cbc211bd';
