UPDATE public.safety_items SET name_ar = COALESCE(name_ar, 'التعرّض لأشعة الشمس'), description_ar = COALESCE(description_ar, 'يُعدّ التعرّض المعتدل لأشعة الشمس آمنًا عمومًا، ويساعد على إنتاج فيتامين D. لكن التعرّض لفترة طويلة قد يسبب الجفاف وضربة الشمس وحروق الشمس، مما قد يكون مزعجًا وربما ضارًا. يُنصح بالحد من التعرّض المباشر لأشعة الشمس، خاصة خلال ساعات الذروة (من الساعة 10 صباحًا حتى 4 مساءً)، وارتداء ملابس واقية، واستخدام واقي الشمس، وزيادة تناول السوائل.') WHERE id = '3982c1ae-13f7-4142-8726-4f0481aa7c58';
