UPDATE public.safety_items SET name_ar = COALESCE(name_ar, 'السفر بالطائرة'), description_ar = COALESCE(description_ar, 'تُعد الرحلات الجوية على متن شركات الطيران التجارية آمنة عمومًا خلال فترة الحمل. ومع ذلك، يُنصح باستشارة طبيبكِ قبل السفر، وخاصة قبل الرحلات الطويلة، حتى في حال عدم وجود أي مشكلات مرتبطة بالحمل. اشربي كمية وفيرة من الماء، وتحركي للوقاية من تجلط الدم، واستخدمي الجوارب الضاغطة إذا أوصى بها طبيبكِ. تنطبق هذه التوصيات أيضًا على الأمهات المرضعات، لكن قد يكون من المفيد إجراء تحضيرات إضافية لتغذية رضيعكِ وراحته خلال الرحلات الطويلة.') WHERE id = 'b0855f6d-792e-4d72-a4d4-3509c5e9f5a1';
UPDATE public.safety_items SET name_ar = COALESCE(name_ar, 'السلمون'), description_ar = COALESCE(description_ar, 'مصدر لأحماض أوميغا-3. يُنصح بتناوله مطهوًا جيدًا بما لا يزيد على مرتين أسبوعيًا.') WHERE id = 'b0c7bfda-4110-4f88-8a68-a6303d1447c6';
UPDATE public.safety_items SET name_ar = COALESCE(name_ar, 'ركوب الطائرة'), description_ar = COALESCE(description_ar, 'تُعد الرحلات الجوية التجارية آمنة عمومًا خلال فترة الحمل. يُنصح باستشارة طبيبكِ بشأن السفر بالطائرة، وخاصة خلال الثلث الثالث من الحمل، واتخاذ احتياطات مثل شرب كمية وفيرة من الماء والتحرك للوقاية من تجلط الدم. تنطبق هذه التوصيات أيضًا على الأمهات المرضعات، لكن ينبغي إجراء تحضيرات إضافية لتغذية رضيعكِ وراحته خلال الرحلات الطويلة.') WHERE id = 'b1a7ab3d-fa21-4a98-ae31-159ea5e65822';
UPDATE public.safety_items SET name_ar = COALESCE(name_ar, 'السجق التركي'), description_ar = COALESCE(description_ar, 'يُعد السجق التركي آمنًا عمومًا خلال فترة الرضاعة الطبيعية عند تناوله باعتدال، لكن من المهم مراعاة محتواه المرتفع من الصوديوم والدهون. كما قد تؤثر الأطعمة الحارة أحيانًا في رضيعكِ عن طريق حليب الأم، مما قد يسبب له الانزعاج أو مشكلات في الهضم. راقبي استجابة رضيعكِ.') WHERE id = 'b4267eb3-6e6a-46f3-93ce-1dab05fea063';
UPDATE public.safety_items SET name_ar = COALESCE(name_ar, 'المشدّ (الحزام الداعم)'), description_ar = COALESCE(description_ar, 'يخفف آلام الظهر، فارتديه بعد استشارة الطبيب.') WHERE id = 'ce5d270b-9ea1-4416-b1ff-dde38b8ca2f7';
